insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('c13603c5-2e1e-57c0-8c5c-2b288e93d0f3'::uuid, 'bec9b5c7-dbe5-511e-af03-6cff8ae3056a'::uuid, 'linkedin', null, 'C', 'en', 'Sunscreen sold in the United States is not a cosmetic. It sits under FDA''s OTC drug monograph system, and Monograph M020 is the one that governs it.', '{"en":{"linkedin":"Sunscreen sold in the United States is not a cosmetic. It sits under FDA''s OTC drug monograph system, and Monograph M020 is the one that governs it.\n\nA recent WTO TBT notification confirms FDA has finalised amendments to M020, this time touching two active ingredients: Aminobenzoic Acid (PABA) and Trolamine Salicylate. Because this is a final action, there is no comment window attached.\n\nFor a Malaysian brand shipping SPF products into the US, this matters more than the label copy. Your formulation has to sit inside what the monograph still permits. If your UV filter is not on the current M020 list, or the concentration falls outside its limits, it does not matter how clean your NPRA notification looks at home. FDA does not accept cosmetic-style self-declaration for sunscreen actives.\n\nCheck your actives against the current monograph before you check your claims.\n\nSources: WTO/TBT Notification G/TBT/N/USA/1443/Add.6 (15/09/2026); US FDA OTC Monograph M020 (Sunscreen Drug Products).\n\n#RegulatoryAffairs #Sunscreen #WTOTBT #FDA #ASEANExport"}}'::jsonb, 'WTO/TBT Notification G/TBT/N/USA/1443/Add.6 (15/09/2026); US FDA OTC Monograph M020', '[]'::jsonb, '2026-09-19'::date, '06:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7506948052470001664","at":"2026-09-19 13:42 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7506948052470001664/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-19 13:42:00+08'::timestamptz, now(), '2026-09-17T15:49:49.787Z'::timestamptz) on conflict (id) do nothing;  -- 1sca6ogvx0 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('1ef6ab08-d553-581b-bd95-f81941e1ab3e'::uuid, '8f794e1b-5fa5-574c-9a31-ff8d0ac41d77'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Chomel Hand Sanitizer hilang notifikasi NPRA sebab methanol. Bukan sebab formula dia salah.', '{"bm":{"instagram":"Chomel Hand Sanitizer kena batal notifikasi NPRA sebab kandungan methanol melebihi had dibenarkan.\n\nRamai pengusaha hand sanitizer masih anggap produk mereka bukan kosmetik sebab nampak macam produk kebersihan tangan biasa, bukan skincare. Hakikatnya, hand sanitizer jatuh terus bawah rejim notifikasi kosmetik NPRA, sama macam lotion atau sabun muka.\n\nYang SME selalu terlepas pandang: methanol dalam kes macam ni bukan ramuan yang sengaja dimasukkan dalam formula. Ia masuk sebagai bendasing dalam ethanol gred rendah atau denatured alcohol yang murah. Bila NPRA jumpa masalah, ia bukan salah formulator, ia salah bahan mentah yang tak dikawal masa pembelian.\n\nDi bawah ASEAN Cosmetic Directive Annex III, methanol (CAS 67-56-1) hanya dibenarkan sebagai denaturant untuk ethanol dan isopropyl alcohol, maksimum 5% dikira daripada peratusan ethanol dan isopropyl alcohol itu sendiri, bukan had bebas ke atas produk siap.\n\nKalau anda beli ethanol tanpa Certificate of Analysis untuk setiap batch, anda tak ada apa-apa untuk ditunjuk bila soalan ini datang. Spesifikasi bahan mentah dan CoA pembekal itulah kawalan sebenar, bukan apa yang tertulis dalam fail notifikasi anda.\n\nNPRA tak siarkan bacaan sebenar yang dikesan dalam senarai pembatalan, jadi jangan reka angka bacaan. Had 5% dalam Annex III itu sudah cukup untuk terangkan kenapa ethanol murah yang tak disaring boleh jatuhkan seluruh batch.","facebook":"Chomel Hand Sanitizer kena batal notifikasi NPRA sebab methanol melebihi had dibenarkan.\n\nRamai sangka hand sanitizer bukan kosmetik sebab ia nampak macam produk kebersihan. Hakikatnya ia bawah rejim notifikasi kosmetik NPRA juga.\n\nMethanol di sini bukan ramuan yang sengaja dimasukkan, ia bendasing dalam ethanol murah atau denatured alcohol. Bawah ASEAN Cosmetic Directive Annex III, methanol hanya dibenarkan sebagai denaturant, maksimum 5% daripada kandungan ethanol dan isopropyl alcohol, bukan had bebas pada produk siap.\n\nTanpa Certificate of Analysis setiap batch ethanol dari pembekal, anda tak ada apa nak tunjuk bila NPRA tanya. Itu kawalan sebenar, bukan formula.","threads":"Chomel Hand Sanitizer kena batal notifikasi NPRA sebab methanol lebih had. Hand sanitizer pun kosmetik bawah NPRA, ramai lupa. Methanol biasanya bendasing dalam ethanol murah, bukan sengaja ditambah. ASEAN Cosmetic Directive Annex III: methanol hanya sebagai denaturant, max 5% daripada ethanol dan isopropyl alcohol, bukan had bebas produk siap. Tanpa CoA ethanol setiap batch, anda tak boleh buktikan apa-apa."}}'::jsonb, 'ASEAN Cosmetic Directive Annex III, Release 2023-1, 5 Jun 2023 (asean.org); NPRA Senarai Pembatalan Produk Kosmetik Bernotifikasi, 19 Sept 2026.', '[]'::jsonb, '2026-09-23'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab1b12e826cfc54b85d970b","at":"2026-09-22 06:35 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab1b14074d4ff403e12ed44","at":"2026-09-22 06:35 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab1b14f74d4ff403e12eed0","at":"2026-09-22 06:35 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-22 06:35:00+08'::timestamptz, now(), '2026-09-20T09:45:39.711Z'::timestamptz) on conflict (id) do nothing;  -- 2gw1yxs4an (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('a2f6bcf5-3572-5519-9d91-b5a9840c5f7b'::uuid, '735df675-affc-5ec6-8843-14b8094bb629'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Silap yang saya jumpa berulang kali: ''produk 100% Islam'' pada kosmetik disangka bukti ia selamat.', '{"bm":{"instagram":"Silap yang saya nampak berulang kali bila handle file kosmetik SME.\n\nBranding pengasas Muslim atau tagline ''produk 100% Islam'' pada kosmetik itu cerita pemasaran. Tak ada kaitan dengan sama ada produk lulus notifikasi NPRA, atau sama ada ia mengandungi merkuri melebihi had.\n\nAda kes produk begini didapati mengandungi merkuri, bahan dilarang terus di bawah Annex II ruj. 406, bukan sekadar berhad, sebab pengeluar guna kilang tanpa GMP untuk jimat kos. Nama pengasas atau identiti agama tak ubah apa yang berlaku dalam formulation.\n\nBukti keselamatan yang sah cuma dua: notifikasi NPRA yang valid, dan ujian logam berat untuk batch berkenaan. Itu saja yang boleh ditunjuk semasa audit atau recall.\n\nPisahkan dalam kepala anda: branding untuk jual, notifikasi dan GMP untuk buktikan selamat. Yang kedua tak boleh diganti dengan yang pertama.","facebook":"Silap yang selalu saya jumpa: anggap ''produk 100% Islam'' atau identiti pengasas Muslim pada kosmetik sama dengan produk itu selamat.\n\nDua benda berbeza. Branding untuk jual. Notifikasi NPRA dan ujian logam berat untuk buktikan selamat.\n\nAda kes produk begini didapati mengandungi merkuri, bahan dilarang terus di bawah Annex II ruj. 406, sebab kilang tanpa GMP dipakai untuk jimat kos. Label agama atau bangsa tak ubah apa yang berlaku dalam formulation.\n\nJangan biar branding jadi ganti kepada notifikasi yang sah.","threads":"''Produk 100% Islam'' bukan bukti kosmetik selamat. Notifikasi NPRA dan ujian logam berat yang bukti. Ada brand macam ni kena merkuri lebih had sebab kilang tanpa GMP. Branding untuk jual, bukan untuk lulus."}}'::jsonb, 'Cosmetic Regulations, Annex II ref 406', '[]'::jsonb, '2026-09-11'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa40179262bdff0e87c0476","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa4018ea3aa88881a36228f","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa401c132d420cab6f54488","at":"2026-09-11 21:28 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:28:00+08'::timestamptz, now(), '2026-09-08T05:53:48.961Z'::timestamptz) on conflict (id) do nothing;  -- 3pq7yp7qpa (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('f4d25131-5dcd-53f3-957e-aadf6e9f4abe'::uuid, null, 'linkedin', null, 'E', 'en', 'Four Hairfiller Instant Dye Shampoo products were recalled in Sweden for p-phenylenediamine (PPD). PPD is not banned. It is restricted.', '{"en":{"linkedin":"Four Hairfiller Instant Dye Shampoo products were recalled in Sweden for p-phenylenediamine (PPD). PPD is not banned. It is restricted.\n\nPPD sits in Annex III of the EU Cosmetics Regulation, the restricted list, not Annex II, the prohibited list. It has a maximum concentration on the scalp after mixing, plus mandatory warnings on sensitisation, patch testing and staining.\n\nThe common mistake is treating Annex III like Annex II. A banned substance has no safe concentration. A restricted one has a legal concentration and conditions, and the product is compliant only when both the number and the warning are correct.\n\nInstant and gradual dyes marketed to sit outside the oxidative hair dye category still carry PPD sometimes, at a level or with warnings never checked against Annex III''s actual entry.\n\nThe real question for a supplier is not whether PPD is present. It is whether concentration and warning match the entry that permits it.\n\nSources: EU Safety Gate alert, Hairfiller Instant Dye Shampoo, notified by Sweden, 17-18 September 2026; EU Cosmetics Regulation (EC) No 1223/2009, Annex III\n\n#CosmeticRegulation #HairDye #PPD #RegulatoryAffairs #EUCosmeticsRegulation"}}'::jsonb, 'EU Cosmetics Regulation (EC) No 1223/2009, Annex III; EU Safety Gate alert, 17-18 Sept 2026', '[]'::jsonb, '2026-09-26'::date, '06:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7509377370454233088","at":"2026-09-26 06:24 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7509377370454233088/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-26 06:24:00+08'::timestamptz, now(), '2026-09-19T13:45:00.000Z'::timestamptz) on conflict (id) do nothing;  -- 4rfdpr1gj2 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('65a01ccb-e795-52fc-b54c-9c665af6febf'::uuid, '7d9b1b04-e54e-5311-90c2-5fe47ef411c0'::uuid, 'linkedin', null, 'B', 'en', 'A lot of brand owners and even some formulators think the halal assurance obligation stops at their own name on the label. If you use a maklon (contract manufacturer) or a shared production kitchen, you assume that''s their problem, not yours, or that nobody''s problem until the finished good is packe', '{"en":{"linkedin":"A lot of brand owners and even some formulators think the halal assurance obligation stops at their own name on the label. If you use a maklon (contract manufacturer) or a shared production kitchen, you assume that''s their problem, not yours, or that nobody''s problem until the finished good is packed.\n\nBPJPH''s draft Keputusan Ketua BPJPH on SJPH guidelines changes that. It puts the Sistem Jaminan Produk Halal requirement directly on the processing service itself: maklon, dapur kongsi, and other outsourced processing operations, whether they''re making cosmetics, food, beverages or medicine.\n\nPractically, that means the toll manufacturer needs its own documented halal assurance system, not a borrowed certificate from the brand it''s packing for. Segregation, cleaning validation between batches, raw material traceability, all of it now sits with whoever is running the vat or the filling line, not just whoever owns the SKU.\n\nPublic feedback on the draft closes 23 Nov 2026. If you run or use contract manufacturing for cosmetics into Indonesia, this is the document to read before then, not after.\n\nSources: BPJPH, Draft Keputusan Ketua BPJPH tentang Pedoman SJPH bagi Jasa Maklon dan sejenisnya (public consultation)\n\n#HalalCompliance #BPJPH #Cosmetics #RegulatoryAffairs #ASEAN"}}'::jsonb, 'BPJPH, Draft Keputusan Ketua BPJPH tentang Pedoman SJPH bagi Jasa Maklon dan sejenisnya (public consultation, closing 23 Nov 2026)', '[]'::jsonb, '2026-09-27'::date, '06:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7509741951643037696","at":"2026-09-27 06:33 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7509741951643037696/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-27 06:33:00+08'::timestamptz, now(), '2026-09-24T17:53:02.013Z'::timestamptz) on conflict (id) do nothing;  -- 63ka8uyadu (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('4f79ce9d-8dbb-5966-9b96-c373ac9c7790'::uuid, '31f769b8-f8c4-5cf2-8630-a7e52d5c4010'::uuid, 'linkedin', null, 'D', 'en', 'Vitamin C serums love to say ''ascorbic acid is CIR-approved''. That phrase alone tells you nothing about today''s formula.', '{"en":{"linkedin":"Vitamin C serums love to say ''ascorbic acid is CIR-approved''. That phrase alone tells you nothing about today''s formula.\n\nCIR''s review of ascorbic acid and ascorbates was never meant to be a one-time clearance. CIR''s own process builds in periodic re-review of ingredients already in commerce, because new data on stability, concentration and use patterns can shift the safety conclusion years after the first review closed.\n\nWhat that means for a brand: your ''our vitamin C is stable and safe'' claim should sit on the current re-review conclusion and the concentration range it actually covers, not on the fact that the ingredient passed review decades ago.\n\nThe same logic applies locally. An NPRA notification showing ''active'' status confirms the product cleared submission once. It does not confirm the formula still matches the current permitted ingredient list or concentration limit.\n\nCheck what the latest review actually supports for your specific use level. Status alone is not data.\n\nCIR''s 2026 Re-Review Summary for ascorbic acid and ascorbates - May 16, 2025 (issued for Panel approval ahead of the June 9–10, 2025 meeting)\n\nSources: Cosmetic Ingredient Review (CIR), Re-Review Summary, ascorbic acid and ascorbates; NPRA cosmetic notification system, product status definitions.\n\n#CosmeticRegulatory #VitaminC #CIR #NPRA #RegulatoryAffairs"}}'::jsonb, 'Cosmetic Ingredient Review (CIR), Re-Review Summary, ascorbic acid and ascorbates (date unverified); NPRA cosmetic notification system, product status definitions', '[]'::jsonb, '2026-09-25'::date, '19:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7509377259116613633","at":"2026-09-26 06:24 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7509377259116613633/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-26 06:24:00+08'::timestamptz, now(), '2026-09-23T13:35:24.393Z'::timestamptz) on conflict (id) do nothing;  -- 7tlpceb4l6 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('9aa2fea2-2d5a-5710-8f6b-ac0fee1ceb44'::uuid, '77916abb-2b51-5fd2-8455-c5ac685e979d'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Ramai ingat asalkan tak sebut ''rawat jerawat'', guna gelaran Doktor untuk promote skincare tu selamat. Salah.', '{"bm":{"instagram":"Ini silap yang saya nampak berulang kali dalam kalangan ''doktor medsos'' yang promote skincare guna nama dan gelaran sendiri.\n\nRamai anggap selagi tak buat tuntutan perubatan (macam ''rawat jerawat'' atau ''hilangkan parut''), semua okay. Itu salah faham besar.\n\nGaris Panduan Pengiklanan Kosmetik NPRA — Annex I, Part 10, Ogos 2022 — ada klausa khusus untuk ini. Klausa 4.1, Impressions of Professional Advice or Endorsement: iklan kosmetik tidak boleh memaparkan individu seperti doktor, doktor gigi atau ahli farmasi dengan tanggapan memberi syor atau pengesahan profesional, dan tidak boleh guna apa-apa ungkapan yang memberi kuasa berlebihan bahawa produk itu disyorkan oleh profesional kesihatan.\n\nSoalan Lazim NPRA bagi pengiklanan kosmetik, Versi 1.0 November 2025, jawab soalan ini terus: penggunaan gelaran profesional seperti doktor, ahli farmasi atau doktor gigi, bersama pemakaian kot putih, untuk mengesyorkan atau mempromosi kosmetik yang dinotifikasi adalah tidak dibenarkan.\n\nTanggalkan kot putih pun bukan lesen automatik. FAQ yang sama kata jika profesional perubatan muncul tanpa gelaran, tanpa pakaian klinikal dan tanpa latar klinik, ia ''boleh dipertimbangkan tetapi tertakluk kepada penilaian lanjut''. Watak kartun berkot putih, berstetoskop atau berlabel ''Dr.'' pun dikira sebagai paparan profesional perubatan.\n\nSebabnya iklan kosmetik di Malaysia tidak melalui kelulusan awal Lembaga Iklan Ubat. Ia sistem regulasi kendiri, dan pemegang notifikasi kosmetik yang menanggung sepenuhnya jika iklan itu tidak patuh.\n\nDan garis panduan yang sama ingatkan satu lapisan lagi yang berasingan daripada isu iklan tadi: profesional kesihatan berdaftar terikat dengan etika badan yang mendaftarkan mereka, dan penglibatan peribadi dalam promosi begini boleh membawa kepada pelanggaran etika.","facebook":"Ramai ''doktor medsos'' fikir selagi tak buat tuntutan perubatan, promote skincare guna gelaran sendiri tu selamat.\n\nSalah. Garis Panduan Pengiklanan Kosmetik NPRA (Annex I, Part 10, Ogos 2022), klausa 4.1, larang iklan kosmetik memberi tanggapan syor atau pengesahan profesional — termasuk apa-apa ungkapan yang memberi kuasa berlebihan bahawa produk disyorkan oleh profesional kesihatan.\n\nSoalan Lazim NPRA, Versi 1.0 November 2025, jawab terus: gelaran doktor, ahli farmasi atau doktor gigi bersama kot putih untuk mempromosi kosmetik yang dinotifikasi adalah tidak dibenarkan.\n\nTanggalkan kot putih pun bukan lesen automatik. Tanpa gelaran, tanpa pakaian klinikal, tanpa latar klinik — NPRA kata ''boleh dipertimbangkan tetapi tertakluk kepada penilaian lanjut''.\n\nDan profesional kesihatan berdaftar masih terikat dengan etika badan yang mendaftarkan mereka.","threads":"Guna gelaran ''Doktor'' untuk endorse skincare tak jadi selamat sekadar sebab tiada tuntutan perubatan.\n\nGaris Panduan Pengiklanan Kosmetik NPRA, Annex I Part 10 klausa 4.1: iklan tak boleh beri tanggapan syor atau pengesahan profesional. Soalan Lazim NPRA November 2025 sebut gelaran itu sendiri.\n\nBukan grey area."}}'::jsonb, 'NPRA, Guidelines for Control of Cosmetic Products in Malaysia (Second Edition), Annex I, Part 10 – Guideline for Cosmetic Advertisement, Ogos 2022, klausa 4.1; NPRA, Soalan Lazim: Control of Cosmetics Advertisement in Malaysia, Versi 1.0, November 2025, S2–S3', '[]'::jsonb, '2026-09-14'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa401b3cabd46fa08090d61","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa401b5a3aa88881a3627c6","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa401b8262bdff0e87c0c2c","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:27:00+08'::timestamptz, now(), '2026-09-08T12:32:10.940Z'::timestamptz) on conflict (id) do nothing;  -- 8klb14g1io (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('2952d0b6-4b28-588e-9eac-429460092dc8'::uuid, '24105721-7e2a-5084-84fd-c081506c2fb8'::uuid, 'regulab', 'farmaseutikal', null, 'bm', 'Stok anda masih guna label FarmaTag versi lama? Itu bukan palsu, dan tak perlu ditarik dari rak.', '{"bm":{"instagram":"Stok farmasi anda masih ada label hologram FarmaTag versi lama? Itu bukan palsu, dan tak perlu ditarik dari rak.\n\nRamai anggap bila KKM lancarkan FarmaTag versi baharu, automatik yang lama jadi tak sah. Salah faham macam ni boleh buat farmasi atau pengedar panik pulangkan stok yang sebenarnya masih sah.\n\nSurat KKM.600-18/3/112 Jld. 4 (44) bertarikh 16 Disember 2025 letak tiga perkara dengan jelas. Perenggan 2, FarmaTag versi baharu berkuat kuasa 2 Oktober 2025. Perenggan 3, fungsi pengesahan ketulenan bagi label baharu dimuatkan dalam aplikasi MyUBAT dan hanya tersedia mulai 1 Januari 2026. Perenggan 4, label hologram FarmaTag versi lama masih sah di pasaran dan ketulenannya boleh disemak melalui aplikasi FarmaChecker.\n\nYang ramai tercari-cari ialah tarikh tamat untuk stok lama. Surat itu tak menetapkan sebarang tarikh tamat atau tempoh peralihan. Label lama bukan tak sah, ia cuma disemak melalui laluan yang berbeza.\n\nJadi risiko sebenar bukan versi label pada kotak anda. Ia staf kaunter yang scan guna aplikasi yang tak sepadan dengan versi label, tak dapat bacaan, lepas tu simpulkan produk itu palsu.\n\nKalau anda uruskan farmasi atau jadi pengedar, brief staf pada satu perkara sahaja: bacaan kosong bukan bukti produk palsu, ia mungkin cuma aplikasi yang salah untuk versi label itu.","facebook":"Stok anda masih guna label hologram FarmaTag versi lama? Itu bukan palsu dan tak perlu ditarik dari rak.\n\nSurat KKM.600-18/3/112 Jld. 4 (44) bertarikh 16 Disember 2025 sebut tiga perkara. Satu, FarmaTag versi baharu berkuat kuasa 2 Oktober 2025. Dua, fungsi pengesahan ketulenan bagi label baharu dimuatkan dalam aplikasi MyUBAT mulai 1 Januari 2026. Tiga, dan ini yang selalu terlepas pandang, label versi lama masih sah di pasaran dan ketulenannya disemak melalui aplikasi FarmaChecker.\n\nSurat itu tak menetapkan sebarang tarikh tamat atau tempoh peralihan untuk stok berlabel lama. Label lama bukan tak sah. Ia cuma disemak melalui laluan yang berbeza.\n\nRisiko sebenar di kaunter bukan versi label pada kotak. Ia staf yang scan guna aplikasi yang tak sepadan dengan versi label, tak dapat bacaan, lepas tu ingat produk itu palsu.","threads":"Label hologram FarmaTag versi lama pada stok anda bukan palsu. Surat KKM.600-18/3/112 Jld. 4 (44) bertarikh 16 Disember 2025: versi baharu berkuat kuasa 2 Oktober 2025, pengesahan label baharu dalam MyUBAT mulai 1 Januari 2026, dan label versi lama masih sah, disemak melalui FarmaChecker. Tiada tarikh tamat untuk stok lama dinyatakan."}}'::jsonb, 'Surat KKM.600-18/3/112 Jld. 4 (44), 16 Disember 2025 — Pemakluman Penggunaan Label Keselamatan Hologram Baharu dan Kaedah Pengesahan Ketulenan Label bagi Produk Farmaseutikal, Pejabat Timbalan Ketua Pengarah Kesihatan (Perkhidmatan Farmasi), KKM; perenggan 2, 3 dan 4.', '[]'::jsonb, '2026-09-20'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aac69459ffdc36a73d6d59e","at":"2026-09-18 06:28 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aac69556697df0ff5bb34e4","at":"2026-09-18 06:28 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aac69829aa6c4a43f5fa40c","at":"2026-09-18 06:28 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-18 06:28:00+08'::timestamptz, now(), '2026-09-08T12:35:42.904Z'::timestamptz) on conflict (id) do nothing;  -- 9q02mekl3s (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('8927f904-5c6f-50bd-bea8-7209d66abcb0'::uuid, 'a5b9db39-bbe6-520c-adec-e43170801719'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Produk pencerah anda dah dinotifikasi NPRA? Itu tak bermakna anda terlepas.', '{"bm":{"instagram":"Produk pencerah anda dah dinotifikasi NPRA? Itu tak bermakna anda terlepas. Bila Annex dikemas kini, produk sedia ada pun kena ikut.\n\nPekeliling Bil. 2/2026 bertarikh 7 Julai 2026 kemas kini Annex II, III, IV dan VI dalam Guidelines for Control of Cosmetic Products in Malaysia, selaras keputusan Mesyuarat ASEAN Cosmetic Committee ke-43 pada 12 dan 13 Mei 2026.\n\nYang paling mendesak bukan kojic acid, walaupun itu yang paling ramai cakap. Bifonazole, Clotrimazole, Thiabendazole dan Tioconazole dimasukkan ke Annex II, dan perenggan 4.1.3 sebut produk kosmetik bernotifikasi yang mengandungi bahan-bahan tersebut tidak dibenarkan lagi berada di pasaran mulai tarikh pekeliling itu dikeluarkan. Tiada tempoh peralihan langsung untuk empat bahan ini.\n\nYang ada tempoh peralihan, dan ini yang perlu masuk dalam perancangan reformulasi anda:\n- Kojic acid: produk yang tidak mematuhi syarat baharu hanya dibenarkan di pasaran sehingga 29 April 2028. Had baharu ialah 1.0% untuk muka (leher) dan tangan bagi produk leave-on dan semua rinse-off, dan 0.2% untuk produk badan leave-on.\n- CI 45430: sehingga 29 April 2028.\n- Margosa ext.: sehingga 29 April 2029, pada 0.1% untuk semua produk kosmetik.\n\nChlorophene dan 2-chloroacetamide dikeluarkan dari Annex VI kerana kedua-duanya dipindah ke Annex II. Dan satu berita baik yang jarang disebut: Pentetic Acid dikeluarkan dari Annex II dan kini dibenarkan dalam produk kosmetik.\n\nKalau portfolio anda ada produk pencerah atau produk anti-kulat, semak formulasi dengan makmal atau pembekal bahan mentah sekarang. Tarikh 2028 nampak jauh, tapi reformulasi, stability study dan habiskan stok pembungkusan lama semuanya makan masa.","facebook":"Produk pencerah anda dah dinotifikasi NPRA? Itu tak bermakna anda terlepas.\n\nPekeliling Bil. 2/2026 (7 Julai 2026) kemas kini Annex II, III, IV dan VI dalam Guidelines for Control of Cosmetic Products in Malaysia, ikut keputusan Mesyuarat ASEAN Cosmetic Committee ke-43 pada 12 dan 13 Mei 2026.\n\nYang paling mendesak bukan kojic acid. Bifonazole, Clotrimazole, Thiabendazole dan Tioconazole masuk Annex II, dan produk bernotifikasi yang mengandunginya tidak dibenarkan berada di pasaran mulai tarikh pekeliling itu dikeluarkan. Tiada tempoh peralihan langsung.\n\nYang ada tempoh peralihan: kojic acid dan CI 45430 sehingga 29 April 2028, Margosa ext. sehingga 29 April 2029. Kojic acid kini 1.0% untuk muka (leher) dan tangan bagi produk leave-on dan semua rinse-off, dan 0.2% untuk produk badan leave-on.\n\nChlorophene dan 2-chloroacetamide dikeluarkan dari Annex VI kerana kedua-duanya masuk Annex II. Satu berita baik: Pentetic Acid dikeluarkan dari Annex II dan kini dibenarkan.","threads":"Notifikasi NPRA lama anda tak automatik selamat. Pekeliling Bil. 2/2026 (7 Julai 2026) kemas kini Annex II, III, IV dan VI. Bifonazole, Clotrimazole, Thiabendazole dan Tioconazole tak dibenarkan di pasaran mulai tarikh pekeliling dikeluarkan, tiada tempoh peralihan. Kojic acid dan CI 45430 sehingga 29 April 2028, Margosa ext. sehingga 29 April 2029."}}'::jsonb, 'NPRA Pekeliling Bil. 2/2026, Rujukan Bil (21) dlm. NPRA/PPPK/01/04, bertarikh 7 Julai 2026 — perenggan 4.1.3, 4.2.2, 4.2.3, 4.3.1, 4.4.1 dan 4.4.2; Lampiran A (Annex II), Lampiran B (Annex III, Kojic Acid ruj. 346, Margosa ext. ruj. 345), Lampiran C (Annex IV, CI 45430), Lampiran D (Annex VI ruj. 40 dan 41); keputusan Mesyuarat ASEAN Cosmetic Committee ke-43, 12 & 13 Mei 2026; Peraturan 18A, Peraturan-Peraturan Kawalan Dadah dan Kosmetik 1984.', '[]'::jsonb, '2026-09-14'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa401bbcabd46fa08090e57","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa401bd5a67efa86a9b6667","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa401bf32d420cab6f5445f","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:27:00+08'::timestamptz, now(), '2026-09-06T15:30:04.485Z'::timestamptz) on conflict (id) do nothing;  -- a7biuux4cl (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('ae27b459-c0e2-506f-874c-0c443e57b293'::uuid, '97fc1db1-7231-5d6d-8d52-b1a561bbdfa0'::uuid, 'regulab', 'kajian_kes', null, 'bm', 'Ada satu kes kami handle: syarikat kosmetik guna notifikasi NPRA yang dikeluarkan lapan tahun lepas untuk satu produk, dan bila ditanya status ingredient sekarang, jawapan dia ''notifikasi kami masih active, apa masalah''.', '{"bm":{"instagram":"Ada satu kes kami handle: syarikat kosmetik guna notifikasi NPRA yang dikeluarkan lapan tahun lepas untuk satu produk, dan bila ditanya status ingredient sekarang, jawapan dia ''notifikasi kami masih active, apa masalah''.\n\nMasalahnya bukan status active atau tidak. Masalahnya senarai ingredient dilarang dalam Annex III kena semak dari semasa ke semasa, dan NPRA boleh update senarai tu bila-bila masa tanpa produk anda automatically kena notice. Jadi notifikasi yang ''active'' pun boleh jadi formulation dia dah tak patuh dengan senarai terkini, cuma belum kena tangkap semasa premise inspection atau post-market surveillance.\n\nRamai founder anggar jarak masa antara tarikh notifikasi dengan peraturan sekarang tu jauh, sebab notifikasi tu ''lama''. Realitinya boleh jadi sangat dekat, sebab amendment kepada senarai larangan tu jalan lebih kerap dari yang orang sedar.\n\nKalau anda ada notifikasi lama, jangan anggap sebab dia active, dia automatically patuh dengan senarai sekarang.","facebook":"Kes sebenar: syarikat kosmetik pegang notifikasi NPRA lapan tahun, ingat sebab status ''active'' maknanya semua ok.\n\nRealitinya, senarai ingredient dilarang dalam Annex III boleh diupdate NPRA bila-bila masa, dan produk yang dah notify tak automatically kena semak semula. Jadi notifikasi ''active'' tak semestinya formulation patuh dengan senarai terkini.\n\nActive status bukan bukti patuh. Ia cuma bukti anda pernah patuh masa notify dulu.","threads":"Notifikasi NPRA ''active'' 8 tahun tak bermakna formulation anda masih patuh Annex III sekarang. Senarai larangan boleh diupdate bila-bila, produk lama tak automatically disemak semula. Active bukan proof of compliance hari ini."}}'::jsonb, '', '[]'::jsonb, '2026-09-16'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa9fc3cbcef7237b5a9d47d","at":"2026-09-16 10:17 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa9c62f4afcb5a41b059c2a","at":"2026-09-16 06:27 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa9fc3e501861120db42359","at":"2026-09-16 10:17 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-16 10:17:00+08'::timestamptz, now(), '2026-09-14T03:42:48.238Z'::timestamptz) on conflict (id) do nothing;  -- bqcelp6d9e (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('c46c3a8d-a92a-511d-9657-8b8ea87f203b'::uuid, null, 'linkedin', null, 'D', 'en', 'A safe cosmetic ingredient and a banned one can share the same NOAEL. The difference is what SCCS does with it next.', '{"en":{"linkedin":"A safe cosmetic ingredient and a banned one can share the same NOAEL. The difference is what SCCS does with it next.\n\nMargin of Safety, MoS, is the number that decides. SCCS takes the No Observed Adverse Effect Level from animal or in vitro data, divides it by the Systemic Exposure Dose estimated from how the product is actually used, and the result has to clear a threshold before an ingredient earns a place in Annex III or V.\n\nTwo products can carry the identical concentration of a UV filter and land on opposite sides of that line. A leave-on sunscreen applied daily to large skin area produces a far higher SED than a rinse-off cleanser with the same percentage. Contact time and surface area are doing as much work in that formula as the toxicology data itself.\n\nThis is why formulators cannot just copy a concentration from a competitor''s INCI list and assume it clears the same MoS in a different product category.\n\nThe chemistry behind the limit matters more than the limit itself.\n\nSources: SCCS Notes of Guidance, Margin of Safety methodology\n\n#CosmeticRegulation #SCCS #RegulatoryAffairs #Toxicology #ASEANCosmetics"}}'::jsonb, 'SCCS Notes of Guidance, Margin of Safety methodology', '[]'::jsonb, '2026-09-11'::date, '08:30', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7504161918690086914","at":"2026-09-11 21:00 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7504161918690086914/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:00:00+08'::timestamptz, now(), '2026-09-09T08:47:23.793Z'::timestamptz) on conflict (id) do nothing;  -- c6vsc6utu9 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('cef83977-cff8-5e70-a477-e597a3859a9a'::uuid, null, 'linkedin', null, 'C', 'en', 'A WTO TBT notification just made the word "nano" mandatory on your ingredient list, not optional.', '{"en":{"linkedin":"A WTO TBT notification just made the word \"nano\" mandatory on your ingredient list, not optional.\n\nThe notifying country filed a TBT notification requiring cosmetic products containing nanomaterial titanium dioxide to be declared as \"TITANIUM DIOXIDE (NANO)\", not just \"TITANIUM DIOXIDE\".\n\nThis mirrors what EU Regulation (EC) 1223/2009 Annex VI already requires for nano UV filters, where the bracket is not decoration, it is a legal marker.\n\nMany ASEAN dossiers lift the EU ingredient list wholesale but quietly drop the nano bracket, because the local notification template never asked for it.\n\nOnce this new requirement enters into force, that copied list becomes non-compliant in the notifying market even though the formula itself never changed.\n\nSunscreens and BB creams using nano TiO2 as a UV filter get caught first. If your file lists TiO2 without a particle size declaration, you will not know you are exposed until someone pulls the raw material''s certificate of analysis.\n\nFix the paperwork before the regulator asks for it.\n\n#RegulatoryAffairs #Cosmetics #WTOTBT #Nanomaterial #ASEAN"}}'::jsonb, 'WTO TBT notification,', '[]'::jsonb, '2026-09-22'::date, '06:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:ugcPost:7507931576765280256","at":"2026-09-22 06:40 MYT","url":"https://www.linkedin.com/feed/update/urn:li:ugcPost:7507931576765280256/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-22 06:40:00+08'::timestamptz, now(), '2026-09-19T04:30:13.254Z'::timestamptz) on conflict (id) do nothing;  -- chgf5b2m86 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('214d2c0e-7ed0-5cca-84b4-1f0eecad5caa'::uuid, '80a5f6a6-be92-56c7-b061-03cbedd6bcc6'::uuid, 'regulab', 'halal_my', null, 'bm', 'Dakwaan MSG ada khinzir tular lagi. Masalahnya, orang tanya soalan yang salah dari mula.', '{"bm":{"instagram":"FSQD JKWPKL & Putrajaya dah keluarkan kenyataan rasmi menafikan dakwaan MSG atau perisa umami mengandungi khinzir. Tapi lepas kenyataan pun, ramai masih tanya soalan yang salah.\n\nSoalan yang selalu ditanya: ''MSG ni daging apa?''\n\nJawapannya: bukan daging langsung. MSG ialah garam natrium bagi asid glutamik, satu asid amino biasa yang wujud dalam tomato, keju, kicap. MSG komersial dihasilkan melalui fermentation mikrob ke atas sumber karbohidrat macam molas atau kanji ubi, bukan tisu haiwan.\n\nJadi soalan halal yang betul bukan pasal ''sumber daging''. Soalan yang betul: apa medium fermentation yang digunakan, apa nutrien untuk kultur mikrob tu, dan apa processing aid yang masuk sepanjang proses. Itulah yang JAKIM semak dalam audit halal, bukan struktur kimia molekul akhir.\n\nMolekul akhir MSG sama je tak kira dari mana sumbernya. Yang beza, dan yang tentukan status halal, ialah apa yang berlaku sebelum molekul tu terbentuk.\n\nJadi kalau syarikat anda guna MSG atau perisa umami dalam produk, jangan settle dengan ''MSG memang halal''. Minta certificate of analysis dan halal cert untuk bahan tu sendiri, sebab audit tengok proses, bukan nama.","facebook":"FSQD JKWPKL & Putrajaya dah nafikan dakwaan tular MSG mengandungi khinzir. Tapi ramai masih tanya soalan salah: ''MSG ni daging apa?''\n\nMSG bukan daging. Ia garam natrium bagi asid glutamik, dihasilkan melalui fermentation mikrob atas sumber karbohidrat macam kanji ubi, bukan tisu haiwan.\n\nSoalan halal yang betul: medium fermentation, nutrien kultur, dan processing aid yang digunakan. Itu yang JAKIM semak dalam audit, bukan molekul akhirnya.\n\nKalau produk anda guna MSG, minta certificate untuk bahan tu sendiri. Proses yang tentukan status halal, bukan nama bahan.","threads":"MSG bukan daging, jadi ''MSG ni daging apa'' memang soalan salah dari awal. Soalan betul: medium fermentation dan processing aid yang digunakan. Itu yang audit halal semak, bukan molekul akhir. FSQD dah sahkan tak ada khinzir dalam MSG."}}'::jsonb, 'Kenyataan media FSQD, JKWPKL & Putrajaya, 24 Ogos 2026', '[]'::jsonb, '2026-09-21'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aaf0b6d4594e3153f427a5b","at":"2026-09-20 06:24 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aaf0b794594e3153f427b39","at":"2026-09-20 06:24 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aaf0b8013d908add20795c0","at":"2026-09-20 06:24 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-20 06:24:00+08'::timestamptz, now(), '2026-09-19T12:57:50.709Z'::timestamptz) on conflict (id) do nothing;  -- d0tlit7ezp (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('23be4206-510d-5455-bdbe-bdea4e4b336c'::uuid, '58e917ad-b747-5027-a803-9a0fcd9b5199'::uuid, 'regulab', 'makanan', null, 'bm', 'Vetsin bukan khinzir. ''Umami'' cuma perkataan untuk rasa asas kelima, bukan kod rahsia bahan haram.', '{"bm":{"instagram":"Vetsin bukan khinzir. Perkataan ''umami'' pada kotak MSG jenama popular buat ramai risau ia berkait dengan babi. Bahagian Keselamatan dan Kualiti Makanan (BKKM), Jabatan Kesihatan WP Kuala Lumpur & Putrajaya sudah menafikan dakwaan itu.\n\nUmami ialah rasa asas kelima yang dikesan lidah manusia, selain manis, masam, masin dan pahit. Ia terhasil bila reseptor lidah mengesan sebatian glutamat, iaitu asid amino yang memang wujud secara semula jadi dalam pelbagai jenis makanan. Perkataan itu memerihalkan rasa, bukan sumber bahan.\n\nBKKM juga menyatakan penggunaan MSG dibenarkan sebagai bahan tambah makanan dalam kategori penambah perisa, dan produk MSG bersijil halal di Malaysia kena penuhi keperluan halal yang ketat. Banyak pengeluar guna bahan mentah seperti ubi kayu dan tebu.\n\nTapi ini bukan sekadar cerita satu jenama besar. Ini risiko yang setiap SME makanan boleh hadapi bila-bila masa.\n\nBila anda letak nama sebatian kimia, istilah saintifik atau perkataan asing pada label, contohnya nama bahan pengawet, kod E, atau istilah teknikal dari spec sheet pembekal, netizen boleh baca ikut tafsiran sendiri. Bukan salah anda buat produk sedemikian. Tapi bila khabar angin merebak lebih laju daripada penjelasan, jualan dulu jatuh sebelum sempat anda jawab.\n\nSediakan fail rujukan: sijil halal kalau ada, spec sheet bahan mentah daripada pembekal, dan penjelasan ringkas setiap istilah teknikal pada label anda sendiri. Bila isu timbul, anda boleh jawab dalam hitungan jam dengan dokumen, bukan sekadar kenyataan ''kami dah check pun''.\n\nDue diligence pada label bukan pilihan lagi. Ia line pertahanan pertama sebelum isu kecil jadi viral.","facebook":"Umami bukan khinzir. BKKM, Jabatan Kesihatan WP Kuala Lumpur & Putrajaya sudah menafikan dakwaan itu. Umami ialah rasa asas kelima yang dikesan lidah bila reseptor mengesan sebatian glutamat, asid amino yang wujud semula jadi dalam banyak makanan. Ia perihal rasa, bukan sumber bahan.\n\nTapi ini isu yang boleh kena pada SME makanan mana-mana pun: bila anda guna istilah saintifik atau nama sebatian pada label, netizen boleh salah tafsir jadi isu halal.\n\nSediakan spec sheet pembekal dan penjelasan ringkas setiap istilah teknikal dulu. Bila isu timbul, anda jawab dengan dokumen, bukan tunggu khabar angin reda sendiri.","threads":"Umami bukan khinzir. BKKM, Jabatan Kesihatan WP Kuala Lumpur & Putrajaya sudah menafikan dakwaan itu. Umami ialah rasa asas kelima, terhasil daripada sebatian glutamat yang wujud semula jadi dalam makanan.\n\nTapi kalau label produk anda ada nama sebatian atau istilah saintifik, risiko sama boleh berlaku bila-bila masa. Sediakan spec sheet dan penjelasan istilah dulu, sebelum netizen buat tafsiran sendiri."}}'::jsonb, 'Kenyataan Bahagian Keselamatan dan Kualiti Makanan (BKKM), Jabatan Kesihatan Wilayah Persekutuan Kuala Lumpur & Putrajaya, mengenai dakwaan MSG mengandungi khinzir', '[]'::jsonb, '2026-09-19'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa6919466679b076f27c13b","at":"2026-09-13 20:05 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa69196eba7bc5677955bc7","at":"2026-09-13 20:05 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa6919866679b076f27c1c7","at":"2026-09-13 20:05 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-13 20:05:00+08'::timestamptz, now(), '2026-09-08T05:53:03.222Z'::timestamptz) on conflict (id) do nothing;  -- eip2wf6rd2 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('e55c0984-bd40-5655-af25-628eb22d12ff'::uuid, '2ecbc36e-2232-5c4a-a0e6-faf4bb73cef4'::uuid, 'linkedin', null, 'D', 'en', 'HSA Singapore issued a Class 2 retail recall for NU SKIN ageLOC Dermatic Effects, all lots, after surveillance testing found theophylline. Recall dated 17 September 2026, announced 18 September 2026. Local company on record: NU SKIN ENTERPRISES SINGAPORE PTE LTD.', '{"en":{"linkedin":"HSA Singapore issued a Class 2 retail recall for NU SKIN ageLOC Dermatic Effects, all lots, after surveillance testing found theophylline. Recall dated 17 September 2026, announced 18 September 2026. Local company on record: NU SKIN ENTERPRISES SINGAPORE PTE LTD.\n\nTheophylline treats asthma and COPD. It also has lipolytic and vasodilatory action, which is why it shows up illegally in slimming and firming products. No ASEAN Cosmetic Directive category allows it.\n\nThis isn''t a labelling error. An undeclared pharmaceutical active means the product should have gone through drug classification and registration, with dosage and safety controls that cosmetic notification never covers.\n\nDistributors carrying body-sculpting or firming claims should ask suppliers for the actual safety dossier, not just a notification number.\n\nSources:\nHSA Singapore recall notice, Class 2, dated 17 September 2026, announced 18 September 2026.\n\n#RegulatoryAffairs #Cosmetics #HSA #ASEAN #ProductSafety"}}'::jsonb, 'HSA Singapore recall notice, Class 2, dated 17 September 2026, announced 18 September 2026', '[]'::jsonb, '2026-09-19'::date, '12:50', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:ugcPost:7506936915351191552","at":"2026-09-19 12:50 MYT","url":"https://www.linkedin.com/feed/update/urn:li:ugcPost:7506936915351191552/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-19 12:50:00+08'::timestamptz, now(), '2026-09-19T04:16:16.158Z'::timestamptz) on conflict (id) do nothing;  -- emxufxko1d (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('55d7ff87-015f-5afa-90fa-8711f5164fca'::uuid, 'e36da7ab-a9b4-5d8e-be4b-c32e2208e3c2'::uuid, 'linkedin', null, 'A', 'en', 'Singapore''s Health Sciences Authority (Amendment) and Other Matters Bill folds health regulatory functions from the Ministry of Health and the Singapore Pharmacy Board into HSA as one authority.', '{"en":{"linkedin":"Singapore''s Health Sciences Authority (Amendment) and Other Matters Bill folds health regulatory functions from the Ministry of Health and the Singapore Pharmacy Board into HSA as one authority.\n\nThe bill itself does not create, remove or amend a single clause about cosmetics. Cosmetics in Singapore stay governed under the existing framework, HSA''s cosmetic product regulations and the ASEAN Cosmetic Directive as adopted there.\n\nWhat actually moves is institutional: staff, budget lines, enforcement teams. The desk that reviews your product notification or an adverse event report changes hands, not the rule it applies.\n\nThat distinction matters if you''re filing in Singapore right now. A regulator merger is not a compliance trigger. Don''t resubmit anything, don''t expect a new labelling clause, and don''t hold a filing back waiting for a cosmetics-specific circular this bill was never built to produce.\n\nSources: Health Sciences Authority (Amendment) and Other Matters Bill, Parliament of Singapore \n\n#HSA #CosmeticRegulation #RegulatoryAffairs #ASEAN #Singapore"}}'::jsonb, 'Health Sciences Authority (Amendment) and Other Matters Bill, Parliament of Singapore, second reading', '[]'::jsonb, '2026-09-21'::date, '06:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7507761385414680576","at":"2026-09-21 19:22 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7507761385414680576/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-21 19:22:00+08'::timestamptz, now(), '2026-09-09T14:33:03.954Z'::timestamptz) on conflict (id) do nothing;  -- f871n67co0 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('60560352-a4f2-51fc-8dce-90a33f37052d'::uuid, 'ad67520e-ed16-543d-9540-598e2b8ebe7d'::uuid, 'regulab', 'halal_my', null, 'bm', 'Bahan produk anda sempurna, tapi permohonan halal boleh ditolak sebelum JAKIM sempat tengok apa-apa bahan pun.', '{"bm":{"instagram":"Bahan produk anda boleh 100% halal, semua sijil ada, GMP pun lengkap. Tapi permohonan SPHM anda tetap boleh ditolak sebelum JAKIM sempat semak apa-apa bahan.\n\nSebabnya nama produk anda sendiri.\n\nManual Prosedur Pensijilan Halal Malaysia (Domestik) 2020, Prosedur 6(7), letak ini sebagai sebab TIDAK LAYAK memohon: nama syarikat, produk, menu atau jenama yang merujuk kepada produk tidak halal, sinonim dengannya, menyerupainya, atau apa-apa istilah mengelirukan. Lampiran A manual itu senaraikan istilahnya, lebih 200 nama, dari Bacon, Beer dan Ham sampai Bak Kut Teh, Char Siew, Chee Cheong Fun, Loh Bak dan Siew Bao.\n\nPerkataan ''Halal'' dalam nama jenama sendiri pun ada peruntukannya. Prosedur 5(12): nama syarikat, produk, ramuan dan jenama hendaklah tidak menggunakan pernyataan ''halal'' atau apa-apa representasi yang menunjukkan ia boleh digunakan oleh orang Islam.\n\nYang ramai tak tahu: sebahagian istilah itu dibenarkan jika diiringi keterangan. Lampiran A bahagian (2) bagi contohnya terus. Ramen dilarang, Carbonara Ramen dibenarkan. Luncheon meat dilarang, Chicken Luncheon Meat dibenarkan. Begitu juga Gyoza, Mortadella, Polony, Shogayaki dan Cocktail.\n\nSatu lagi di peringkat yang sama, Prosedur 6(3): jenama yang sama tidak boleh dipakai untuk produk halal dan tidak halal serentak.\n\nSemua permohonan SPHM melalui MYeHALAL, seperti diperuntukkan dalam Prosedur 21(1) manual yang sama.","facebook":"Bahan produk sempurna tak jamin permohonan halal lulus. Nama produk sendiri boleh menolaknya.\n\nManual Prosedur Pensijilan Halal Malaysia (Domestik) 2020, Prosedur 6(7), letak nama yang merujuk atau menyerupai produk tidak halal sebagai sebab TIDAK LAYAK memohon. Lampiran A senaraikan lebih 200 istilah: Bacon, Beer, Ham, Bak Kut Teh, Char Siew, Chee Cheong Fun, Loh Bak, Siew Bao.\n\nProsedur 5(12) pula: nama syarikat, produk, ramuan dan jenama tidak boleh guna pernyataan ''halal'' atau representasi yang menunjukkan ia boleh digunakan orang Islam.\n\nYang ramai tak tahu, sebahagian istilah itu dibenarkan dengan keterangan. Ramen dilarang, Carbonara Ramen dibenarkan. Luncheon meat dilarang, Chicken Luncheon Meat dibenarkan.","threads":"Bahan 100% halal, GMP lengkap, tapi permohonan SPHM boleh ditolak sebelum JAKIM semak bahan. Sebabnya nama produk.\n\nManual Prosedur Pensijilan Halal Malaysia (Domestik) 2020, Prosedur 6(7) dan Lampiran A: lebih 200 istilah, dari Bacon dan Beer sampai Bak Kut Teh dan Char Siew.\n\nSebahagiannya dibenarkan dengan keterangan. Ramen dilarang, Carbonara Ramen tidak."}}'::jsonb, 'JAKIM, Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020: Prosedur 5(12), Prosedur 6(3) dan 6(7), Prosedur 21(1), dan Lampiran A', '[]'::jsonb, '2026-09-22'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aaed8594594e3153f3e2ee1","at":"2026-09-22 00:33 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa874aca283eff81a4f2c7a","at":"15 Sep 2026, 6:27 AM MYT","via":"ws.regulab Studio"},"threads":{"id":"6aaed8777fcdd893197838d9","at":"2026-09-22 00:33 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-22 00:33:00+08'::timestamptz, now(), '2026-09-06T15:30:31.671Z'::timestamptz) on conflict (id) do nothing;  -- ffogztxpbr (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('9950b1ce-dd6a-5ebc-8ef5-19d743aa6576'::uuid, 'a00c55c7-d09f-5174-9a32-9331a5a7c358'::uuid, 'regulab', 'halal_my', null, 'bm', 'Produk tiada logo halal bukan bermakna ia haram. Ia cuma bermakna syarikat tu belum mohon.', '{"bm":{"instagram":"Ramai founder yang saya jumpa fikir logo halal JAKIM automatik wajib untuk semua produk makanan atau kosmetik. Ada pula yang terbalik, nampak produk tanpa logo terus anggap mesti ada masalah dengan bahan dia.\n\nTengok apa yang undang-undang itu sebenarnya kawal. Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020 diterbitkan di bawah Akta Perihal Dagangan 2011 [Akta 730], melalui subperenggan 7(2) Perintah Perihal Dagangan (Perakuan dan Penandaan Halal) 2011. Perintah Perihal Dagangan (Takrif Halal) 2011 pula yang mentakrifkan ''halal'' dan menetapkan JAKIM, MAIN atau JAIN sebagai pihak berkuasa berwibawa.\n\nMaknanya rejim itu mengawal perihal dan penandaan halal, bukan mewajibkan setiap produk disijilkan. Yang menjadi kesalahan ialah memperihalkan atau menanda produk sebagai halal tanpa perakuan pihak berkuasa berwibawa. Bukan ketiadaan logo.\n\nBila ia jadi wajib pula, biasanya bukan undang-undang Malaysia yang mewajibkannya, tetapi pasaran destinasi atau pembeli anda. Contoh yang paling jelas sekarang: Indonesia. BPJPH Regulation No. 3 of 2026 berkuat kuasa 23 Julai 2026 dan mengawal bentuk serta tatacara pelabelan maklumat bukan halal untuk produk dalam perimeter pensijilan halal mandatori mereka, termasuk makanan, minuman, ubat, kosmetik dan barangan pengguna.\n\nJadi bila ada yang tanya kenapa produk pesaing tiada logo halal tapi laku juga, jawapannya bukan misteri. Mungkin pasaran dia sekarang tidak memerlukannya. Logo halal itu akses pasaran, bukan lesen untuk beroperasi.","facebook":"Ramai anggap logo halal JAKIM wajib untuk semua produk. Tengok apa yang undang-undang itu sebenarnya kawal.\n\nManual Prosedur Pensijilan Halal Malaysia (Domestik) 2020 diterbitkan di bawah Akta Perihal Dagangan 2011 [Akta 730], melalui subperenggan 7(2) Perintah Perihal Dagangan (Perakuan dan Penandaan Halal) 2011. Rejim itu mengawal perihal dan penandaan halal, bukan mewajibkan setiap produk disijilkan.\n\nYang menjadi kesalahan ialah memperihalkan atau menanda produk sebagai halal tanpa perakuan JAKIM, MAIN atau JAIN. Bukan ketiadaan logo.\n\nBila ia wajib, selalunya pasaran destinasi yang mewajibkannya. Contoh paling jelas sekarang: Indonesia, di bawah BPJPH Regulation No. 3 of 2026 yang berkuat kuasa 23 Julai 2026.","threads":"Tiada logo halal bukan bermakna haram.\n\nManual Prosedur Pensijilan Halal Malaysia (Domestik) 2020 terbit di bawah Akta Perihal Dagangan 2011. Rejim itu mengawal perihal dan penandaan halal, bukan mewajibkan setiap produk disijilkan.\n\nYang salah dari segi undang-undang: menanda produk sebagai halal tanpa perakuan JAKIM, MAIN atau JAIN. Bukan sebaliknya."}}'::jsonb, 'Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020, Prosedur 1(2), diterbitkan di bawah Akta Perihal Dagangan 2011 [Akta 730] melalui subperenggan 7(2) Perintah Perihal Dagangan (Perakuan dan Penandaan Halal) 2011; Perintah Perihal Dagangan (Takrif Halal) 2011. Contoh eksport: BPJPH Regulation No. 3 of 2026 (Indonesia), berkuat kuasa 23 Julai 2026, WTO TBT G/TBT/N/IDN/184/Add.2', '[]'::jsonb, '2026-09-13'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa43034e1158f41d39cc53e","at":"2026-09-12 00:45 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa430365ebbb9f005ccbb70","at":"2026-09-12 00:45 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa43038e1158f41d39cc56f","at":"2026-09-12 00:45 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-12 00:45:00+08'::timestamptz, now(), '2026-09-08T05:55:41.276Z'::timestamptz) on conflict (id) do nothing;  -- g0neiaa5ap (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('6780dddd-01fa-52c8-b9c3-c11ac11ce8a9'::uuid, 'fc7d3a0d-2ffb-571a-8300-721a53aed27b'::uuid, 'regulab', 'fatwa', null, 'bm', 'Asid folik dalam suplemen anda bukan diperah daripada hati khinzir. Ia kimia.', '{"bm":{"instagram":"Ada video tular kata ibu mengandung dan bayi ''makan hati khinzir'' sebab ambil asid folik. Ini yang orang keliru: asid folik ialah vitamin B9. Ia memang wujud secara semula jadi dalam hati haiwan, termasuk khinzir. Tapi itu bukan macam mana suplemen di pasaran dihasilkan.\n\nSuplemen asid folik dalam bentuk tablet atau cecair dibuat melalui tindak balas kimia. Tiada bahan mentah bersumberkan haiwan terlibat dalam proses tersebut. JAKIM sendiri sudah jelaskan ini dalam laman Isu-Isu Tular Halal rasmi mereka.\n\nPunca kekeliruan ni mudah: orang samakan ''di mana sebatian ini boleh dijumpai secara semula jadi'' dengan ''dari mana sebatian dalam botol suplemen anda datang''. Dua soalan berbeza, dua jawapan berbeza.\n\nRisiko sebenar bukan pada kandungan suplemen. Risiko sebenar ialah bila ibu mengandung atau yang merancang hamil berhenti ambil asid folik sebab takut dengan dakwaan tular ni. Itu yang boleh bagi kesan kepada perkembangan bayi.\n\nKeputusan Muzakarah MKI bukan undang-undang secara automatik. Ia mengikat di sesebuah negeri hanya selepas diwartakan oleh Jawatankuasa Fatwa Negeri.","facebook":"Video tular kata ibu mengandung ''makan hati khinzir'' sebab ambil asid folik. Faktanya: asid folik ialah vitamin B9, wujud semula jadi dalam hati haiwan termasuk khinzir, tapi suplemen tablet atau cecair dihasilkan melalui tindak balas kimia, bukan daripada bahan mentah haiwan. JAKIM dah jelaskan ini dalam laman Isu-Isu Tular Halal rasmi. Risiko sebenar: ibu mengandung berhenti ambil asid folik sebab dakwaan ni, bukan kandungannya.\n\nKeputusan Muzakarah MKI bukan undang-undang secara automatik. Ia mengikat di sesebuah negeri hanya selepas diwartakan oleh Jawatankuasa Fatwa Negeri.","threads":"Asid folik dalam suplemen anda bukan daripada hati khinzir. Ia dibuat melalui tindak balas kimia, bukan diproses daripada organ haiwan. Orang keliru sebab samakan ''di mana ia dijumpai secara semula jadi'' dengan ''macam mana ia dibuat''. JAKIM dah jelaskan ini dalam laman Isu-Isu Tular Halal rasmi. Jangan berhenti ambil asid folik sebab dakwaan tular, itu risiko sebenar untuk ibu mengandung."}}'::jsonb, 'JAKIM, laman Isu-Isu Tular Halal (rasmi), dibaca 19 September 2026', '[]'::jsonb, '2026-09-22'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab1b0318e2aab6eac4e8758","at":"2026-09-22 06:31 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab1b0421b349ea8ed97697d","at":"2026-09-22 06:31 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab1b050826cfc54b85d8046","at":"2026-09-22 06:31 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-22 06:31:00+08'::timestamptz, now(), '2026-09-20T09:52:06.142Z'::timestamptz) on conflict (id) do nothing;  -- gr9m120ecp (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('e83eec04-19e2-543f-b92a-b5fe56c150b6'::uuid, '7a1ed7bc-152b-5e5c-a711-d0caf613b28c'::uuid, 'linkedin', null, 'G', 'en', 'Most people size up filler risk by brand alone. A new JAAD study says that is half the story.', '{"en":{"linkedin":"Most people size up dermal filler risk by brand alone. A study published in the Journal of the American Academy of Dermatology on 18 September 2026 pushes back on that.\n\nThe researchers used Color Doppler Ultrasound to examine filler complications, and reported associations not just with filler type, but with the injector''s profession.\n\nThat matters because vascular occlusion, the complication everyone fears with filler, is a mechanical event. A needle or cannula tip enters or compresses a vessel. Product chemistry (HA cross-linking, particle size) affects how the occlusion behaves once it happens. But whether it happens at all is driven by technique, anatomy knowledge and injection depth, all of which sit with the person holding the needle, not the syringe label.\n\nIn Malaysia this maps onto two separate regulatory checks. Is the filler registered as a medical device with NPRA. Is the injector a registered medical practitioner operating within the scope set by the Malaysian Medical Council. Brand due diligence without practitioner due diligence covers half the risk.\n\nSources: Etesami I, Memari H, Wortsman X, et al. Color Doppler Ultrasound of Cosmetic Filler Complications: Associations with Filler Type and Injector Profession. J Am Acad Dermatol. Published online 18 Sept 2026, ahead of print. doi:10.1016/j.jaad.2026.09.043. Medical Device Act 2012 (NPRA, dermal filler registration requirement). Medical Act 1971 (Malaysian Medical Council, scope of practice).\n\n#RegulatoryAffairs #DermalFiller #CosmeticRegulation #MedicalDevice #NPRA"}}'::jsonb, 'Etesami I, Memari H, Wortsman X, et al. Color Doppler Ultrasound of Cosmetic Filler Complications: Associations with Filler Type and Injector Profession. J Am Acad Dermatol. Published online 18 Sept 2026, ahead of print. doi:10.1016/j.jaad.2026.09.043; Medical Device Act 2012 (NPRA); Medical Act 1971 (MMC)', '[]'::jsonb, '2026-09-24'::date, '19:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7509016463295578112","at":"2026-09-25 06:30 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7509016463295578112","via":"ws.regulab Studio"}}'::jsonb, '2026-09-25 06:30:00+08'::timestamptz, now(), '2026-09-23T06:32:29.025Z'::timestamptz) on conflict (id) do nothing;  -- gys2u578rg (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('1be1c98b-bb99-5b9e-8945-52fde3cb036b'::uuid, null, 'regulab', 'fatwa', null, 'bm', 'Alkohol dalam toner dan minyak wangi anda — apa hukumnya?', '{"bm":{"instagram":"Alkohol dalam toner dan minyak wangi anda — apa hukumnya?\n\nNot all alcohol is liquor. Bukan semua alkohol itu arak, dan perbezaan itu yang menentukan hukumnya.\n\nMuzakarah Jawatankuasa Fatwa MKI Kali Ke-7 bersidang 11–12 April 1984 dan memutuskan:\n\nAlkohol dari proses pembuatan arak — haram dan najis.\nAlkohol yang dihasilkan BUKAN melalui proses itu — tidak najis, tapi haram diminum dalam bentuk asli.\nAlkohol sampingan dalam pembuatan makanan — tidak najis.\nUbat-ubatan dan pewangi beralkohol — harus.\n\nInilah fatwa induk untuk semua fatwa alkohol terkemudian di Malaysia, dan asas kepada penerimaan Ethanol dan Alcohol Denat. dalam kosmetik.\n\nTapi ia bersyarat, dan syaratnya bukti.\n\nUntuk pensijilan halal, anda kena boleh buktikan etanol itu sintetik atau industri — bukan hasil sampingan kilang arak. Simpan supplier declaration dan carta aliran proses. Dua dokumen itu yang diminta masa audit. Kalau pembekal tak boleh beri, itu pun satu jawapan.\n\nSekarang bahagian yang paling kerap terlepas.\n\nKeputusan Muzakarah MKI bukan undang-undang secara automatik. Ia mengikat di sesebuah negeri hanya selepas diwartakan oleh Jawatankuasa Fatwa Negeri. Semak status pewartaan sebelum petik dalam dokumen klien.\n\nDan status fatwa tak menggantikan pematuhan NPRA — dua saringan berasingan.\n\nwww.kkmhalalconsultant.com\n\nRujukan: Muzakarah Jawatankuasa Fatwa MKI Kali Ke-7, 11–12 April 1984. Status hukum: harus (bersyarat).\n\n#Fatwa #Halal #JAKIM #Kosmetik #Pewangi #SMEMalaysia","facebook":"Alkohol dalam toner dan minyak wangi — apa hukumnya?\n\nBukan semua alkohol itu arak, dan perbezaan itu yang menentukan hukumnya.\n\nMuzakarah Jawatankuasa Fatwa MKI Kali Ke-7 (11–12 April 1984): alkohol dari proses pembuatan arak haram dan najis; alkohol yang dihasilkan bukan melalui proses itu tidak najis; ubat-ubatan dan pewangi beralkohol adalah harus.\n\nInilah asas penerimaan Ethanol dan Alcohol Denat. dalam kosmetik — tapi ia bersyarat. Untuk pensijilan halal, buktikan etanol itu sintetik atau industri. Simpan supplier declaration dan carta aliran proses; dua dokumen itu yang diminta masa audit.\n\nYang paling kerap terlepas: keputusan Muzakarah MKI bukan undang-undang secara automatik. Ia mengikat hanya selepas diwartakan oleh Jawatankuasa Fatwa Negeri. Semak status pewartaan sebelum petik dalam dokumen klien.\n\nwww.kkmhalalconsultant.com\n\nRujukan: Muzakarah Jawatankuasa Fatwa MKI Kali Ke-7, 11–12 April 1984.\n\n#Fatwa #Halal #JAKIM #SMEMalaysia","threads":"Alkohol dalam toner dan minyak wangi anda — apa hukumnya?"}}'::jsonb, 'Muzakarah Jawatankuasa Fatwa Majlis Kebangsaan Bagi Hal Ehwal Ugama Islam Malaysia (MKI) Kali Ke-7, 11–12 April 1984', '[]'::jsonb, '2026-09-04'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6a9d3a355c2ba4d1540f72e6","at":"2026-09-06 18:02 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6a9d3a37af83b6dedf8df346","at":"2026-09-06 18:02 MYT","via":"ws.regulab Studio"},"threads":{"id":"6a9d3a385c2ba4d1540f7312","at":"2026-09-06 18:02 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-06 18:02:00+08'::timestamptz, now(), '2026-09-05T07:51:59.458627Z'::timestamptz) on conflict (id) do nothing;  -- h20260904 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('4a899874-e949-5591-b33e-da4a911d2acb'::uuid, null, 'regulab', 'kosmetik', null, 'bm', '"Saya tukar pembekal bahan mentah je. Tak payah bagitahu NPRA kan?"', '{"bm":{"instagram":"\"Saya tukar pembekal bahan mentah je. Tak payah bagitahu NPRA kan?\"\n\nPayah. Dan jawapannya bukan ya atau tidak — ia bergantung pada jenis perubahan.\n\nGuidelines for Control of Cosmetic Products in Malaysia (2nd Ed, NPRA) bahagikan perubahan kepada dua jenis:\n\nJENIS 1 — pindaan pada notifikasi semasa sahaja. Tiada caj, nombor notifikasi anda kekal sama.\n\nJENIS 2 — perubahan yang memerlukan notifikasi baharu. Fi pemprosesan RM50.00, dan nombor notifikasi baharu dikeluarkan.\n\nYang mana satu bukan pilihan anda. Ia ditetapkan dalam Annex I part 5. Anda semak senarai itu, bukan anggarkan sendiri.\n\nKenapa kena semak sebelum, bukan selepas?\n\nSebab nombor notifikasi baharu bermakna nombor yang dah tercetak pada packaging jadi salah. Kalau 10,000 keping label dah keluar dari mesin, kos itu bukan RM50.\n\nSatu lagi yang orang tak sangka.\n\nPIF kena dikemas kini untuk SETIAP perubahan pada produk yang dinotifikasi — ramuan, pengilang, pembekal bahan mentah, proses pengeluaran. Termasuk Jenis 1, yang tak jana nombor baharu langsung.\n\nPIF tanggungjawab CNH, bukan pengilang. Ia mesti sedia dan boleh diakses bila NPRA minta — bukan \"boleh siapkan dalam dua minggu\".\n\nUrutan yang betul: semak Annex I part 5, tentukan jenis, kemas kini PIF, baru cetak.\n\nRujukan: Guidelines for Control of Cosmetic Products in Malaysia, 2nd Ed (NPRA), Seksyen 2.9, 3.8, 4.1.8.\n\n#Kosmetik #NPRA #CNH #PIF #SMEMalaysia","facebook":"\"Saya tukar pembekal bahan mentah je. Tak payah bagitahu NPRA kan?\"\n\nPayah — dan jawapannya bergantung pada jenis perubahan.\n\nJenis 1: pindaan pada notifikasi semasa sahaja. Tiada caj, nombor kekal sama.\nJenis 2: perubahan yang memerlukan notifikasi baharu. Fi pemprosesan RM50.00, nombor baharu dikeluarkan.\n\nYang mana satu bukan pilihan anda — ia ditetapkan dalam Annex I part 5.\n\nSemak sebelum cetak packaging, bukan selepas. Nombor baharu bermakna nombor yang dah tercetak jadi salah, dan kos itu bukan lagi RM50.\n\nSatu lagi: PIF kena dikemas kini untuk SETIAP perubahan — termasuk Jenis 1, yang tak jana nombor baharu. PIF tanggungjawab CNH, dan ia mesti sedia bila NPRA minta.\n\nRujukan: Guidelines for Control of Cosmetic Products in Malaysia, 2nd Ed (NPRA), Seksyen 2.9, 3.8, 4.1.8.\n\n#Kosmetik #NPRA #CNH #PIF #SMEMalaysia","threads":"\"Saya tukar pembekal bahan mentah je. Tak payah bagitahu NPRA kan?\""}}'::jsonb, 'Guidelines for Control of Cosmetic Products in Malaysia, 2nd Ed (NPRA), Seksyen 2.9, 3.8, 4.1.8', '[]'::jsonb, '2026-09-10'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa266d52e4217c61484348f","at":"10 Sep 2026, 4:15 PM MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa266eab142551a03fd92c7","at":"10 Sep 2026, 4:15 PM MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa266f72e4217c614843907","at":"10 Sep 2026, 4:15 PM MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-10 21:00:00+08'::timestamptz, now(), '2026-09-05T07:11:38.491700Z'::timestamptz) on conflict (id) do nothing;  -- h20260907 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('661b3f6c-13ae-5d53-8bbe-c39471b710bc'::uuid, null, 'regulab', 'halal_my', null, 'bm', 'Sijil halal anda sah berapa lama? Bergantung skim — dan ramai ingat 2 tahun untuk semua.', '{"bm":{"instagram":"Sijil halal anda sah berapa lama? Bergantung skim — dan ramai ingat 2 tahun untuk semua.\n\nRumah sembelihan — 1 tahun.\nMakanan, minuman, premis makanan — 2 tahun.\nKosmetik, farmaseutikal, logistik, OEM, peranti perubatan — 3 tahun.\nSyarikat luar negara yang mengilang dalam negara — 2 tahun.\n\nJadi kalau anda syarikat logistik halal dan anda plan pembaharuan ikut kitaran 2 tahun, anda buat kerja setahun lebih awal daripada perlu.\n\nDan sebaliknya lagi teruk: kalau anda premis makanan tapi ingat sijil anda 3 tahun, anda akan terlepas tarikh.\n\nSatu lagi yang jarang disebut — pemegang Sijil Pengesahan Halal Malaysia sekurang-kurangnya 5 tahun yang memenuhi syarat boleh dapat tempoh lanjutan 5 tahun.\n\nSemak skim anda dalam sijil sendiri sebelum tetapkan kalendar pembaharuan.\n\nRujukan: MPPHM (Domestik) 2020, Prosedur 35(2) dan 35(3).\n\n#SijilHalal #JAKIM #HalalMalaysia #LogistikHalal #SMEMalaysia","facebook":"Sijil halal anda sah berapa lama? Bergantung skim.\n\nRumah sembelihan 1 tahun. Makanan, minuman dan premis makanan 2 tahun. Kosmetik, farmaseutikal, logistik, OEM dan peranti perubatan 3 tahun. Syarikat luar negara yang mengilang dalam negara 2 tahun.\n\nRamai ingat 2 tahun untuk semua. Kalau anda syarikat logistik, itu bermakna anda buat kerja pembaharuan setahun lebih awal. Kalau anda premis makanan tapi ingat 3 tahun, anda terlepas tarikh.\n\nPemegang SPHM 5 tahun ke atas yang memenuhi syarat boleh dapat tempoh lanjutan 5 tahun.\n\nRujukan: MPPHM (Domestik) 2020, Prosedur 35(2) dan 35(3).\n\n#SijilHalal #JAKIM #HalalMalaysia #SMEMalaysia"}}'::jsonb, 'MPPHM (Domestik) 2020, Prosedur 35(2) dan 35(3)', '[]'::jsonb, '2026-09-09'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa11ce77f00355254d4372d","at":"2026-09-09 16:46 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa1594e0844d2b6d49f3d97","at":"2026-09-09 21:04 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-09 21:04:00+08'::timestamptz, now(), '2026-09-05T07:11:38.491700Z'::timestamptz) on conflict (id) do nothing;  -- h20260909 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('fdfcc5d9-b1eb-5c05-aec9-9c73991ccd4e'::uuid, null, 'regulab', 'farmaseutikal', null, 'bm', 'Health supplement anda: 100 hari, atau 245 hari?', '{"bm":{"instagram":"Health supplement anda: 100 hari, atau 245 hari?\n\nProduk sama. Bahan sama. Tapi tempoh penilaian boleh beza 145 hari — dan yang tentukan bukan apa yang ada dalam botol.\n\nIa claim yang anda cetak pada label.\n\nKalau label bawa general atau nutritional claim, atau functional claim, dengan satu active ingredient — ia masuk abridged evaluation. 100 hari bekerja.\n\nTulis \"disease risk reduction claim\" pada label yang sama, botol yang sama — terus jatuh ke full evaluation. 245 hari.\n\nSatu ayat pada artwork. 145 hari.\n\nYang selalu jadi: artwork dah siap, dossier dah masuk, baru perasan bila QUEST letak fail kat laluan penuh. Time tu nak tukar claim pun dah lambat — anda kena tarik balik dan mula semula.\n\nSo decide dulu. Sebelum hantar, bukan selepas: claim mana yang betul-betul nak dicetak, dan anda ada substantiation untuk claim tu ke tidak.\n\nRamai orang plan timeline dari tarikh hantar. Itu pun dah silap — Seksyen 10.3 kata jam mula selepas bayaran fi disahkan, bukan bila dossier sampai.\n\nRujukan: DRGD 3rd Ed, 12th Rev (Julai 2026), Seksyen 10.3.\n\n#PendaftaranUbat #NPRA #DRGD #HealthSupplement #SMEMalaysia #RegulatoryAffairs","facebook":"Health supplement anda: 100 hari, atau 245 hari?\n\nProduk sama, bahan sama. Yang tentukan tempoh bukan apa dalam botol — ia claim yang anda cetak pada label.\n\nGeneral atau nutritional claim, atau functional claim, satu active ingredient — abridged evaluation, 100 hari bekerja. Tulis \"disease risk reduction claim\" pada label yang sama, ia jatuh ke full evaluation, 245 hari.\n\nSatu ayat pada artwork. 145 hari.\n\nYang selalu jadi: baru perasan bila QUEST dah letak fail kat laluan penuh, dan time tu nak tukar pun dah lambat.\n\nDecide claim dulu, sebelum hantar dossier.\n\nRujukan: DRGD 3rd Ed, 12th Rev (Julai 2026), Seksyen 10.3.\n\n#NPRA #DRGD #HealthSupplement #SMEMalaysia","threads":"Health supplement anda: 100 hari, atau 245 hari?"}}'::jsonb, 'DRGD 3rd Ed, 12th Rev (Julai 2026), Seksyen 10.3', '[]'::jsonb, '2026-09-17'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa4019ccabd46fa08090b68","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa4019d4ac55a0b10a1267b","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa4019f4ac55a0b10a126a5","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:26:00+08'::timestamptz, now(), '2026-09-05T07:11:38.491700Z'::timestamptz) on conflict (id) do nothing;  -- h20260910 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('a9a4652b-3c28-59d1-b561-bd7802719f0b'::uuid, null, 'regulab', 'fatwa', null, 'bm', 'Warna merah dalam gincu anda mungkin datang daripada serangga.', '{"bm":{"instagram":"Warna merah dalam gincu anda mungkin datang daripada serangga.\n\nCarmine. Cochineal. CI 75470. Tiga nama, satu bahan — dalam gincu, blusher, minuman dan gula-gula.\n\nReaksi pertama kebanyakan orang: kalau dari serangga, mesti haram.\n\nMuzakarah Jawatankuasa Fatwa MKI Kali Ke-100, bersidang 4–6 Julai 2012, memutuskan sebaliknya. Penggunaan bahan pewarna cochineal dalam makanan, minuman dan barang gunaan adalah DIHARUSKAN.\n\nAlasannya pada darah. Cochineal ialah serangga — kumbang betina — yang tidak membahayakan, dan jumhur fuqaha bersepakat bahawa bangkai serangga yang darahnya tidak mengalir adalah suci.\n\nTetapi ia harus BERSYARAT: kadar penggunaan mengikut ketetapan Kementerian Kesihatan Malaysia, selagi tidak mendatangkan kemudaratan.\n\nYang ramai terlepas, dan ini bahagian yang mahal:\n\nJabatan Mufti Negara Brunei Darussalam memutuskan sebaliknya. Haram. Kalau SKU anda melintas sempadan, keputusan Malaysia tidak ikut sama — untuk pasaran itu, reformulasi kepada beetroot, anthocyanin atau CI sintetik.\n\nUntuk kosmetik pula, status fatwa tidak menamatkan kerja: kelulusan CI 75470 di bawah Annex IV ACD disemak berasingan, mengikut jenis penggunaan.\n\nDan keputusan Muzakarah MKI bukan undang-undang automatik. Ia mengikat di sesebuah negeri hanya selepas diwartakan oleh Jawatankuasa Fatwa Negeri.\n\nRujukan: Muzakarah Jawatankuasa Fatwa MKI Kali Ke-100, 4–6 Julai 2012. Teks penuh disahkan di e-SMAF (e-smaf.islam.gov.my).\n\n#Cochineal #Carmine #FatwaMalaysia #HalalMalaysia #KosmetikMalaysia #RegulatoryAffairs","facebook":"Warna merah dalam gincu anda mungkin datang daripada serangga.\n\nCarmine, cochineal, CI 75470 — satu bahan, tiga nama.\n\nMuzakarah Jawatankuasa Fatwa MKI Kali Ke-100 (4–6 Julai 2012) memutuskan penggunaannya dalam makanan, minuman dan barang gunaan adalah DIHARUSKAN. Alasannya: cochineal ialah serangga yang tidak membahayakan, dan jumhur fuqaha bersepakat bangkai serangga yang darahnya tidak mengalir adalah suci.\n\nBersyarat: kadar mengikut ketetapan Kementerian Kesihatan Malaysia, selagi tidak mendatangkan kemudaratan.\n\nYang mahal kalau terlepas — Jabatan Mufti Negara Brunei Darussalam memutuskan sebaliknya. Untuk SKU eksport ke sana, reformulasi kepada beetroot, anthocyanin atau CI sintetik.\n\nDan keputusan Muzakarah MKI bukan undang-undang automatik. Ia mengikat di sesebuah negeri hanya selepas diwartakan oleh Jawatankuasa Fatwa Negeri.\n\nRujukan: Muzakarah MKI Kali Ke-100, 4–6 Julai 2012. Teks penuh: e-SMAF.\n\n#FatwaMalaysia #HalalMalaysia #Carmine","threads":"Warna merah dalam gincu anda mungkin datang daripada serangga."}}'::jsonb, 'Muzakarah Jawatankuasa Fatwa Majlis Kebangsaan Bagi Hal Ehwal Ugama Islam Malaysia (MKI) Kali Ke-100, 4–6 Julai 2012', '[]'::jsonb, '2026-09-11'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa4019c32d420cab6f53c00","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa401b1a3aa88881a3625a4","at":"2026-09-11 21:28 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa401e2262bdff0e87c0fd5","at":"2026-09-11 21:28 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:28:00+08'::timestamptz, now(), '2026-09-05T07:11:38.491700Z'::timestamptz) on conflict (id) do nothing;  -- h20260911 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('4127b3d9-1ee1-5636-8e20-9fe42d7b1d08'::uuid, null, 'regulab', 'kajian_kes', null, 'bm', 'Sunscreen stick memang berkesan. Cuma bukan dengan satu sapuan.', '{"bm":{"instagram":"Sunscreen stick memang berkesan. Cuma bukan dengan satu sapuan.\n\nNombor SPF pada label bukan janji yang mengikut tangan anda. Ia keputusan satu keadaan ujian, dan keadaan itu menetapkan berapa banyak produk disapu pada kulit: 2 mg/cm², di bawah ISO 24444.\n\nSatu sapuan stick tidak sampai ke situ. Yang tinggal pada kulit ialah jalur berselang, dan celah antara jalur itu tidak berlapis sama.\n\nJadi sapu ulang-alik 3–4 kali, ke depan dan ke belakang, kemudian ratakan dengan hujung jari.\n\nAtau lebih mudah: guna losyen sebagai lapisan pertama dan simpan stick untuk sapuan ulang sepanjang hari. Hidung, telinga, bawah mata. Itu kawasan yang stick memang paling senang capai.\n\nUntuk pihak jenama, ada satu lagi lapisan pada cerita ini.\n\nNasihat penggunaan boleh masuk artwork: \"Sapu dengan banyak dan sekata; ulang setiap 2 jam.\" Itu arahan, bukan dakwaan prestasi.\n\nNombor SPF pada label pula ialah claim, dan claim kena ada substantiation di belakangnya. Annex I Part 8. Semak juga setiap UV filter dalam formula terhadap Annex VII sebelum anda kunci artwork.\n\nDan ayat macam \"satu sapuan sudah cukup\"? Ia bercanggah dengan keadaan ujian yang menghasilkan nombor itu.\n\nRujukan: ISO 24444, kadar sapuan 2 mg/cm². NPRA Guidelines for Control of Cosmetic Products — Annex I Part 8, Annex VII.\n\n#SPF #KosmetikMalaysia #NPRA #RegulatoryAffairs #SMEMalaysia #UsahawanMalaysia","facebook":"Sunscreen stick memang berkesan — cuma bukan dengan satu sapuan.\n\nNombor SPF pada label ialah keputusan satu keadaan ujian, dan keadaan itu menetapkan berapa banyak produk disapu pada kulit: 2 mg/cm², di bawah ISO 24444. Satu sapuan stick tinggalkan jalur berselang, bukan lapisan sekata.\n\nJadi sapu ulang-alik 3–4 kali, kemudian ratakan. Atau guna losyen sebagai lapisan pertama dan simpan stick untuk sapuan ulang — hidung, telinga, bawah mata.\n\nUntuk jenama: nasihat penggunaan boleh masuk artwork. Nombor SPF pula ialah claim, dan claim kena ada substantiation. Annex I Part 8.\n\nRujukan: ISO 24444; NPRA Guidelines, Annex I Part 8 dan Annex VII.\n\n#SPF #KosmetikMalaysia #NPRA","threads":"Sunscreen stick memang berkesan. Cuma bukan dengan satu sapuan."}}'::jsonb, 'SPF substantiation ISO 24444 @ 2 mg/cm²; NPRA Annex I Part 8 (claims), Annex VII (UV filters). Amaran wajib sunscreen: Annex I Part 9(i).', '[]'::jsonb, '2026-09-12'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa4017232d420cab6f535c6","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa40174a3aa88881a361f85","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa40176262bdff0e87c043b","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:26:00+08'::timestamptz, now(), '2026-09-05T07:11:38.491700Z'::timestamptz) on conflict (id) do nothing;  -- h20260912 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('5caaa016-b45b-589a-8b1c-cfb5c7ed89c3'::uuid, null, 'regulab', 'makanan', null, 'bm', 'Gambar strawberi pada pek anda menarik satu tuntutan yang ramai terlepas.', '{"bm":{"instagram":"Gambar strawberi pada pek anda menarik satu tuntutan yang ramai terlepas.\n\nSebaik anda menonjolkan sesuatu ramuan pada label — pada nama produk, melalui gambar, atau dengan teks yang dibesarkan — Peraturan-Peraturan Makanan 1985 menuntut peratusnya. Per. 11(1)(eb): peratus berat atau isi padu, dinyatakan bersebelahan ramuan yang ditonjolkan itu.\n\nIni corak yang berulang. Artwork siap, panel depan kemas, \"dengan madu asli\" besar di tengah. Senarai ramuan di belakang pula lengkap dan betul susunannya. Semakan label kembali dengan satu perkara sahaja: madu itu berapa peratus, dan kenapa nombor itu tiada di sebelahnya.\n\nQUID bukan peraturan bersendirian. Ia duduk pada blok yang sama dengan tiga lagi:\n\nPer. 11(1)(e) — senarai ramuan, susunan kadar menurun mengikut berat.\nPer. 11(1)(ea) — ramuan yang boleh menyebabkan hipersensitiviti mesti dinyatakan.\nPer. 11(1)(g) — aditif ditulis sebagai kelas fungsian + nama, atau nombor INS dalam kurungan.\n\nUrutan semakan yang menjimatkan cetakan semula: mula pada panel depan, bukan pada senarai ramuan. Senaraikan apa yang ditonjolkan, padankan setiap satu dengan peratus dari formula sebenar, letakkan nombor itu bersebelahan ramuan berkenaan. Baru kunci artwork.\n\nRujukan: Peraturan-Peraturan Makanan 1985 (BM), kemas kini November 2024.\n\n#PelabelanMakanan #FSQD #KKM #SMEMalaysia","facebook":"Gambar strawberi pada pek anda menarik satu tuntutan yang ramai terlepas.\n\nSebaik sesuatu ramuan ditonjolkan pada label — pada nama produk, melalui gambar, atau dengan teks yang dibesarkan — Per. 11(1)(eb) Peraturan-Peraturan Makanan 1985 menuntut peratusnya: peratus berat atau isi padu, bersebelahan ramuan yang ditonjolkan itu.\n\nCorak yang berulang: panel depan kemas, senarai ramuan di belakang betul susunannya, dan semakan label kembali bertanya madu itu berapa peratus.\n\nQUID duduk pada blok yang sama dengan Per. 11(1)(e), 11(1)(ea) dan 11(1)(g).\n\nJadi mula pada panel depan, bukan pada senarai ramuan. Senaraikan apa yang ditonjolkan, padankan dengan peratus dari formula sebenar, letakkan nombor itu bersebelahan ramuan berkenaan — baru kunci artwork.\n\nRujukan: Peraturan-Peraturan Makanan 1985 (BM), kemas kini November 2024.\n\n#PelabelanMakanan #FSQD #KKM #SMEMalaysia","threads":"Gambar strawberi pada pek anda menarik satu tuntutan yang ramai terlepas."}}'::jsonb, 'Peraturan-Peraturan Makanan 1985 (BM), kemas kini November 2024 — Per. 11(1)(eb) dan blok senarai ramuan Per. 11(1)', '[]'::jsonb, '2026-09-19'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa401834ac55a0b10a123f7","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa40187cabd46fa08090981","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa40188a3aa88881a3621ce","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:26:00+08'::timestamptz, now(), '2026-09-05T07:11:38.491700Z'::timestamptz) on conflict (id) do nothing;  -- h20260915 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('76da37d2-61eb-56f1-aa38-0d42d3f09c3a'::uuid, '0cd95a3f-14d4-53e2-a0e0-209fa3884449'::uuid, 'regulab', 'farmaseutikal', null, 'bm', 'Ramai masih test DNA botol kapsul. NPRA dah tak minta itu lagi.', '{"bm":{"instagram":"Ramai formulator masih risau pasal satu benda yang sebenarnya dah tak dalam skop lagi.\n\nBila produk ada gelatin, contohnya dalam kapsul, ramai anggap deklarasi asal haiwan kena cover semua yang bersentuhan dengan produk sekali: botol, kapsul luar, penutup. Jadi mereka hantar semua bahan pembungkusan tu untuk ujian DNA juga, buang masa dan duit.\n\nSkop tu dah tak macam tu. Kemas kini DRGD NPRA dah keluarkan pembungkusan primer daripada penilaian dan deklarasi wajib. Ini terpakai terus untuk permohonan baharu, dan untuk produk yang sedang dalam penilaian sekarang, bukan tunggu permohonan lama habis dulu.\n\nYang masih wajib: deklarasi sumber haiwan yang tepat untuk setiap ramuan dalam produk siap itu sendiri, bukan bekasnya. Kalau kapsul guna gelatin babi, kena state ''PORCINE ORIGIN'' untuk bahan aktif, eksipien, pengawet dan kapsul, semua kena disebut, bukan satu je.\n\nKalau ujian DNA anda negatif, itu boleh tambah kenyataan pada kotak luar. Tapi keputusan negatif tu tak automatik buang keperluan deklarasi asas, melainkan ada bukti saintifik yang bahan haiwan tu memang tiada langsung dalam formulasi.\n\nJadi soalan sebenar bukan ''botol kena declare ke tak'', tapi ''setiap ramuan dalam produk siap ni dah declare dengan betul ke belum''.","facebook":"Ramai anggap deklarasi bahan asal haiwan (contoh gelatin dalam kapsul) kena cover botol, kapsul luar dan penutup sekali. Sebenarnya NPRA dah keluarkan pembungkusan primer daripada skop wajib itu, terpakai serta-merta untuk permohonan baharu dan produk yang sedang dinilai.\n\nYang masih wajib: deklarasi sumber haiwan tepat untuk setiap ramuan dalam produk siap, contohnya ''PORCINE ORIGIN'' untuk bahan aktif, eksipien, pengawet dan kapsul. Ujian DNA negatif boleh tambah kenyataan pada kotak luar, tapi tak buang keperluan deklarasi asas melainkan ada bukti saintifik ketiadaan bahan haiwan.","threads":"Ramai masih test DNA botol dan penutup kapsul sebab ingat itu wajib untuk deklarasi asal haiwan. Skop tu dah dikeluarkan oleh NPRA. Yang wajib sekarang: deklarasi tepat untuk setiap ramuan dalam produk siap, bukan bekasnya."}}'::jsonb, '', '[]'::jsonb, '2026-09-21'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aae721c076fd8348fc707ed","at":"2026-09-19 19:29 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aae722c076fd8348fc70916","at":"2026-09-19 19:29 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aae7238f4364554a89b0cf1","at":"2026-09-19 19:30 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-19 19:30:00+08'::timestamptz, now(), '2026-09-19T04:20:49.252Z'::timestamptz) on conflict (id) do nothing;  -- j00dibqipf (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('62fc7c2c-367f-5a7a-bd2e-c4936440c912'::uuid, 'bfdb7761-6059-5fd4-89a3-0eae0d08522c'::uuid, 'regulab', 'sains_kosmetik', null, 'bm', '88 wanita, 112 hari, satu regimen selepas laser. Bukan sekadar ''soothing'' atas label.', '{"bm":{"instagram":"Ramai brand tempatan letak label ''post-laser recovery cream'' atau ''barrier repair serum'' atas rak. Bila anda tanya data di belakang dakwaan tu, selalunya cuma senarai bahan yang dikatakan ''lembut'' pada kulit. Itu bukan bukti, itu pemasaran.\n\nAda kajian klinikal rawak terkawal (RCT) melibatkan 88 wanita, dijalankan selama 112 hari, menguji regimen krim dan serum mengandungi niacinamide, Pro-Xylane dan panthenol selepas prosedur laser jenis PicoWay. Pada hari ke-14, kumpulan yang guna regimen ini catat TEWL (kehilangan air transepidermal) lebih rendah dan hidrasi lebih tinggi berbanding kawalan. Selepas 112 hari, ada penambahbaikan pada kekenyalan, kedutan dan tona kulit.\n\nUntuk formulator dan brand tempatan: tiga bahan ni bukan eksklusif, sesiapa boleh dapat niacinamide, Pro-Xylane, panthenol daripada supplier. Yang buat beza ialah protokol ujian, tempoh dan populasi kulit yang diuji. Kalau nak dakwa produk anda ''sesuai selepas laser'', dakwaan tu kena disandarkan pada data protokol macam ni, bukan sekadar senarai bahan yang bunyi menenangkan.\n\nNPRA nilai dakwaan kosmetik berdasarkan bukti sokongan sebenar, bukan reputasi bahan individu. Tiada data khusus post-procedure, jangan letak dakwaan post-procedure.","facebook":"Brand tempatan suka letak ''post-laser recovery'' atau ''barrier repair'' atas botol tanpa data khusus. Ada RCT 88 wanita, 112 hari, uji regimen niacinamide, Pro-Xylane dan panthenol selepas laser PicoWay: TEWL lebih rendah dan hidrasi lebih tinggi pada hari ke-14, kekenyalan dan tona kulit bertambah baik lepas 112 hari.\n\nTiga bahan ni sendiri tak eksklusif. Yang bagi kredibiliti ialah protokol ujian dan tempoh. Dakwaan ''sesuai selepas laser'' patut disandarkan pada data macam ni, bukan senarai bahan yang bunyi lembut.","threads":"''Post-laser recovery cream'' atas label tanpa data khusus itu cuma pemasaran. RCT 88 wanita, 112 hari, regimen niacinamide + Pro-Xylane + panthenol selepas PicoWay: TEWL turun, hidrasi naik hari ke-14, tona kulit membaik lepas 112 hari. Dakwaan macam ni kena ada protokol, bukan sekadar bahan lembut."}}'::jsonb, 'Liu H, Li B, He X, et al. Skin barrier repairing and anti-aging effects evaluation of a comprehensive topical regimen incorporating niacinamide, Pro-Xylane, and panthenol after PicoWay laser: a randomized controlled study. Lasers Med Sci. 2026;41(1):212. doi:10.1007/s10103-026-04995-1', '[]'::jsonb, '2026-09-25'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab5a3f1355ed92ff3e72867","at":"2026-09-25 06:29 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab5a3fef9c76b6998c3fe30","at":"2026-09-25 06:29 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab5a406f9c76b6998c3fe92","at":"2026-09-25 06:29 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-25 06:29:00+08'::timestamptz, now(), '2026-09-23T06:29:36.458Z'::timestamptz) on conflict (id) do nothing;  -- j2ii0e3jqj (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('49c11700-f9d9-5248-bf23-bd1487b7a606'::uuid, null, 'linkedin', null, 'D', 'en', 'Silver in cosmetics just got safer on paper, and the reason sits in the particle size, not the element.', '{"en":{"linkedin":"Silver in cosmetics just got safer on paper, and the reason sits in the particle size, not the element.\n\nOn 30 July 2026, the EU notified the WTO of a draft amending the Cosmetics Regulation on the use of Silver. The text follows SCCS scientific advice and would broaden permitted uses of micron-sized Silver well beyond the current restrictions.\n\nThe mechanism is worth sitting with. Margin of safety is NOAEL divided by systemic exposure dose, and exposure dose depends on how much of the substance actually crosses the skin. Micron-sized particles penetrate less than ionic or nano-scale Silver, so the absorbed dose drops, and the margin of safety rises for the same nominal concentration on the label.\n\nSame element, same INCI name on paper. Different particle size, different margin of safety, different regulatory outcome.\n\nA concentration limit in cosmetics is rarely a statement about the ingredient. It is a statement about the exposure term measured for that specific physical form of it.\n\nSources:\nSecondary regulatory reporting on the EU WTO TBT notification, Silver in cosmetics, 30 July 2026 [I]\nSCCS scientific advice on Silver\n\n#Cosmetics #SCCS #Silver #RegulatoryAffairs #ProductSafety"}}'::jsonb, 'Draft Regulation amending the EU Cosmetics Regulation re: Silver, WTO TBT notification 30 July 2026, following SCCS scientific advice (via secondary reporting)', '[]'::jsonb, '2026-09-06'::date, '08:30', 'posted', '[]'::jsonb, 0, '{"linkedin":{"at":"2026-09-06 21:28 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7502357089265061888/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-06 21:28:00+08'::timestamptz, now(), '2026-09-05T07:27:39.000Z'::timestamptz) on conflict (id) do nothing;  -- l20260906 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('d53920d3-b3cc-52c9-884c-a9a1720d418f'::uuid, null, 'linkedin', null, 'D', 'en', 'Bakuchiol and NMN just graduated in China, and "graduated" is the operative word.', '{"en":{"linkedin":"Bakuchiol and NMN just graduated in China, and \"graduated\" is the operative word.\n\nOn 19 August 2026, China''s NMPA moved four ingredients out of mandatory safety monitoring and into IECIC List II: Bakuchiol, beta-Nicotinamide Mononucleotide (NMN), Azelamidopropyl Dimethylamine, and a cetyl diglyceryl tris(trimethylsiloxy)silylethyl dimethicone silicone.\n\nThe mechanism is the interesting part. A New Cosmetic Ingredient registered in China carries a mandatory three-year monitoring period. During those three years the registrant files annual reports on usage volume and safety signals, and NMPA can order a fresh safety assessment if anything looks off. Clear the three years with no red flags, and the ingredient moves to List II: an existing ingredient any manufacturer can use, no fresh registration required.\n\nBakuchiol and NMN are two of the most-watched actives in skincare right now, and this is what \"cleared for general use in China\" actually means procedurally. Not a single approval event. A monitoring clock that ran out clean.\n\n#ChinaCosmetics #NMPA #RegulatoryAffairs #IngredientCompliance #CosmeticRegulation"}}'::jsonb, 'NMPA, fifth dynamic adjustment to the Inventory of Existing Cosmetic Ingredients in China (IECIC), 19 August 2026 (via secondary reporting)', '[]'::jsonb, '2026-09-23'::date, '06:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7508292717735546880","at":"2026-09-23T06:34 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7508292717735546880","via":"ws.regulab Studio"}}'::jsonb, '2026-09-23 06:34:00+08'::timestamptz, now(), '2026-09-13T14:05:00.000Z'::timestamptz) on conflict (id) do nothing;  -- l20260914 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('50841a7a-c076-58a5-ac1b-095475906bd7'::uuid, null, 'linkedin', null, 'A', 'en', 'From 27 September, writing ''eco-friendly'' on a cosmetic label needs proof, not a hunch.', '{"en":{"linkedin":"From 27 September, writing ''eco-friendly'' on a cosmetic label needs proof, not a hunch.\n\nDirective (EU) 2024/825 amends the EU''s unfair commercial practices rules and becomes applicable in member states on 27 September 2026, ten days from now. It targets exactly the shorthand a lot of cosmetic packaging leans on: eco-friendly, green, biodegradable, climate friendly, natural, used as a blanket claim rather than tied to one named, measurable attribute.\n\nA generic claim like that is banned outright unless it rests on independently verified, recognised excellent environmental performance. A specific claim, recycled content in a named component, backed by evidence, stays allowed. A forward-looking claim, a 2030 target, stays allowed only with a public implementation plan and third-party verification behind it.\n\nFor a brand shipping into the EU, the packaging on shelf on 27 September is the packaging that already has to meet this. Stock printed with an unsubstantiated ''eco-friendly'' does not get a grace period because the artwork was signed off earlier in the year.\n\n#EUCompliance #GreenClaims #Cosmetics #RegulatoryAffairs #Greenwashing"}}'::jsonb, 'Directive (EU) 2024/825 of the European Parliament and of the Council, amending Directives 2005/29/EC and 2011/83/EU, applicable in EU member states from 27 September 2026', '[]'::jsonb, '2026-09-24'::date, '06:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7508848961542127617","at":"2026-09-24 19:25 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7508848961542127617/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-24 19:25:00+08'::timestamptz, now(), '2026-09-17T13:45:00.000Z'::timestamptz) on conflict (id) do nothing;  -- l20260926 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('a6e00a37-b02c-5d6e-a9e8-fb6235f8a99b'::uuid, '8f2ea12e-216a-5c59-891e-56c7c22e264d'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Ramai reseller kosmetik Korea fikir asalkan batch number sah dan jenama betul, mereka dah selamat. Itu silap besar.', '{"bm":{"instagram":"Ramai reseller kosmetik Korea fikir asalkan batch number sah dan jenama betul, mereka dah selamat. Itu silap besar.\n\nKeselamatan produk bukan setakat pasal formula. Ia juga pasal saluran produk tu masuk pasaran. Bila produk masuk melalui parallel import, di luar rantaian pengedar rasmi (official distributor) jenama tu, tiada jaminan ia melalui ujian atau notifikasi yang sama macam produk yang masuk secara rasmi. Kotak sama, batch number sama, tapi laluan masuk berbeza, dan itu yang tentukan sama ada produk tu clear bila authority buat spot check.\n\nUntuk pasaran Malaysia, ini penting sebab NPRA letak tanggungjawab notifikasi pada Cosmetic Notification Holder (CNH), bukan semata-mata pada produk itu sendiri. Kalau anda reseller yang import terus tanpa lalui CNH berdaftar untuk produk tu, anda sebenarnya di luar rejim notifikasi yang sepatutnya lindungi produk itu.\n\nJenama tulen tak bermakna saluran anda selamat.","facebook":"Ramai reseller kosmetik Korea anggap asalkan batch dan jenama tulen, mereka selamat daripada tindakan authority. Sebenarnya risiko bukan setakat keaslian produk, ia pasal saluran masuk.\n\nProduk yang masuk luar rantaian pengedar rasmi tiada jaminan lalui ujian atau notifikasi sama macam produk rasmi, walaupun kotak dan batch nampak sama.\n\nNPRA letak tanggungjawab notifikasi pada Cosmetic Notification Holder, bukan pada produk semata-mata.","threads":"Batch sah, jenama sah, tak bermakna produk tu selamat dari recall. Saluran masuk yang tentukan, bukan sekadar keaslian. Parallel import di luar CNH berdaftar bermakna produk tu di luar rejim notifikasi NPRA yang sepatutnya lindungi dia"}}'::jsonb, 'Guidelines for Control of Cosmetic Products in Malaysia (2nd Ed, NPRA)', '[]'::jsonb, '2026-09-21'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aae71db560f708e815723f7","at":"2026-09-19 19:28 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aae71ea076fd8348fc70044","at":"2026-09-19 19:28 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aae7201560f708e81572763","at":"2026-09-19 19:29 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-19 19:29:00+08'::timestamptz, now(), '2026-09-19T04:11:23.934Z'::timestamptz) on conflict (id) do nothing;  -- ma77cbeeis (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('7916850e-02ae-59c0-9a22-6ee726492586'::uuid, 'c4b01fb0-28e2-5230-b09a-4d219081ba80'::uuid, 'regulab', 'halal_my', null, 'bm', 'Video DNA babi Cadbury tular balik. JAKIM sendiri dah label ini isu lama, bukan penemuan baharu.', '{"bm":{"instagram":"Video DNA babi dalam Cadbury Dairy Milk Hazelnut tular balik. Ini bukan berita baharu.\n\nJAKIM sendiri dah letak isu ni dalam senarai Isu-Isu Tular Halal di laman rasmi Bahagian Pengurusan Halal. Kenyataan media asal dikeluarkan pada 24 Mei 2014. Kedua-dua produk, Hazelnut dan Roast Almond, kekal sebagai pemegang SPHM yang sah sehingga hari ini.\n\nSoalan yang patut ditanya bukan ''kenapa video ni tular lagi'', tapi ''kenapa satu keputusan ujian boleh jadi berita bertahun-tahun''.\n\nUjian DNA sangat sensitif. Ia boleh bagi bacaan positif akibat pencemaran silang semasa pengendalian sampel di makmal, bukan semestinya daripada ramuan produk itu sendiri. Satu sampel, satu keputusan, tak sama dengan status sesebuah kilang.\n\nSebab itulah rejim pensijilan tak bergantung pada satu keputusan makmal je. Ia bergantung pada audit rantaian bekalan dan Sistem Jaminan Halal syarikat secara berterusan, bukan snapshot sekali sahaja.\n\nKalau anda usahawan yang tengah proses sijil halal, ini poin penting untuk difahami: satu insiden pencemaran silang yang dikesan dan diuruskan ikut prosedur bukan automatik gugurkan sijil. Sistem jaminan halal anda yang menentukan, bukan satu keputusan makmal yang terpencil.","facebook":"Video DNA babi Cadbury tular lagi. JAKIM dah letak ni dalam senarai Isu-Isu Tular Halal rasmi, kenyataan asal 24 Mei 2014, dan kedua-dua produk kekal SPHM sah sampai hari ini.\n\nPoin sebenar: satu keputusan ujian DNA daripada satu sampel bukan status sesebuah kilang. Ujian DNA sensitif, boleh terkesan pencemaran silang semasa pengendalian sampel, bukan ramuan.\n\nSebab itu pensijilan bergantung pada audit rantaian bekalan dan Sistem Jaminan Halal, bukan satu keputusan makmal.","threads":"Video DNA babi Cadbury tular semula. JAKIM dah sendiri label ni isu lama dalam senarai Isu-Isu Tular Halal, asal 2014, produk masih ada SPHM sah.\n\nSatu ujian DNA dari satu sampel bukan status sesebuah kilang. Boleh jadi pencemaran silang masa handling sampel, bukan ramuan. Itu sebab pensijilan bergantung pada audit rantaian bekalan, bukan satu result makmal."}}'::jsonb, 'JAKIM Bahagian Pengurusan Halal, halaman Isu-Isu Tular Halal, kenyataan media asal 24 Mei 2014; status SPHM dibaca 19 Sept 2026', '[]'::jsonb, '2026-09-22'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab1b073826cfc54b85d82fd","at":"2026-09-22 06:32 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab1b08474d4ff403e12e270","at":"2026-09-22 06:32 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab1b0911177eabccaf0a0de","at":"2026-09-22 06:32 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-22 06:32:00+08'::timestamptz, now(), '2026-09-20T15:54:06.698Z'::timestamptz) on conflict (id) do nothing;  -- ma7maqxy36 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('a7e8a3e1-687e-5883-964c-63e92338960b'::uuid, 'a3cb13a4-6b5f-56d0-b969-9672cd9699e2'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Nombor NOT bukan nombor MAL. Kalau anda ingat kedua-dua ni sama level, produk anda dah berisiko sejak hari pertama.', '{"bm":{"instagram":"Ini silap yang saya nampak berulang kali bila syarikat baharu mula isi borang NPRA.\n\nKosmetik itu dinotifikasikan. Pemegang notifikasi isytihar formula dan maklumat produk sendiri, NPRA keluarkan nombor notifikasi, dan tiada penilaian formula dibuat sebelum produk itu masuk pasaran. Proses ini pantas sebab tanggungjawab letak pada syarikat, bukan sebab NPRA dah check semua bahan anda.\n\nUbat, produk semula jadi dan suplemen kesihatan pula lain rejim sepenuhnya: DIDAFTARKAN. Dossier dihantar, dinilai oleh penilai NPRA, dan nombor MAL keluar selepas penilaian itu selesai. Ini yang ambil masa lebih lama sebab memang ada orang duduk semak data anda.\n\nSoal praktikal untuk SME: kalau caption pemasaran anda cakap pasal menyembuhkan, merawat atau memulihkan sesuatu keadaan kulit atau kesihatan, anda dah masuk bahasa rejim pendaftaran. Ini berlaku walaupun produk anda dinotifikasikan sebagai kosmetik dengan nombor NOT. Jurang antara apa produk anda didaftarkan sebagai, dengan apa caption anda cakap, itulah yang jadi isu bila pihak berkuasa check.\n\nSebelum ambil stok atau lantik ejen jual, semak dulu nombor tu di laman NPRA. Bukan sekadar nombor tu wujud, tapi check ia keluar bawah rejim yang betul untuk jenis produk anda.","facebook":"Nombor NOT (notifikasi kosmetik) dan nombor MAL (pendaftaran ubat/suplemen) bukan benda sama.\n\nKosmetik: syarikat isytihar formula sendiri, nombor keluar, tiada penilaian formula sebelum masuk pasaran.\n\nUbat/suplemen: dossier dinilai dulu oleh NPRA, baru nombor MAL keluar.\n\nKalau caption anda cakap ''sembuh'' atau ''rawat'', anda dah bercakap bahasa pendaftaran walaupun produk anda notifikasi kosmetik. Tu jurang yang buat satu ayat caption jadi isu regulatori.\n\nSemak kedua-dua nombor di laman NPRA sebelum ambil stok.","threads":"NOT dan MAL bukan sama. NOT: kosmetik dinotifikasi, tiada penilaian formula. MAL: ubat/suplemen didaftar, dossier dinilai dulu baru nombor keluar. Caption cakap ''sembuh'' atau ''rawat'' pada produk NOT, anda dah masuk rejim pendaftaran tanpa sedar."}}'::jsonb, 'Guidelines for Control of Cosmetic Products in Malaysia (2nd Ed, NPRA), Seksyen 1 (notification regime)', '[]'::jsonb, '2026-09-23'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab1b0f38e2aab6eac4ea0d1","at":"2026-09-22 06:34 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab1b1058e2aab6eac4ea180","at":"2026-09-22 06:34 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab1b1121b349ea8ed977aae","at":"2026-09-22 06:34 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-22 06:34:00+08'::timestamptz, now(), '2026-09-20T09:40:44.142Z'::timestamptz) on conflict (id) do nothing;  -- mm5xe1ls8g (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('2c22bf3b-aab1-5172-9415-caca08aaef78'::uuid, '22e86f73-f0e7-52ea-a85a-63a9ffd4deab'::uuid, 'regulab', 'makanan', null, 'bm', 'Logo Healthier Choice KKM pada minuman berperisa malt buat ramai syak ada rasuah, sebab produk tu memang manis.', '{"bm":{"instagram":"Logo Healthier Choice KKM pada minuman berperisa malt buat ramai syak ada rasuah, sebab produk tu memang manis.\n\nRealitinya logo ni bukan ukur produk sihat ke tak secara keseluruhan. Kriteria nutrien untuk Healthier Choice Logo ditetapkan mengikut kategori makanan oleh Bahagian Pemakanan KKM. Maknanya satu produk dinilai terhadap kriteria kategorinya sendiri, bukan terhadap semua makanan di pasaran. Sebab tu minuman yang masih ada gula boleh layak, kalau ia menepati kriteria yang ditetapkan untuk kategori dia.\n\nIni penting untuk SME yang nak mohon logo ni atau yang produk dia kena salah faham macam ni. Bila pelanggan tanya kenapa logo sihat tapi manis, jawapan yang betul bukan nafi je. Terangkan yang logo tu keputusan teknikal dalam kategori sendiri.\n\nDan sebelum anda reka pembungkusan sekeliling logo tu, semak dulu kriteria untuk kategori anda dalam garis panduan semasa. Salah komunikasi di sini boleh buat pelanggan rasa kena tipu walaupun anda ikut prosedur betul.\n\nLogo tu bukan KKM kata produk anda sihat, titik. Ia keputusan teknikal berdasarkan perbandingan dalam kategori sendiri.","facebook":"Logo Healthier Choice KKM pada minuman berperisa malt yang manis buat ramai syak ada rasuah.\n\nSebenarnya logo ni bukan pengesahan produk sihat secara keseluruhan. Kriteria nutrien untuk logo ini ditetapkan mengikut kategori makanan oleh Bahagian Pemakanan KKM, jadi setiap produk dinilai terhadap kriteria kategorinya sendiri, bukan terhadap semua makanan. Sebab tu minuman yang masih manis boleh layak, kalau ia menepati kriteria kategori dia.\n\nSME yang nak mohon logo ni, atau yang produk dia kena salah faham macam ni, kena faham konsep ni dulu. Semak kriteria kategori anda dalam garis panduan semasa sebelum reka pembungkusan sekeliling logo tu.","threads":"Logo Healthier Choice KKM bukan cop ''produk ni sihat''. Kriteria nutriennya ditetapkan mengikut kategori makanan oleh Bahagian Pemakanan KKM, jadi produk dinilai terhadap kriteria kategorinya sendiri. Sebab tu minuman yang masih manis pun boleh layak. Semak kriteria kategori anda sebelum reka pembungkusan sekeliling logo tu."}}'::jsonb, 'Nutritional Guidelines on Nutrient Criteria for Healthier Choice Logo Malaysia, Bahagian Pemakanan, Kementerian Kesihatan Malaysia — kriteria nutrien ditetapkan mengikut kategori makanan.', '[]'::jsonb, '2026-09-09'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa1298c1b2e90ab73acc4bf","at":"2026-09-09 17:40 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa1298e871c18cb5cebb6fc","at":"2026-09-09 17:40 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa12991e66587e2e4ffd62c","at":"2026-09-09 17:40 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-09 17:40:00+08'::timestamptz, now(), '2026-09-07T15:01:39.908Z'::timestamptz) on conflict (id) do nothing;  -- mnl77jcfdf (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('6f591df6-3113-567b-b3d4-363c7e8acf24'::uuid, '3bc1747e-af92-50ee-b933-0fc16ec14bd3'::uuid, 'regulab', 'farmaseutikal', null, 'bm', 'Produk ''herba untuk kolesterol'' yang sebenarnya statin preskripsi, dan pengguna terus tak tahu', '{"bm":{"instagram":"NPRA batalkan pendaftaran PS 21 Capsule (MAL15120007TC) sebab kapsul ''tradisional'' ini didapati mengandungi simvastatin. Ramai anggap ini sekadar kes label salah. Bukan.\n\nSimvastatin ialah statin preskripsi. Ia ada interaksi ubat yang serius dan perlu pemantauan enzim hati secara berkala, itu sebab ia bukan produk over the counter pun, apatah lagi produk tradisional.\n\nMasalahnya: orang yang beli produk ini fikir mereka ambil herba, bukan ubat. Jadi bila doktor preskripsi gemfibrozil, mereka tak beritahu pun sebab tak sedar tengah ambil statin. Bila mereka minum jus limau gedang, tiada siapa amaran sebab bukan makan ''ubat''. Doktor pun tak tahu untuk semak enzim hati sebab dalam rekod, pesakit cuma ambil ''suplemen kolesterol''.\n\nIni bukan insiden terpencil. Corak yang sama berulang: produk tradisional dicampur ubat yang tepat sepadan dengan dakwaan pada label, sebab itu cara paling murah untuk buat produk ''nampak berkesan''. Kolesterol, gula, sendi, darah tinggi, semua kategori ini pernah ada kes serupa.\n\nKalau anda uruskan produk tradisional untuk kategori ini, due diligence pada bahan mentah bukan pilihan, ia sebab syarikat lain kena rampas balik seluruh batch.","facebook":"NPRA batalkan pendaftaran PS 21 Capsule sebab kapsul ''tradisional'' ini mengandungi simvastatin, statin preskripsi.\n\nBahaya sebenar bukan pada label salah. Pengguna ambil produk ini sebagai herba, jadi bila makan gemfibrozil atau minum jus limau gedang, tiada siapa amaran mereka sebab mereka tak sedar tengah ambil statin. Doktor pun tak tahu untuk semak enzim hati.\n\nCorak ini berulang: produk tradisional dicampur ubat yang tepat sepadan dakwaan pada label kerana itu cara paling murah nampak ''berkesan''.","threads":"NPRA batalkan PS 21 Capsule sebab ia mengandungi simvastatin, statin preskripsi, bukan herba.\n\nBahaya bukan label salah. Pengguna tak tahu mereka ambil statin, jadi tak elak gemfibrozil atau jus limau gedang, dan doktor tak semak enzim hati.\n\nCorak sama berulang untuk kolesterol, gula, sendi."}}'::jsonb, 'NPRA, Senarai Pembatalan Produk Semula Jadi/Tradisional Berdaftar, PS 21 Capsule MAL15120007TC, disiarkan 5 Ogos 2026', '[]'::jsonb, '2026-09-24'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab1f4e59609314f62165ed5","at":"2026-09-22 11:25 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab1f4f79609314f62165fe4","at":"2026-09-22 11:25 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab1f504ffe5c8afb1297364","at":"2026-09-22 11:25 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-22 11:25:00+08'::timestamptz, now(), '2026-09-20T09:41:45.530Z'::timestamptz) on conflict (id) do nothing;  -- odiadan3mh (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('7d95e64e-2eca-5bab-8808-d8fdbe278c10'::uuid, null, 'regulab', 'halal_my', null, 'bm', 'Ini silap yang saya nampak berulang kali. Founder dah siapkan semua dokumen syarikat, premise dah bersih, SOP dah ada, tapi bila submit permohonan MYeHALAL, kena tolak. Sebabnya bukan pada syarikat sendiri, tapi pada sijil halal pembekal bahan mentah yang di-attach sekali dalam permohonan.', '{"bm":{"instagram":"Ini silap yang saya nampak berulang kali. Founder dah siapkan semua dokumen syarikat, premise dah bersih, SOP dah ada, tapi bila submit permohonan MYeHALAL, kena tolak. Sebabnya bukan pada syarikat sendiri, tapi pada sijil halal pembekal bahan mentah yang di-attach sekali dalam permohonan.\n\nRamai tak sedar setiap sijil halal pembekal ada tarikh luput sendiri. Kalau anda simpan sijil tu dari setahun lepas untuk supplier tepung, perisa atau pewarna, dan tak check semula tarikh sah semasa nak submit, JAKIM akan reject terus kat peringkat semakan dokumen. Tak sampai pun ke tahap penilai audit premise.\n\nLagi satu isu, sesetengah pembekal tukar sijil bila renew ijazah baru, tapi nombor sijil pun berubah. Kalau anda masih guna nombor lama dalam senarai bahan (ingredient list), sistem akan flag sebagai tak sepadan.\n\nBenda ni simple check je sebenarnya, tapi ramai anggap dokumen pembekal tu \"dah settle\" sekali submit dulu, tak perlu update lagi. Padahal setiap kali nak apply atau renew, semua sijil pembekal kena refresh check status dia di MYeHALAL portal dulu.","facebook":"Permohonan Sijil Halal kena tolak, bukan sebab dokumen syarikat anda tak lengkap, tapi sebab sijil halal pembekal bahan mentah yang anda attach dah luput tarikh sah.\n\nRamai simpan sijil supplier dari setahun dua lepas, ingat dah settle. Realitinya setiap sijil ada tarikh luput sendiri, dan kalau pembekal renew, nombor sijil pun boleh berubah. Kalau senarai bahan anda masih rujuk nombor lama, sistem MYeHALAL akan flag terus.\n\nSemak semula status sijil setiap pembekal sebelum submit, bukan lepas kena reject.","threads":"Sijil Halal anda kena tolak sebab sijil pembekal yang anda attach dah luput, bukan sebab dokumen syarikat anda. Check tarikh sah setiap sijil bahan mentah dalam MYeHALAL sebelum submit, jangan guna yang simpan dari tahun lepas."}}'::jsonb, '', '[]'::jsonb, '2026-09-15'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa7dad5008f3b8d4eda5d21","at":"2026-09-14T19:30:00+08:00","via":"ws.regulab Studio"},"instagram":{"id":"6aa7dae14fdc747eb03a2fae","at":"2026-09-14T19:30:00+08:00","via":"ws.regulab Studio"},"threads":{"id":"6aa7daea008f3b8d4eda6399","at":"2026-09-14T19:30:00+08:00","via":"ws.regulab Studio"}}'::jsonb, '2026-09-15 08:00:00+08'::timestamptz, now(), '2026-09-14T10:05:56.031Z'::timestamptz) on conflict (id) do nothing;  -- oypqbsv35r (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('f4912bbb-dd9d-5361-8433-6a6525cc47ed'::uuid, '84b66d55-9803-5b3a-b7d5-b67776f34763'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Platform e-dagang minta ''sijil FDA'' sebelum boleh jual kosmetik ke AS. Dokumen itu tak wujud.', '{"bm":{"instagram":"Ramai penjual kosmetik tempatan kena tanya oleh platform e-dagang: mana sijil FDA anda? Ada yang sampai kena suspend listing sebab tak boleh upload dokumen itu.\n\nMasalahnya, dokumen yang diminta tu tak wujud. Di bawah MoCRA 2022 (seksyen 607 FD&C Act), apa yang syarikat kosmetik buat dengan FDA cuma dua benda: facility registration dan product listing. Bila dah submit dan diterima dalam sistem, anda dapat nombor pendaftaran fasiliti dan nombor penyenaraian produk. Itu sahaja.\n\nFDA sendiri dah klarifikasi, tak ada sijil, tak ada surat pengesahan pematuhan, tak ada pun surat pengecualian pendaftaran yang dikeluarkan secara rasmi untuk tujuan tunjuk kepada pihak ketiga. Kalau ada ''pihak'' yang tawarkan nak keluarkan sijil sebegini atas nama FDA, itu red flag terus.\n\nUntuk SME yang jual ke AS lewat platform sebegini, cara betul nak buktikan status pendaftaran adalah dengan quote nombor pendaftaran fasiliti dan nombor listing tu, bukan cari dokumen PDF bercop yang sebenarnya tak pernah dikeluarkan.\n\nKalau platform still insist nak sijil, itu bermakna staff support diorang pun tak faham struktur MoCRA. Bukan salah anda.","facebook":"Penjual kosmetik kena tanya platform e-dagang: mana sijil FDA anda? Dokumen tu sebenarnya tak wujud.\n\nDi bawah MoCRA 2022 (seksyen 607 FD&C Act), FDA cuma proses facility registration dan product listing. Lepas diterima, anda dapat nombor pendaftaran, bukan sijil. FDA sendiri dah sahkan tak ada sijil, tak ada surat pengesahan, tak ada surat pengecualian rasmi untuk tunjuk pihak ketiga.\n\nCara betul buktikan status: quote nombor pendaftaran fasiliti dan nombor listing terus, bukan cari dokumen yang memang tak pernah wujud.","threads":"FDA dah klarifikasi: tak ada sijil pendaftaran fasiliti kosmetik di bawah MoCRA. Tak ada surat pengesahan, tak ada surat pengecualian rasmi pun.\n\nApa yang wujud cuma nombor pendaftaran fasiliti dan nombor product listing dalam sistem FDA. Kalau platform e-dagang minta ''sijil FDA'', diorang tersilap konsep, bukan anda yang kurang dokumen."}}'::jsonb, 'FDA, MoCRA 2022, Section 607 of the FD&C Act (facility registration and product listing)', '[]'::jsonb, '2026-09-16'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa9c5e1f2c03c15de8dff8f","at":"2026-09-16 06:26 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa9c5eff2c03c15de8e0074","at":"2026-09-16 06:26 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa9c5fb83d5c8e350e6d345","at":"2026-09-16 06:26 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-16 06:26:00+08'::timestamptz, now(), '2026-09-11T12:59:06.184Z'::timestamptz) on conflict (id) do nothing;  -- p0yfsjq7mf (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('3ee37acc-4c8f-5037-b79b-22b82c6b2a2e'::uuid, '539d0ec4-8a0d-5532-b36d-26b55d8a5660'::uuid, 'regulab', 'kosmetik', null, 'bm', 'Krim malam yang dijual kaki lima tu sebenarnya regimen ubat preskripsi untuk melasma, bukan kosmetik.', '{"bm":{"instagram":"Ramai fikir asalkan pembungkusan nampak macam skincare biasa, cukup untuk dijual sebagai kosmetik. Salah.\n\nHydroquinone, tretinoin dan steroid topikal (contohnya betamethasone) dalam satu tiub itu bukan formula rawak. Itu dikenali sebagai formula Kligman, regimen ubat untuk rawat melasma yang sepatutnya bawah preskripsi dan pemantauan doktor. Sebab tu pesakit perlu tempoh henti, susulan berkala, kerana risiko atrofi kulit dan ochronosis kalau guna berpanjangan tanpa kawalan.\n\nBila produk macam ni dijual sebagai krim malam untuk kulit cerah, tiada siapa yang pantau tempoh guna. Itu bukan soal pembungkusan cantik atau tak, itu soal bahan.\n\nDi bawah Akta Racun 1952, bahan-bahan ini letakkan produk terus keluar dari definisi kosmetik. Ia jatuh bawah DRGD (Drug Registration Guidance Document) NPRA, bukan laluan notifikasi kosmetik. Tak kira apa nama jenama atau label depan tiub, kalau kandungan dia macam ni, ia ubat preskripsi. Titik.\n\nSyarikat yang jual produk macam ni bawah rejim notifikasi kosmetik memang akan kena tindakan, sebab dari awal lagi ia tak layak dinotifikasi sebagai kosmetik.","facebook":"Ramai anggap kalau pembungkusan nampak macam skincare, cukup untuk daftar sebagai kosmetik. Salah.\n\nHydroquinone + tretinoin + steroid topikal dalam satu tiub adalah formula Kligman, iaitu regimen ubat untuk melasma yang sepatutnya bawah preskripsi doktor, bukan krim malam pasaran terbuka. Tanpa tempoh henti dan susulan, risiko atrofi kulit dan ochronosis jadi nyata.\n\nDi bawah Akta Racun 1952, bahan begini keluarkan produk dari definisi kosmetik terus. Ia jatuh bawah DRGD NPRA, bukan notifikasi kosmetik, tak kira apa label di depan tiub.","threads":"Hydroquinone + tretinoin + steroid topikal dalam satu tiub bukan krim malam biasa. Itu formula Kligman, regimen ubat melasma yang sepatutnya bawah preskripsi doktor.\n\nDi bawah Akta Racun 1952, bahan ni keluarkan produk dari status kosmetik. Ia jatuh bawah DRGD NPRA, bukan notifikasi kosmetik. Label depan tiub tak ubah hakikat ni."}}'::jsonb, 'Akta Racun 1952 (Poisons Act 1952); Guidelines for Control of Cosmetic Products in Malaysia (2nd Ed, NPRA), definisi sempadan kosmetik/ubat; DRGD (Drug Registration Guidance Document), NPRA', '[]'::jsonb, '2026-09-25'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab301e098ae6feaa61c1d1a","at":"2026-09-23T06:32 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab301ed2aa0e20bb46a434a","at":"2026-09-23T06:32 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab301f798ae6feaa61c1e45","at":"2026-09-23T06:32 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-23 06:32:00+08'::timestamptz, now(), '2026-09-20T16:20:32.974Z'::timestamptz) on conflict (id) do nothing;  -- q8eqj5vy4j (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('834b4def-f979-50f5-8e92-a9828fe5b01a'::uuid, null, 'regulab', 'makanan', null, 'bm', 'Rokok elektronik dan vape bukan lagi ''produk makanan'' di bawah Akta Makanan 1983.', '{"bm":{"instagram":"Rokok elektronik dan vape bukan lagi ''produk makanan'' di bawah Akta Makanan 1983.\n\nAkta Makanan (Pindaan) 2024 [Akta A1702] mendapat perkenan diraja pada 24 Januari 2024 dan diwartakan pada 2 Februari 2024, tetapi ia tidak berkuat kuasa pada tarikh itu. Seksyen 1(2) serahkan tarikh permulaan kuat kuasa kepada Menteri, dan Menteri menetapkannya melalui P.U. (B) 386/2024: berkuat kuasa 1 Oktober 2024.\n\nSejak tarikh itu, takrif ''tembakau'' dan ''hasil tembakau'' dibuang daripada Seksyen 2 Akta Makanan 1983, dan Seksyen 36, peruntukan lama yang meletakkan hasil tembakau di bawah kawalan akta makanan, dimansuhkan sepenuhnya.\n\nApa-apa pendaftaran, notis, arahan atau kelulusan sedia ada berkaitan hasil tembakau di bawah Seksyen 36 lama tidak hilang begitu saja. Ia dipindah untuk diuruskan di bawah Akta Kawalan Produk Merokok Demi Kesihatan Awam 2024 [Akta 852].\n\nUntuk SME yang buat atau edar e-liquid, vape, rokok elektronik atau produk tembakau lain: ini bukan lagi laluan notifikasi FSQD/BKKM di bawah Akta Makanan. Regulator, borang dan proses kelulusan kini sepenuhnya berlainan daripada produk makanan biasa.\n\nRujukan: Akta Makanan (Pindaan) 2024 [Akta A1702], berkuat kuasa 1 Oktober 2024 melalui P.U. (B) 386/2024; Akta Kawalan Produk Merokok Demi Kesihatan Awam 2024 [Akta 852].\n\n#KKM #FSQD #SMEMalaysia #RegulatoryAffairs #UsahawanMalaysia","facebook":"Rokok elektronik dan vape bukan lagi ''produk makanan'' di bawah Akta Makanan 1983.\n\nAkta Makanan (Pindaan) 2024 [Akta A1702] diwartakan 2 Februari 2024, tetapi tarikh kuat kuasanya ditetapkan berasingan oleh Menteri melalui P.U. (B) 386/2024: 1 Oktober 2024. Sejak tarikh itu takrif ''tembakau'' dan ''hasil tembakau'' dibuang daripada Seksyen 2, dan Seksyen 36 dimansuhkan.\n\nPendaftaran, notis, arahan atau kelulusan sedia ada di bawah Seksyen 36 lama dipindah ke Akta Kawalan Produk Merokok Demi Kesihatan Awam 2024 [Akta 852].\n\nUntuk SME e-liquid, vape dan hasil tembakau: bukan lagi laluan FSQD/BKKM di bawah Akta Makanan.\n\n#KKM #FSQD #SMEMalaysia","threads":"Vape dan rokok elektronik bukan lagi ''produk makanan''.\n\nAkta Makanan (Pindaan) 2024 [Akta A1702] berkuat kuasa 1 Oktober 2024 melalui P.U. (B) 386/2024, bukan pada tarikh ia diwartakan. Takrif hasil tembakau keluar dari Seksyen 2, Seksyen 36 dimansuhkan, dan semuanya berpindah ke Akta 852.\n\n#KKM"}}'::jsonb, 'Akta Makanan (Pindaan) 2024 [Akta A1702], perkenan diraja 24 Januari 2024, diwartakan 2 Februari 2024, berkuat kuasa 1 Oktober 2024 melalui P.U. (B) 386/2024; Akta Kawalan Produk Merokok Demi Kesihatan Awam 2024 [Akta 852]', '[]'::jsonb, '2026-09-09'::date, '17:33', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa127dfe66587e2e4ffb93d","at":"2026-09-09 17:33 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa127e57f00355254d52b3a","at":"2026-09-09 17:33 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa127ef964147bf5c6d8e4e","at":"2026-09-09 17:33 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-09 17:33:00+08'::timestamptz, now(), '2026-09-08T13:45:00.000Z'::timestamptz) on conflict (id) do nothing;  -- r20260908b (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('bff53461-ba62-53a4-8dcf-59d337de3f58'::uuid, null, 'regulab', 'farmaseutikal', null, 'bm', 'Notifikasi NPRA lulus bukan noktah akhir. NPRA terus pantau produk anda selepas ia sampai ke pasaran.', '{"bm":{"instagram":"Notifikasi NPRA anda dah lulus. Ramai founder anggap itu garisan penamat. Bukan.\n\nNPRA jalankan Product Quality Monitoring (PQM) untuk pantau produk yang dah ada di pasaran. Program ini merangkumi lapan perkara: sampling produk, ujian makmal, pemantauan pematuhan label, pengendalian laporan kualiti, pengendalian laporan out-of-specification, pemantauan tindakan regulatori untuk produk tak patuh, pemantauan recall sukarela, dan komunikasi risiko.\n\nSampel diambil daripada batch pengeluaran yang sama, dalam pembungkusan asal, dan diuji di makmal NPRA untuk identifikasi, assay, disintegrasi/pelarutan, ujian mikrobiologi, logam berat, bahan berkaitan/kekotoran, sterili, dan skrining bahan adulteran.\n\nKalau keputusan jumpa produk anda tak patuh, NPRA boleh gantung atau batalkan pendaftaran di bawah Peraturan 11, Peraturan-Peraturan Kawalan Dadah dan Kosmetik 1984, bila ada risiko kesihatan sebenar atau berpotensi seperti bahan adulteran atau isu kualiti yang tak diselesaikan.\n\nKes adulterasi bawa tindakan paling berat: pendaftaran dibatalkan, semua batch direcall serta-merta, lesen pengilang digantung 6 bulan untuk kesalahan pertama atau 1 tahun untuk kesalahan berikutnya, dan semua transaksi lain PRH itu, termasuk permohonan pendaftaran baru, tukar PRH, dan tukar tapak pengilangan, turut dibekukan tempoh yang sama.\n\nPRH bertanggungjawab jaga sistem sendiri untuk siasat dan lapor isu kualiti kepada NPRA.\n\n#NPRA #PendaftaranProduk #Farmaseutikal #SMEMalaysia #RegulatoryAffairs #UsahawanMalaysia","facebook":"Notifikasi NPRA lulus bukan noktah akhir. NPRA terus pantau produk anda selepas ia sampai ke pasaran.\n\nMelalui program Product Quality Monitoring (PQM), NPRA ambil sampel, uji makmal, semak pematuhan label, dan skrin bahan adulteran daripada produk yang dah berdaftar.\n\nKalau didapati adulterated, tindakan terus: pendaftaran dibatalkan, semua batch direcall serta-merta, lesen pengilang digantung 6 bulan untuk kesalahan pertama, 1 tahun untuk kesalahan berikutnya. Semua permohonan lain PRH turut dibekukan tempoh yang sama.\n\n#NPRA #Farmaseutikal #SMEMalaysia","threads":"Notifikasi NPRA lulus bukan noktah akhir. NPRA terus pantau produk anda di pasaran lewat Product Quality Monitoring: sampling, ujian makmal, semak label, sampai skrin bahan adulteran.\n\nProduk didapati adulterated: pendaftaran dibatalkan, batch direcall, lesen pengilang digantung 6 bulan hingga 1 tahun, semua permohonan lain PRH turut dibekukan.\n\n#NPRA"}}'::jsonb, 'DRGD 3rd Edition, 12th Revision, Julai 2026, Seksyen 21.2, 21.2.1, 21.2.7, 21.2.8', '[]'::jsonb, '2026-09-17'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aab1714f50aa6b642fca70d","at":"17 Sep 2026, 6:24 AM MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aaa7cdabb0dc2fb6ea15c4b","at":"16 Sep 2026, 7:26 PM MYT","via":"ws.regulab Studio"},"threads":{"id":"6aab171c246d54e666adc07f","at":"17 Sep 2026, 6:24 AM MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-17 08:00:00+08'::timestamptz, now(), '2026-09-10T13:55:00.000Z'::timestamptz) on conflict (id) do nothing;  -- r20260910 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('861c8a3b-a6b7-542e-a693-77731b48ae1f'::uuid, null, 'regulab', 'kosmetik', null, 'bm', '"Produk saya rawat jerawat sampai hilang." — ayat ini boleh gagalkan notifikasi NPRA anda.', '{"bm":{"instagram":"\"Produk saya rawat jerawat sampai hilang.\" — ayat ini boleh gagalkan notifikasi NPRA anda.\n\nSeksyen 3.5 Guidelines for Control of Cosmetic Products in Malaysia (NPRA) tetapkan: kosmetik tidak boleh guna nama atau dakwaan yang dianggap bersifat perubatan atau di luar skop kosmetik.\n\nPerkataan seperti ''rawat'', ''sembuh'' atau ''matikan kuman sepenuhnya'' membawa produk anda keluar dari skop kosmetik terus ke skop perubatan — dan itu bukan laluan notifikasi kosmetik lagi.\n\nYang ramai tak sedar: Seksyen 4.1.1 sahkan skrining post-market NPRA termasuk NAMA PRODUK dan dakwaan yang dibuat, bukan setakat kandungan formula. Nama produk anda pun boleh jadi sebab ditolak.\n\nGanti dengan ayat yang describe fungsi kosmetik, bukan janji perubatan: ''membantu mengurangkan penampilan jerawat'' bukan ''merawat jerawat''. ''diformulasi untuk kulit berjerawat'' bukan ''sembuhkan jerawat''.\n\nGuideline sendiri nasihatkan: dapatkan nasihat pakar undang-undang sebelum kunci dakwaan pada artwork.\n\nSoalan anda mungkin jadi post esok.\n\nRujukan: Guidelines for Control of Cosmetic Products in Malaysia, 2nd Ed (NPRA), Seksyen 3.5, 4.1.1, Annex I Part 8.\n\n#Kosmetik #NPRA #CNH #SMEMalaysia","facebook":"\"Produk saya rawat jerawat sampai hilang.\" — ayat ini boleh gagalkan notifikasi NPRA anda.\n\nSeksyen 3.5 Guidelines NPRA: kosmetik tak boleh guna nama atau dakwaan bersifat perubatan. ''Rawat'', ''sembuh'', ''matikan kuman sepenuhnya'' bawa produk anda keluar skop kosmetik.\n\nSeksyen 4.1.1 sahkan NPRA skrining nama produk dan dakwaan, bukan setakat formula. Ganti dengan ''membantu mengurangkan penampilan jerawat'', bukan ''rawat jerawat''.\n\n#Kosmetik #NPRA #SMEMalaysia","threads":"\"Produk saya rawat jerawat sampai hilang.\"\n\nAyat ini boleh gagalkan notifikasi NPRA anda. Seksyen 3.5: kosmetik tak boleh guna dakwaan bersifat perubatan.\n\nNPRA skrining nama produk juga, bukan setakat formula. Tukar ''rawat'' kepada ''bantu kurangkan penampilan''.\n\n#Kosmetik"}}'::jsonb, 'Guidelines for Control of Cosmetic Products in Malaysia, 2nd Ed (NPRA), Seksyen 3.5 (Cosmetic Claims), Seksyen 4.1.1 (skrining PMS termasuk nama produk dan dakwaan), Annex I Part 8', '[]'::jsonb, '2026-09-14'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa4018b262bdff0e87c065b","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa4018ccabd46fa080909f0","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa40190cabd46fa08090a36","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:26:00+08'::timestamptz, now(), '2026-09-05T12:41:22.927980Z'::timestamptz) on conflict (id) do nothing;  -- r20260914 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('dac5bceb-2328-5a54-b3f6-44148c918f6b'::uuid, null, 'regulab', 'makanan', null, 'bm', 'MeSTI bukan sijil ''bonus'' untuk cantikkan profil syarikat anda.', '{"bm":{"instagram":"MeSTI bukan sijil ''bonus'' untuk cantikkan profil syarikat anda.\n\nPeraturan-Peraturan Kebersihan Makanan (PPKM) 2009 dah mewajibkan setiap empunya dan penghuni premis pengilangan makanan menyediakan dan mengadakan satu Program Jaminan Keselamatan Makanan (PJKM). PJKM itu satu sistem amalan terancang yang didokumenkan, yang memberi jaminan makanan anda tidak memudaratkan pengguna apabila dimakan.\n\nGMP, HACCP dan ISO 22000 semuanya PJKM. Tiga-tiga itu berat untuk PKS, dan itulah sebabnya KKM perkenalkan MeSTI: satu skim yang mudah diperoleh dan memenuhi keperluan minima yang diperuntukkan dalam PPKM 2009. MeSTI ini bukan skim baharu pun, ia jenama semula bagi Skim Keselamatan Makanan 1Malaysia (SK1M).\n\nJadi soalan yang betul bukan ''perlu ke saya ambil MeSTI''. Soalannya PJKM mana yang anda pilih untuk tunaikan kewajipan yang memang dah ada atas premis anda.\n\nDua perkara praktikal:\n\nPermohonan MeSTI dibuat atas talian melalui sistem FoSIM.\n\nSenarai pemegang Sijil MeSTI terbuka kepada awam di Akses Awam FoSIM, jadi status premis boleh disemak sesiapa sahaja, termasuk pembeli korporat anda dan anda sendiri terhadap pembekal anda.\n\nGaris Panduan Pensijilan MeSTI versi terkini dimuat naik pada 14 Julai 2026 di laman BKKM.\n\nRujukan: Bahagian Keselamatan dan Kualiti Makanan KKM, laman Pensijilan Makanan Selamat Tanggungjawab Industri (MeSTI).\n\n#KKM #FSQD #BKKM #SMEMalaysia #UsahawanMalaysia","facebook":"MeSTI bukan sijil ''bonus'' untuk cantikkan profil syarikat anda.\n\nPeraturan-Peraturan Kebersihan Makanan (PPKM) 2009 dah mewajibkan setiap empunya dan penghuni premis pengilangan makanan menyediakan dan mengadakan satu Program Jaminan Keselamatan Makanan (PJKM). GMP, HACCP dan ISO 22000 semuanya PJKM. Tiga-tiga itu berat untuk PKS.\n\nSebab itu KKM perkenalkan MeSTI: skim yang mudah diperoleh dan memenuhi keperluan minima yang diperuntukkan dalam PPKM 2009.\n\nJadi soalannya bukan ''perlu ke MeSTI''. Soalannya PJKM mana yang anda pilih.\n\nRujukan: BKKM KKM, laman Pensijilan MeSTI.\n\n#KKM #FSQD #SMEMalaysia","threads":"MeSTI bukan sijil ''bonus'' untuk cantikkan profil syarikat anda.\n\nPPKM 2009 dah mewajibkan setiap premis pengilangan makanan ada satu Program Jaminan Keselamatan Makanan. GMP, HACCP, ISO 22000 semuanya kira. MeSTI cuma yang paling mudah dicapai untuk PKS.\n\nSoalannya bukan ''perlu ke''. Soalannya yang mana.\n\n#KKM"}}'::jsonb, 'Bahagian Keselamatan dan Kualiti Makanan, KKM, laman Pensijilan Makanan Selamat Tanggungjawab Industri (MeSTI), hq.moh.gov.my/fsq/mesti; Peraturan-Peraturan Kebersihan Makanan 2009; Garis Panduan Pensijilan MeSTI dimuat naik 14 Julai 2026', '[]'::jsonb, '2026-09-18'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aabcd976f3b085174aaf47a","at":"17 Sep 2026, 7:23 PM MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aab1761883b10a2a9b8bc12","at":"17 Sep 2026, 6:25 AM MYT","via":"ws.regulab Studio"},"threads":{"id":"6aabcda479f9a650af5ac64e","at":"17 Sep 2026, 7:23 PM MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-18 13:00:00+08'::timestamptz, now(), '2026-09-10T02:33:56.247986Z'::timestamptz) on conflict (id) do nothing;  -- r20260915c (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('c787cc3e-1580-53c1-a428-4cafca1fae27'::uuid, null, 'regulab', 'halal_my', null, 'bm', 'Produk import anda ada logo halal negara asal — itu tak automatik sah di Malaysia.', '{"bm":{"instagram":"Produk import anda ada logo halal negara asal — itu tak automatik sah di Malaysia.\n\nPara 5(1) Trade Descriptions Act (Certification and Marking of Halal) Order 2011 kata jelas: makanan dan barangan import yang dipasarkan di Malaysia tak boleh dikatakan halal melainkan ia disahkan oleh badan pensijilan halal asing yang DIIKTIRAF JAKIM.\n\nBukan mana-mana sijil pun dikira. JAKIM keluarkan senarai Recognized Foreign Halal Certification Bodies (FHCB) — gazet terkini berkuat kuasa 21 Ogos 2026 — merangkumi 96 badan pensijilan di 49 negara. Kalau badan yang mengesahkan produk anda tiada dalam senarai itu, sijil tu tak boleh jadi asas dakwaan halal di sini.\n\nPengiktirafan pun ada tempoh: sah 3 tahun, disemak semula selepas tamat, dan badan berkenaan kena hantar laporan tahunan kepada JAKIM.\n\nSatu lagi kewajipan yang ramai terlepas — Para 5(2): pengimport atau pengilang WAJIB tandakan nama badan pensijilan asing itu pada produk atau barangan berkenaan. Bukan sekadar cetak logo halal generik.\n\nSebelum letak apa-apa dakwaan halal pada packaging: semak senarai FHCB terkini dan status badan pensijilan pembekal anda di myehalal.halal.gov.my.\n\nRujukan: Trade Descriptions Act (Certification and Marking of Halal) Order 2011, Para 5(1)&(2); Senarai FHCB JAKIM, berkuat kuasa 21 Ogos 2026.\n\n#SijilHalal #JAKIM #HalalMalaysia #SMEMalaysia","facebook":"Produk import anda ada logo halal negara asal — itu tak automatik sah di Malaysia.\n\nPara 5(1) Trade Descriptions Act (Certification and Marking of Halal) Order 2011: produk import tak boleh dikatakan halal melainkan disahkan badan yang DIIKTIRAF JAKIM. Senarai FHCB terkini (kuat kuasa 21 Ogos 2026) ada 96 badan di 49 negara sahaja.\n\nPara 5(2) pula wajibkan pengimport tandakan nama badan pensijilan pada produk — bukan sekadar logo generik.\n\nSemak status badan pensijilan pembekal anda di myehalal.halal.gov.my sebelum guna dakwaan halal.\n\n#SijilHalal #JAKIM #SMEMalaysia","threads":"Produk import anda ada logo halal negara asal — itu tak automatik sah di Malaysia.\n\nHanya badan pensijilan yang DIIKTIRAF JAKIM yang dikira (Para 5(1), Trade Descriptions Act 2011). Senarai FHCB terkini cuma 96 badan di 49 negara.\n\nPengimport pun wajib tandakan nama badan pensijilan itu pada produk (Para 5(2)) — bukan sekadar logo generik.\n\n#SijilHalal"}}'::jsonb, 'Trade Descriptions Act (Certification and Marking of Halal) Order 2011, Para 5(1) & 5(2); Recognized Foreign Halal Certification Bodies (FHCB) list, JAKIM, berkuat kuasa 21 Ogos 2026M / 8 Rabiulawal 1448H', '[]'::jsonb, '2026-09-13'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa401934ac55a0b10a12567","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa40196cabd46fa08090abc","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa40198a3aa88881a36233f","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:26:00+08'::timestamptz, now(), '2026-09-05T12:41:22.927980Z'::timestamptz) on conflict (id) do nothing;  -- r20260916 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('6259fe1d-a71a-5071-b815-c6b7f2c4e3d4'::uuid, null, 'regulab', 'kosmetik', null, 'bm', 'Notifikasi kosmetik NPRA anda ada tarikh luput. Ramai anggap ia kekal selama-lamanya.', '{"bm":{"instagram":"Notifikasi kosmetik NPRA anda ada tarikh luput. Ramai founder anggap sekali dapat, ia kekal selama-lamanya.\n\nBukan macam itu. Guidelines for Control of Cosmetic Products in Malaysia (Second Edition), Seksyen 2.7, letak tempoh sah notifikasi pada 2 tahun sahaja, dan renewal kena dibuat selewat-lewatnya sebulan sebelum tarikh tamat.\n\nLepas tarikh tu, bukan sekadar proses lambat. Seksyen 2.10 sebut nombor notifikasi sedia ada dikekalkan hanya untuk produk yang diperbaharui sebelum tamat tempoh. Lambat sikit pun, nombor lama hilang, dan produk itu perlu nombor notifikasi baharu, macam permohonan dari kosong.\n\nFee pun bukan cuma sekali. Seksyen 2.6 kenakan RM50 untuk notifikasi baharu, dan RM50 lagi untuk setiap renewal, setiap produk dan varian, dan bayaran yang dah confirm tak akan dikembalikan.\n\nKalau anda urus banyak SKU, jangan tunggu surat peringatan NPRA. Set reminder sendiri dari tarikh notifikasi asal diterima, dan letak sebulan sebelum tarikh tamat sebagai garis merah, bukan tarikh tamat itu sendiri.","facebook":"Notifikasi kosmetik NPRA anda ada tarikh luput. Ramai anggap ia kekal selama-lamanya.\n\nSah untuk 2 tahun sahaja. Renewal kena buat selewat-lewatnya sebulan sebelum tarikh tamat, bukan bila sempat.\n\nLambat sikit pun, nombor notifikasi lama hilang. Anda kena mohon macam produk baharu, bayar fee RM50 semula, dan mula proses dari awal.\n\nSet reminder dari hari notifikasi diterima, bukan bila surat peringatan sampai.","threads":"Notifikasi kosmetik NPRA sah 2 tahun sahaja. Renewal kena buat sebulan sebelum tamat tempoh.\n\nLambat sikit, nombor notifikasi lama hilang terus. Kena mohon macam produk baharu, bayar RM50 semula, mula dari kosong.\n\nSet reminder dari hari notifikasi diterima, bukan tunggu surat peringatan."}}'::jsonb, 'Guidelines for Control of Cosmetic Products in Malaysia (Second Edition), NPRA, Seksyen 2.6 (Fee), 2.7 (Notification Validity Period), 2.9 (Changes in Notification Particulars), 2.10 (Notification Number)', '[]'::jsonb, '2026-09-16'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aaa7c80cd2a1d410d834ab0","at":"16 Sep 2026, 7:24 PM MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aaa0c61dfcd8cd99b832493","at":"16 Sep 2026, 11:26 AM MYT","via":"ws.regulab Studio"},"threads":{"id":"6aaa7c8a3984077c06c272da","at":"16 Sep 2026, 7:24 PM MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-16 21:00:00+08'::timestamptz, now(), '2026-09-14T13:50:00.000Z'::timestamptz) on conflict (id) do nothing;  -- r20260916b (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('ba5cf771-9efa-5c0a-948e-6332e38affcc'::uuid, null, 'regulab', 'halal_my', null, 'bm', 'Sijil halal dari negara pengeluar tak semestinya sijil yang diiktiraf di Malaysia.', '{"bm":{"instagram":"Sijil halal dari negara pengeluar tak semestinya sijil yang diiktiraf di Malaysia.\n\nRamai founder yang import bahan mentah atau produk siap anggap kalau pembekal ada sijil halal dari badan tempatan negara mereka, itu dah cukup untuk letak dakwaan halal di Malaysia. Bukan begitu.\n\nDi bawah Perintah Perihal Dagangan (Pensijilan dan Penandaan Halal) 2011, Perenggan 5(1) dan 5(2) nyatakan dua perkara. Satu, makanan dan barangan import yang dipasarkan di Malaysia tak boleh diperihalkan sebagai halal melainkan ia mematuhi keperluan atau disahkan halal oleh badan pensijilan halal asing yang diiktiraf JAKIM. Dua, pengimport atau pengilang yang produknya disahkan oleh badan itu WAJIB tera nama badan pensijil berkenaan pada produk tersebut.\n\nJAKIM kekalkan senarai rasmi Foreign Halal Certification Bodies (FHCB), berkuat kuasa 21 Ogos 2026: 96 badan pensijilan merentasi 49 negara dan wilayah. Setiap pelantikan sah selama tiga tahun, badan yang dilantik disenaraikan di laman JAKIM, dan mesti hantar laporan tahunan. Kalau tempoh tamat, JAKIM jalankan audit semakan semula sebelum sambung pengiktirafan.\n\nSijil dari badan pensijilan yang tak ada dalam senarai ini tak boleh jadi asas dakwaan halal di Malaysia, tak kira sebaik mana reputasi badan itu di negara asal.\n\nUntuk import daging dan produk berasaskan daging (termasuk ayam), keperluan lagi ketat: kilang mesti diperiksa dan diluluskan bersama oleh JAKIM dan Jabatan Perkhidmatan Veterinar (DVS), ikut Protokol Malaysia untuk Pengeluaran Daging dan Ayam Halal serta MS 1500:2009.\n\nSebelum kunci pembekal atau cetak label, semak nama badan pensijil pembekal anda terhadap senarai JAKIM dulu.\n\n#SijilHalal #JAKIM #MyHalal #SMEMalaysia","facebook":"Sijil halal dari negara pengeluar tak semestinya sijil yang diiktiraf di Malaysia.\n\nDi bawah Perintah Perihal Dagangan (Pensijilan dan Penandaan Halal) 2011, barang import yang dipasarkan di Malaysia tak boleh dilabel halal melainkan ia disahkan oleh badan pensijilan halal asing yang diiktiraf JAKIM. Nama badan itu pun wajib ditera pada produk.\n\nJAKIM kekalkan senarai rasmi 96 badan di 49 negara, berkuat kuasa 21 Ogos 2026. Sijil dari badan di luar senarai ni tak boleh jadi asas dakwaan halal di sini, walau produk tu memang halal dari segi bahan.\n\nKalau anda import bahan mentah atau produk siap, semak nama badan pensijil pembekal anda terhadap senarai JAKIM dulu, bukan lepas kontena sampai.\n\n#SijilHalal #JAKIM #MyHalal","threads":"Sijil halal dari negara pengeluar tak semestinya diiktiraf di Malaysia. Perintah Perihal Dagangan (Pensijilan dan Penandaan Halal) 2011: barang import cuma boleh dilabel halal kalau badan pensijil asingnya ada dalam senarai JAKIM, dan nama badan itu wajib ditera pada produk. Senarai rasmi 21 Ogos 2026 ada 96 badan, 49 negara. Semak dulu sebelum kunci pembekal.\n\n#SijilHalal"}}'::jsonb, 'JAKIM, The Recognized Foreign Halal Certification Bodies & Authorities, berkuat kuasa 21 Ogos 2026M / 8 Rabiulawal 1448H; Perintah Perihal Dagangan (Pensijilan dan Penandaan Halal) 2011, Perenggan 5(1) & 5(2)', '[]'::jsonb, '2026-09-20'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aae719c1e8bdcdb524317a7","at":"2026-09-19 19:27 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aae71b11e8bdcdb524318df","at":"2026-09-19 19:27 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aae71bc1e8bdcdb524319ce","at":"2026-09-19 19:27 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-19 19:27:00+08'::timestamptz, now(), '2026-09-18T13:50:00Z'::timestamptz) on conflict (id) do nothing;  -- r20260920 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('be029c00-b17b-578b-918d-170b698f759e'::uuid, null, 'regulab', 'farmaseutikal', null, 'bm', 'Produk anda dah didaftarkan NPRA — automatik boleh letak logo halal?', '{"bm":{"instagram":"Produk anda dah didaftarkan NPRA — automatik boleh letak logo halal?\n\nTidak. Ramai founder anggap sebaik produk lulus pendaftaran NPRA, letak logo halal pada label tinggal cetak je. DRGD (Seksyen 7.14) kata lain.\n\nLogo halal pada label produk berdaftar adalah SUKARELA — dan ia cuma dibenarkan untuk kategori tertentu: non-scheduled poison (bukan veterinar), health supplement, produk semula jadi, dan kosmetik. Untuk pasaran tempatan mahupun eksport.\n\nSukarela tak bermakna automatik. Untuk letak logo tu, anda kena hantar permohonan variation pendaftaran produk BERASINGAN kepada NPRA, sertakan salinan sijil halal sebagai dokumen sokongan. Ini proses tambahan lepas produk anda dah pun berdaftar, bukan sebahagian daripada permohonan asal.\n\nLogo yang diterima pun terhad — cuma logo dikeluarkan JAKIM atau Badan Islam yang diiktiraf JAKIM.\n\nUntuk produk scheduled poison (ubat kawalan), lain lagi ceritanya. Logo halal boleh dipakai secara sukarela HANYA pada label produk yang dieksport, dengan syarat negara pengimport membenarkan. Pada label yang dijual di pasaran tempatan, logo halal langsung TIDAK dibenarkan untuk kategori ini.\n\nKalau produk anda dalam kategori yang layak dan anda dah ada sijil halal, jangan tunggu — mohon variation itu sekarang, bukan lepas artwork dicetak.\n\nRujukan: Drug Registration Guidance Document (DRGD) Third Edition, 12th Revision, Julai 2026, Seksyen 7.14 Halal Logo.\n\n#SijilHalal #NPRA #KKM #SMEMalaysia #Farmaseutikal","facebook":"Produk anda dah didaftarkan NPRA — automatik boleh letak logo halal?\n\nTidak. Logo halal pada label produk berdaftar (health supplement, produk semula jadi, kosmetik, dan non-scheduled poison bukan veterinar) adalah SUKARELA, bukan automatik. Anda kena hantar permohonan variation berasingan kepada NPRA, sertakan salinan sijil halal JAKIM.\n\nUntuk produk scheduled poison, logo halal cuma dibenarkan pada label EKSPORT, bukan label pasaran tempatan.","threads":"Produk anda dah didaftarkan NPRA — automatik boleh letak logo halal? Tidak.\n\nLogo halal pada label produk berdaftar (supplement, produk semula jadi, kosmetik) adalah SUKARELA. Kena hantar permohonan variation berasingan kepada NPRA + sijil halal JAKIM.\n\nUntuk scheduled poison, logo halal cuma pada label eksport, bukan tempatan."}}'::jsonb, 'Drug Registration Guidance Document (DRGD) Third Edition, 12th Revision, July 2026, Seksyen 7.14 Halal Logo, ms 45-46', '[]'::jsonb, '2026-09-19'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa401a45a67efa86a9b63c2","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa401a5cabd46fa08090c0c","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa401a74ac55a0b10a1274a","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:27:00+08'::timestamptz, now(), '2026-09-07T13:50:25.000Z'::timestamptz) on conflict (id) do nothing;  -- r20260924 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('baaf777c-35bd-5095-8489-a74900e4d766'::uuid, null, 'regulab', 'fatwa', null, 'bm', 'Bukan anjing, bukan babi — automatik boleh guna dalam kosmetik?', '{"bm":{"instagram":"Bukan anjing, bukan babi — automatik boleh guna dalam kosmetik? Tidak semestinya.\n\nRamai anggap peraturan bahan haiwan dalam kosmetik cuma ada dua kategori: anjing/babi (haram terus) dan semua yang lain (selamat). Fatwa Negeri Sembilan Bil. 07/2018 (bersidang 25 Oktober 2018 / 16 Safar 1440H) tunjukkan ia lebih rumit daripada tu.\n\nKeputusan: produk yang dihasilkan daripada anggota atau unsur haiwan yang HALAL dimakan tetapi memudaratkan adalah dilarang. Dan mana-mana produk kosmetik yang mengandungi bahan najis — seperti anggota/unsur haiwan yang haram dimakan selain anjing dan babi, atau yang memudaratkan manusia — adalah HARAM digunakan.\n\nPengecualian yang penting: kulit binatang haram dimakan (selain anjing dan babi) yang telah DISAMAK adalah HARUS digunakan untuk tujuan kosmetik. Proses samak yang ubah status hukum kulit, bukan sumber haiwan itu sendiri.\n\nIni relevan untuk bahan seperti keratin haiwan eksotik, mink oil, snake venom peptide, dan bahan berasaskan kulit/leather. Nota penting: SYN-AKE ialah bahan sintetik, jangan keliru dengan snake venom sebenar — konsep ''disamak'' pula buka ruang untuk bahan berasaskan kulit terproses selain anjing & babi.\n\nYang paling penting untuk formulator: ini FATWA NEGERI (Negeri Sembilan) sahaja, bukan fatwa kebangsaan. Prinsip am dalam hierarki fatwa: Keputusan Muzakarah MKI bukan undang-undang secara automatik. Ia mengikat di sesebuah negeri hanya selepas diwartakan oleh Jawatankuasa Fatwa Negeri. Kalau produk anda dijual merentasi negeri, semak kedudukan setiap negeri secara berasingan sebelum kunci formula.\n\nStatus fatwa pun tak gantikan saringan NPRA — setiap bahan masih kena disemak berasingan terhadap Annex II/III/IV/VI/VII ACD.\n\nAnda akan perlukannya masa isi borang nanti.\n\nRujukan: Muzakarah Jawatankuasa Fatwa Negeri Sembilan Bil. 07/2018, 25 Oktober 2018.\n\n#FatwaMalaysia #HalalMalaysia #KosmetikMalaysia #SMEMalaysia","facebook":"Bukan anjing, bukan babi — automatik boleh guna dalam kosmetik? Tidak semestinya.\n\nFatwa Negeri Sembilan Bil. 07/2018 (25 Okt 2018): bahan haiwan haram dimakan (selain anjing & babi) yang memudaratkan tetap HARAM untuk kosmetik. Kulit yang DISAMAK sahaja yang harus.\n\nIni fatwa peringkat NEGERI (Negeri Sembilan) sahaja, bukan fatwa kebangsaan — semak kedudukan negeri lain dulu sebelum guna untuk pasaran seluruh Malaysia. Prinsip am: Keputusan Muzakarah MKI bukan undang-undang secara automatik. Ia mengikat di sesebuah negeri hanya selepas diwartakan oleh Jawatankuasa Fatwa Negeri.","threads":"Bukan anjing, bukan babi — automatik boleh guna dalam kosmetik? Tidak semestinya.\n\nFatwa Negeri Sembilan Bil. 07/2018: bahan haiwan haram dimakan (selain anjing/babi) yang memudaratkan tetap HARAM. Kulit yang DISAMAK sahaja harus.\n\nFatwa NEGERI sahaja — semak negeri lain dulu."}}'::jsonb, 'Muzakarah Jawatankuasa Fatwa Negeri Sembilan Bil. 07/2018, 25 Oktober 2018 (16 Safar 1440H)', '[]'::jsonb, '2026-09-13'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa517217b5cf11b8b284903","at":"2026-09-12 17:10 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa51723c197f234ad2af7be","at":"2026-09-12 17:11 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa51725d8d9c38b6785dddf","at":"2026-09-12 17:11 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-12 17:11:00+08'::timestamptz, now(), '2026-09-07T13:50:25.000Z'::timestamptz) on conflict (id) do nothing;  -- r20260925 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('43e9989c-d996-5d3c-9cea-63225482ece8'::uuid, null, 'regulab', 'kosmetik', null, 'bm', 'Dua produk kosmetik diharamkan jualan di Brazil bulan lepas. Bukan sebab bahan. Sebab syarikat yang jual tiada kebenaran operasi langsung.', '{"bm":{"instagram":"ANVISA, pihak berkuasa kesihatan Brazil, keluarkan dua notis (RE 3.488/2026 dan RE 3.489/2026) bulan lepas mengharamkan jualan Bunne Po fibra capilar dan Maycheer Hair Rich Shading Powder.\n\nRamai akan sangka ini sebab bahan dalam produk. Bukan. Sebab yang dinyatakan: kedua-dua syarikat yang menjual produk ini tidak mempunyai kebenaran sanitari untuk beroperasi langsung, tak kira apa kandungan produk tu.\n\nIni poin yang SME sering terlepas pandang. Nombor notifikasi atau pendaftaran produk bukan kertas kerja tambahan yang boleh ditunda. Ia kebenaran undang-undang asas untuk anda jual produk itu di pasaran. Syarikat tiada kebenaran beroperasi, produk automatik dilarang jualan, walau formula tu sendiri selamat sekalipun.\n\nSama logiknya di Malaysia. Nombor NOT daripada NPRA bukan bukti produk ''lulus ujian makmal''. Ia bukti syarikat ada kebenaran untuk letak produk itu di pasaran. Tiada nombor tu, walau produk anda bersih, anda dah melanggar undang-undang sejak hari pertama jual.\n\nSebelum ambil stok daripada mana-mana pembekal atau jenama, semak dua benda berasingan: nombor notifikasi atau pendaftaran produk itu sendiri, dan status kebenaran operasi syarikat yang memegangnya.","facebook":"ANVISA (pihak berkuasa kesihatan Brazil) haramkan jualan dua produk kosmetik bulan lepas, Bunne Po fibra capilar dan Maycheer Hair Rich Shading Powder.\n\nBukan sebab bahan dalam produk. Sebab kedua-dua syarikat yang jual produk ini tiada kebenaran sanitari untuk beroperasi langsung.\n\nUntuk SME: nombor notifikasi atau pendaftaran bukan kertas kerja tambahan, ia kebenaran undang-undang asas untuk jual produk di pasaran. Tiada kebenaran itu, produk dilarang jualan walau formula selamat sekalipun.","threads":"ANVISA Brazil haramkan jualan dua produk kosmetik bulan lepas, bukan sebab bahan, sebab syarikat yang jual tiada kebenaran sanitari untuk beroperasi.\n\nNombor notifikasi bukan kertas kerja, ia kebenaran undang-undang untuk berniaga. Sama di Malaysia: nombor NOT NPRA bukan bukti produk selamat, ia bukti anda ada hak jual."}}'::jsonb, 'ANVISA (Agencia Nacional de Vigilancia Sanitaria, Brazil), RE 3.488/2026 dan RE 3.489/2026, Diario Oficial da Uniao, disiarkan 8 Sept 2026', '[]'::jsonb, '2026-09-25'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab5a41abb8376313827fda9","at":"2026-09-25 06:29 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab5a429bb8376313827fe75","at":"2026-09-25 06:29 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab5a434355ed92ff3e72c4d","at":"2026-09-25 06:29 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-25 06:29:00+08'::timestamptz, now(), '2026-09-23T13:48:41.000Z'::timestamptz) on conflict (id) do nothing;  -- r20260925c (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('b22d95a1-b78c-571a-9f7c-31a7ddb4854b'::uuid, null, 'regulab', 'kajian_kes', null, 'bm', '"Sunscreen naikkan risiko kanser kulit 292%" — bukan apa yang kajian itu jumpa.', '{"bm":{"instagram":"\"Sunscreen naikkan risiko kanser kulit 292%\" — bukan apa kajian itu jumpa.\n\nAngka ni petik daripada kajian UK Biobank (Jeremian et al., 2023), sebenarnya kajian gen pembaikan DNA, bukan kajian sunscreen. Sunscreen cuma satu pembolehubah dalam data tu.\n\n292% tu nisbah unadjusted. Orang kulit cerah, sensitif matahari, ada sejarah lesion memang lebih kerap pakai sunscreen DAN lebih kerap kena kanser kulit. Confounding by indication, bukan sebab-akibat. Kajian tu pun tak selaraskan cumulative UV exposure, punca sebenar risiko.\n\nYang lebih penting: satu-satunya RCT yang betul-betul tugaskan orang pakai sunscreen harian (Green et al., Nambour trial, Australia, 4,000+ orang, 2011) dapati melanoma turun separuh.\n\nBila headline viral petik satu angka dari kajian observational, tanya dulu: kajian ni betul-betul uji sunscreen, atau sunscreen cuma pembolehubah dalam data lain?\n\nPakai sunscreen anda.\n\nRujukan: Jeremian et al., Cancer Epidemiol Biomarkers Prev 2023;32(11):1599-1607; Green et al., J Clin Oncol 2011.\n\n#Kosmetik #Sunscreen #NPRA","facebook":"\"Sunscreen naikkan risiko kanser kulit 292%\" — bukan apa kajian itu jumpa.\n\nKulit cerah dan sensitif matahari pakai lebih sunscreen DAN lebih kerap kena kanser kulit. Kajian UK Biobank tu tak asingkan dua sebab ni. Macam kata payung punca hujan.\n\nSatu-satunya kajian jangka panjang yang betul-betul uji sunscreen harian (Nambour, Australia, 4,000+ orang) dapati melanoma turun separuh.\n\nPakai sunscreen anda.","threads":"\"Sunscreen naikkan risiko kanser kulit 292%\" — bukan apa kajian itu jumpa.\n\nKulit cerah & sensitif matahari pakai lebih sunscreen DAN lebih kerap kanser kulit. Confounding, bukan sebab-akibat.\n\nRCT sebenar (Australia, 4,000+ orang): melanoma turun separuh dengan sunscreen harian.\n\nPakai sunscreen anda."}}'::jsonb, 'Jeremian et al., Cancer Epidemiol Biomarkers Prev 2023;32(11):1599-1607; Green et al., Nambour trial, J Clin Oncol 2011', '[]'::jsonb, '2026-09-12'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa4c65c18f0927c8d633179","at":"12 Sep 2026, 11:30 AM MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa4c66718f0927c8d63323b","at":"12 Sep 2026, 11:30 AM MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa4c6d7aa296f331c822732","at":"12 Sep 2026, 11:30 AM MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-12 13:00:00+08'::timestamptz, now(), '2026-09-07T13:50:25.000Z'::timestamptz) on conflict (id) do nothing;  -- r20260926 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('630f4725-a37a-5a99-ada9-7a1e9b81605d'::uuid, null, 'regulab', 'kajian_kes', null, 'bm', 'Pencuci muka harian anda tak menyebabkan kanser.', '{"bm":{"instagram":"Pencuci muka harian anda tak menyebabkan kanser.\n\nKhabar angin ni datang dari laporan 2024 pasal produk jerawat yang ada benzoyl peroxide (BPO) -- bila disimpan dalam keadaan panas, BPO boleh terurai jadi benzena. Klip viral generalize laporan tu kepada SEMUA produk penjagaan kulit, termasuk yang langsung tiada BPO.\n\nBenzena memang dilarang sebagai ramuan sengaja ditambah di bawah Annex II EC 1223/2009 dan ACD. Tapi kehadiran surih (trace) sebagai hasil penguraian yang \"tak dapat dielak secara teknikal\" dinilai di bawah Artikel 17 / amalan pengilangan baik -- bukan larangan mutlak automatik pada setiap produk yang ada kaitan.\n\nIsu ni relevan HANYA untuk SKU yang memang ada benzoyl peroxide, dan hanya bila disimpan pada suhu tinggi -- dalam kereta, bawah cahaya matahari terus. Pencuci muka atau moisturizer biasa yang tiada BPO langsung tak terlibat.\n\nKalau jenama anda ada produk BPO: minta data ujian benzena end-of-shelf-life dan accelerated-storage daripada pembekal untuk PIF anda. Nyatakan syarat penyimpanan yang betul pada label.\n\nRujukan: EC 1223/2009 Annex II; ACD Annex II; laporan Valisure 2024 tentang penguraian BPO-benzena.\n\n#Kosmetik #NPRA #SMEMalaysia #KosmetikMalaysia","facebook":"Pencuci muka harian anda tak menyebabkan kanser.\n\nKhabar angin ni datang dari laporan 2024 pasal produk jerawat mengandungi benzoyl peroxide (BPO) yang boleh terurai jadi benzena bila disimpan panas. Kebanyakan pencuci muka harian langsung tiada BPO.\n\nKalau anda ada produk BPO dalam portfolio: nyatakan syarat penyimpanan yang betul pada label, dan minta data ujian benzena daripada pembekal untuk PIF.\n\nRujukan: EC 1223/2009 Annex II; laporan Valisure 2024.\n\n#Kosmetik #NPRA #SMEMalaysia","threads":"Pencuci muka harian anda tak menyebabkan kanser.\n\nKhabar angin ni dari laporan 2024 pasal benzoyl peroxide (BPO) yang boleh terurai jadi benzena bila disimpan panas. Kebanyakan pencuci muka harian pun tiada BPO langsung.\n\nKalau ada produk BPO -- jangan tinggal dalam kereta, jauhkan dari cahaya matahari terus.\n\n#Kosmetik"}}'::jsonb, 'EC 1223/2009 Annex II (benzena, bahan dilarang); ACD Annex II; laporan Valisure 2024 tentang penguraian benzoyl peroxide kepada benzena', '[]'::jsonb, '2026-09-12'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa4017c5a67efa86a9b605f","at":"2026-09-12 17:11 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa4017ecabd46fa08090856","at":"2026-09-12 17:11 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa40180a3aa88881a36202c","at":"2026-09-12 17:11 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-12 17:11:00+08'::timestamptz, now(), '2026-09-08T14:05:00.000Z'::timestamptz) on conflict (id) do nothing;  -- r20261003 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('ca02b55b-54ae-5bb4-8dd1-81506064bc8e'::uuid, null, 'regulab', 'makanan', null, 'bm', '''Rendah Gula'' pada label anda -- berapa gram sebenarnya?', '{"bm":{"instagram":"''Rendah Gula'' pada label anda -- berapa gram sebenarnya?\n\nJadual Kelima A Peraturan-Peraturan Makanan 1985 tetapkan angka tepat untuk setiap akuan pemakanan (nutrition claim). Bukan anggaran, bukan ''lebih kurang'' -- nombor tepat, ikut jenis produk (pepejal atau cecair).\n\nGula:\nRendah -- tak lebih 5g/100g (pepejal) atau 2.5g/100ml (cecair)\nBebas -- tak lebih 0.5g/100g atau 0.5g/100ml\n\nNatrium:\nRendah -- tak lebih 0.12g/100g atau 0.06g/100ml\nSangat Rendah -- tak lebih 0.04g/100g atau 0.02g/100ml\nBebas -- tak lebih 0.005g/100g atau 0.005g/100ml\n\nLemak:\nRendah -- tak lebih 3g/100g atau 1.5g/100ml\nBebas -- tak lebih 0.15g/100g atau 0.15g/100ml\n\nYang selalu jadi silap: produk dengan 6g gula/100g letak ''Rendah Gula'' sebab rasa dia memang kurang manis berbanding produk lain dalam kategori sama. Itu bukan asas yang sah. Angka jadual ini yang tentukan, bukan perbandingan pasaran atau rasa lidah.\n\nSebelum cetak sebarang akuan ''Rendah'', ''Bebas'' atau ''Sangat Rendah'' pada artwork, semak keputusan makmal produk anda terhadap angka jadual ini dulu.\n\nRujukan: Peraturan-Peraturan Makanan 1985, Jadual Kelima A (Peraturan 18c, 18D, 18E, 18F dan 26).\n\n#PelabelanMakanan #FSQD #BKKM #SMEMalaysia","facebook":"''Rendah Gula'' pada label anda -- berapa gram sebenarnya?\n\nJadual Kelima A Peraturan-Peraturan Makanan 1985 tetapkan angka tepat untuk akuan macam ''Rendah'', ''Bebas'' dan ''Sangat Rendah''. Contoh gula: Rendah tak lebih 5g/100g (pepejal) atau 2.5g/100ml (cecair); Bebas tak lebih 0.5g.\n\nProduk kurang manis berbanding pesaing bukan asas untuk letak ''Rendah Gula'' -- angka jadual ini yang tentukan.\n\nSemak makmal dulu sebelum cetak artwork.\n\nRujukan: Peraturan-Peraturan Makanan 1985, Jadual Kelima A.\n\n#PelabelanMakanan #FSQD #SMEMalaysia","threads":"''Rendah Gula'' pada label anda -- berapa gram sebenarnya?\n\nJadual Kelima A tetapkan angka tepat: Rendah tak lebih 5g/100g, Bebas tak lebih 0.5g. Rasa kurang manis berbanding pesaing bukan asas yang sah.\n\nSemak makmal dulu sebelum cetak.\n\n#PelabelanMakanan"}}'::jsonb, 'Peraturan-Peraturan Makanan 1985 (BM), kemas kini November 2024/31 Disember 2023 -- Jadual Kelima A (Peraturan 18c, 18D, 18E, 18F dan 26), Daftar I', '[]'::jsonb, '2026-09-20'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aac69107ef8244029317926","at":"2026-09-18 06:28 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aac69247ef8244029317a92","at":"2026-09-18 06:28 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aac6930825615b9030bfa01","at":"2026-09-18 06:28 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-18 06:28:00+08'::timestamptz, now(), '2026-09-08T14:20:00.000Z'::timestamptz) on conflict (id) do nothing;  -- r20261006 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('2d4160a4-c78f-5a5e-a60f-06e621e376ec'::uuid, '96eb985f-1a2c-5803-8b18-0f108bbac785'::uuid, 'regulab', 'farmaseutikal', null, 'bm', 'Letak B6 sebagai ''bonus'' dalam multivitamin anda tak buat ia terlepas daripada keperluan label amaran.', '{"bm":{"instagram":"Ini salah faham yang kerap muncul bila semak label suplemen: ramai formulator anggap kalau Vitamin B6 bukan ''bahan utama'' produk, ia tak perlu ikut keperluan label amaran. Contohnya B6 yang diselitkan dalam multivitamin, magnesium atau zink sekadar sebagai ''bonus'' pada label depan.\n\nItu bukan macam mana regulator nilai risiko. Yang jadi penentu ialah kepekatan bahan dalam formulasi anda, bukan sama ada B6 itu star ingredient atau sekadar tambahan.\n\nArahan di bawah Peraturan 29 Peraturan-Peraturan Kawalan Dadah dan Kosmetik 1984, Bilangan 15 Tahun 2026, mewajibkan pernyataan amaran risiko peripheral neuropathy bagi produk suplemen kesihatan (HS) dan produk bukan racun berjadual (OTC) yang mengandungi Vitamin B6 melebihi 10 mg. Ia datang daripada keputusan PBKD mesyuarat ke-421 pada 8 Jun 2026, dan tarikh kuat kuasanya serta-merta.\n\nDua perkara yang selalu terlepas pandang. Pertama, skopnya bukan label sahaja: semua label, sisip bungkusan dan Risalah Maklumat Ubat untuk Pengguna (RiMUP) kena dikemas kini. Kedua, teks amaran diberi perkataan demi perkataan, jadi ia bukan sesuatu yang boleh anda parafrasa ikut gaya jenama:\n\n\"Warning: This product contains Vitamin B6. Stop taking this product if you experience tingling, burning or numbness and see your doctor as soon as possible.\"\n\nTarikhnya pula berbeza ikut status produk. Permohonan baharu dan produk yang sedang dalam proses penilaian pendaftaran: serta-merta. Produk berdaftar: permohonan pindaan maklumat produk perlu dikemukakan melalui permohonan variasi sebelum 1 Disember 2026.\n\nKalau syarikat anda ada produk dengan B6 dalam senarai bahan, walaupun bukan headline produk, semak kandungan per dos sekarang dan kira sama ada ia melebihi 10 mg.","facebook":"Ramai anggap Vitamin B6 yang diletak sebagai ''bonus'' dalam multivitamin, magnesium atau zink tak perlu label amaran khas. Itu salah. Yang tentukan ialah kepekatan bahan, bukan peranan pemasarannya.\n\nArahan di bawah Peraturan 29 PKDK 1984, Bilangan 15 Tahun 2026, mewajibkan pernyataan amaran risiko peripheral neuropathy bagi produk suplemen kesihatan (HS) dan produk bukan racun berjadual (OTC) yang mengandungi Vitamin B6 melebihi 10 mg. Ia keputusan PBKD mesyuarat ke-421 pada 8 Jun 2026, kuat kuasa serta-merta.\n\nPerhatikan skopnya: bukan label sahaja. Sisip bungkusan dan RiMUP pun kena dikemas kini. Teks amaran diberi perkataan demi perkataan: \"Warning: This product contains Vitamin B6. Stop taking this product if you experience tingling, burning or numbness and see your doctor as soon as possible.\"\n\nPermohonan baharu dan produk yang sedang dalam penilaian: serta-merta. Produk berdaftar: permohonan variasi perlu dikemukakan sebelum 1 Disember 2026.","threads":"Salah faham biasa: B6 sebagai ''bonus'' dalam multivitamin tak perlu label amaran. Salah. Arahan Peraturan 29 PKDK 1984 Bilangan 15 Tahun 2026 wajibkan amaran peripheral neuropathy untuk HS dan OTC yang mengandungi B6 melebihi 10 mg, ikut kepekatan bukan peranan pemasaran. Label, sisip bungkusan dan RiMUP. Produk berdaftar: variasi sebelum 1 Disember 2026."}}'::jsonb, 'Arahan di bawah Peraturan 29, Peraturan-Peraturan Kawalan Dadah dan Kosmetik 1984, Bilangan 15 Tahun 2026 (NPRA.600-1/9/13 (9) Jld.2) — penambahan pernyataan amaran bagi produk HS dan OTC mengandungi Vitamin B6 melebihi 10 mg berkaitan risiko peripheral neuropathy; perenggan 2.1, 2.2.1, 2.2.2 dan 3.1; keputusan PBKD mesyuarat ke-421, 8 Jun 2026; kuat kuasa serta-merta.', '[]'::jsonb, '2026-09-11'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa401885a67efa86a9b614f","at":"2026-09-11 21:26 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa4019632d420cab6f53a28","at":"2026-09-11 21:27 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa401c7a3aa88881a3629a4","at":"2026-09-11 21:28 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-11 21:28:00+08'::timestamptz, now(), '2026-09-08T12:36:27.883Z'::timestamptz) on conflict (id) do nothing;  -- r7h3umljs6 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('2d80cc5c-5b4e-5a46-889c-ce5a66951835'::uuid, '0f76e125-6ed7-5715-9830-8a1f579537ed'::uuid, 'linkedin', null, 'G', 'en', 'Your shampoo cannot fix an autoimmune disease, no matter what the bottle says.', '{"en":{"linkedin":"Three kinds of hair loss get lumped into one marketing category, and that is where the trouble starts.\n\nAlopecia areata happens when the immune system''s T-cells mistakenly attack the hair follicle, treating it as a threat. That is why it often shows up as sudden, coin-sized bald patches rather than gradual thinning.\n\nAndrogenetic alopecia works differently. It is driven by DHT sensitivity at the follicle, causing progressive miniaturisation over years, mostly at the crown or hairline.\n\nTelogen effluvium is different again: a stressor, illness or hormonal shift pushes too many follicles into the resting phase at once, causing diffuse shedding that usually recovers on its own.\n\nThree mechanisms, three prognoses, three treatment pathways. A viewpoint paper in JMIR Dermatology (21 Sept 2026) looked at alopecia areata management from a Malaysian angle and flagged limited access to newer therapies, high treatment cost, and public confusion over its autoimmune nature as real unmet needs.\n\nA cosmetic product marketed generically for ''rambut gugur'' cannot diagnose which of the three a customer has. Claiming it treats hair loss without that distinction is a claims problem, not just a marketing shortcut.\n\nSources: Mohd Affandi A, Jamil A, Azizan NZ, et al. Current Management and Unmet Needs in Alopecia Areata: Viewpoint From a Malaysian Perspective. JMIR Dermatol. 2026;9:e89583. doi:10.2196/89583.\n\n#AlopeciaAreata #Dermatology #CosmeticClaims #RegulatoryAffairs #ASEANCosmetics"}}'::jsonb, 'Mohd Affandi A, Jamil A, Azizan NZ, et al. Current Management and Unmet Needs in Alopecia Areata: Viewpoint From a Malaysian Perspective. JMIR Dermatol. 2026;9:e89583. doi:10.2196/89583', '[]'::jsonb, '2026-09-23'::date, '19:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7508848960564916224","at":"2026-09-24 19:25 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7508848960564916224/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-24 19:25:00+08'::timestamptz, now(), '2026-09-23T06:31:43.047Z'::timestamptz) on conflict (id) do nothing;  -- r9l3kt69bq (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('cd70d971-80bf-552b-819d-90935550c119'::uuid, 'abce6ea6-0c93-5c0b-9739-f1e5f1285618'::uuid, 'regulab', 'makanan', null, 'bm', 'Ramai usahawan madu, minyak masak, sos, kopi dan rempah fikir sebab produk dibeli pukal daripada pembekal dan cuma dibotol atau dibungkus semula di bawah jenama sendiri, kewajipan label kekal pada pembekal asal. Anggapan ini salah.', '{"bm":{"instagram":"Ramai usahawan madu, minyak masak, sos, kopi dan rempah fikir sebab produk dibeli pukal daripada pembekal dan cuma dibotol atau dibungkus semula di bawah jenama sendiri, kewajipan label kekal pada pembekal asal. Anggapan ini salah.\n\nSebaik anda tampal label sendiri pada bekas, andalah pihak yang menanggung ketepatan nama sebenar produk, senarai ramuan, berat bersih, dan identiti pengilang atau pembungkus yang tertera pada label itu. ''Repack sahaja'' bukan status istimewa dalam undang-undang pelabelan makanan.\n\nKes penguatkuasaan terkini terhadap aktiviti membotol semula minyak masak pukal untuk dijual di bawah perihal produk yang berlainan tunjukkan ini bukan teori. Siasatan melibatkan label tidak berdaftar, dirujuk di bawah Akta Kawalan Bekalan 1961 dan Akta Perihal Dagangan 2011.\n\nKalau jenama anda ada pada botol itu, tanggungjawab ikut anda, bukan pembekal pukal.","facebook":"Ramai usahawan fikir sebab produk dibeli pukal dan cuma dibotol semula di bawah jenama sendiri, kewajipan label kekal pada pembekal asal. Salah.\n\nBila anda letak label sendiri pada bekas, andalah yang tanggung ketepatan nama produk, senarai ramuan, berat bersih dan identiti pengilang atau pembungkus. Kes terkini membotol semula minyak masak pukal untuk dijual di bawah perihal berlainan disiasat kerana label tidak berdaftar, di bawah Akta Kawalan Bekalan 1961 dan Akta Perihal Dagangan 2011.\n\n''Repack sahaja'' bukan pengecualian.","threads":"\"Kami repack je\" bukan pengecualian dari kewajipan label. Bila anda tampal label sendiri, andalah yang tanggung ketepatan nama produk, ramuan, berat bersih dan identiti pengilang. Kes minyak masak pukal yang dibotol semula dan dijual di bawah perihal lain baru disiasat atas isu label tidak berdaftar."}}'::jsonb, '', '[]'::jsonb, '2026-09-10'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa25845326c822afe174e50","at":"2026-09-10 15:12 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa258612b7efff1008d2e0c","at":"2026-09-10 15:13 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa258cccae36b8846957f23","at":"2026-09-10 15:14 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-10 15:14:00+08'::timestamptz, now(), '2026-09-09T11:48:10.288Z'::timestamptz) on conflict (id) do nothing;  -- rg0lx7banr (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('aae1bbd2-ade0-5257-9ad8-e2d8361c49a7'::uuid, null, 'regulab', 'farmaseutikal', null, 'bm', 'Ramai fikir bila dah dapat nombor MAL, habis cerita. Sebenarnya itu baru permulaan.', '{"bm":{"instagram":"Ini salah faham yang saya jumpa hampir setiap kali jumpa founder baru daftar produk. Nombor MAL keluar, semua orang lega, anggap kerja regulatory dah selesai.\n\nTapi NPRA ada program namanya Post-market Product Quality Monitoring, PQM. Selepas produk anda dalam pasaran, NPRA boleh sampling produk dari rak, hantar untuk laboratory testing, semak label anda masih ikut apa yang diluluskan atau tidak.\n\nKalau testing jumpa isu, contohnya kandungan tak konsisten dengan apa yang didaftarkan, atau ada tanda adulteration, ini bukan setakat surat amaran. Boleh naik ke risk communication, regulatory action, sampai ke recall batch tertentu.\n\nJadi bila saya cakap dengan client, saya selalu tanya satu soalan: batch anda sekarang, kandungan dia sama macam sample yang anda hantar untuk pendaftaran dulu tak? Ramai tak boleh jawab dengan yakin sebab dari masa pendaftaran ke pengeluaran sebenar, ada je perubahan supplier bahan mentah, perubahan proses.\n\nMAL number bukan sijil ''anda dah selamat''. Dia lebih macam lesen memandu, boleh ditarik balik kalau anda melanggar syarat.","facebook":"Ramai founder anggap bila dah dapat nombor MAL, kerja regulatory habis. Sebenarnya NPRA ada program PQM, Post-market Product Quality Monitoring, yang boleh sampling produk dari pasaran bila-bila masa, hantar untuk lab testing, semak label anda masih patuh atau tidak.\n\nKalau ada isu kualiti atau tanda adulteration, ini boleh naik jadi regulatory action sampai recall. Nombor MAL bukan sijil selamat selamanya, ia lebih macam lesen yang boleh ditarik balik kalau syarat tak dipatuhi.","threads":"Nombor MAL keluar tak bermakna habis cerita. NPRA ada program PQM, boleh sampling produk anda dari rak bila-bila masa, hantar lab testing. Jumpa isu kualiti atau adulteration, boleh terus ke recall. Ia lesen, bukan sijil selamat."}}'::jsonb, 'DRGD 3rd Ed, 12th Rev, July 2026, Seksyen 21.2', '[]'::jsonb, '2026-09-18'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa94e9937b10925a7f84b70","at":"2026-09-15 21:56 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa94e9b303704b130edb836","at":"2026-09-15 21:56 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa94e9e37b10925a7f84c16","at":"2026-09-15 21:56 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-15 21:56:00+08'::timestamptz, now(), '2026-09-09T17:12:12.025Z'::timestamptz) on conflict (id) do nothing;  -- s3caz5w0e1 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('19261dc1-617d-5211-80a2-4dcebaa17714'::uuid, 'e819d4cd-790d-5b95-ad1b-1c3e78fae1ab'::uuid, 'linkedin', null, 'D', 'en', 'A fragrance house''s own cologne just got pulled under a rule that has been in force since 2022.', '{"en":{"linkedin":"A fragrance house''s own cologne just got pulled under a rule that has been in force since 2022.\n\nEU Safety Gate flagged a product for containing 2-(4-tert-butylbenzyl)propionaldehyde, BMHCA, better known in the trade as Lilial. The authority ordered the stock destroyed.\n\nLilial is not a new prohibition. It has sat in Annex II of the EU Cosmetics Regulation, the prohibited-substance list. What this alert actually shows is not a new rule, it is post-market surveillance catching old stock: a batch formulated or packed before the ban, still moving through distribution years after the cut-off.\n\nThat gap is the real exposure. A formula reformulated on time does not protect a brand if warehouse stock, an old production run, or a parallel-imported batch from a market with looser enforcement is still on a shelf somewhere. Annex II bans a substance for placing on the market, not merely for manufacture, so the clock that matters is when the product leaves the shelf, not when the formula changed.\n\nIf your compliance check stops at ''we reformulated'', it has not checked the part that actually gets flagged.\n\nSources: EU Cosmetics Regulation (EC) No 1223/2009, Annex II\n\n#CosmeticRegulation #EUCosmeticsRegulation #Lilial #RegulatoryAffairs #ProductSafety"}}'::jsonb, 'EU Cosmetics Regulation (EC) No 1223/2009, Annex II EU Safety Gate alert', '[]'::jsonb, '2026-09-18'::date, '06:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7506557148462469120","at":"2026-09-18 11:38 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7506557148462469120/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-18 11:38:00+08'::timestamptz, now(), '2026-09-17T15:35:00.000Z'::timestamptz) on conflict (id) do nothing;  -- s4m6dnbmhca (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('30f2aecc-b10b-539b-bf39-a8285e9b035d'::uuid, 'c76fa047-8efd-5a04-b06a-57eb4793e91b'::uuid, 'regulab', 'makanan', null, 'bm', 'Video tular minggu ni dakwa air botol SeaMaster datang dari sumber kumbahan. JAKIM dah jawab: sijil Pengesahan Halal Malaysia produk itu sah. Tapi ramai stop kat situ, macam sijil halal tu dah cukup jawab semua tuduhan.', '{"bm":{"instagram":"Video tular minggu ni dakwa air botol SeaMaster datang dari sumber kumbahan. JAKIM dah jawab: sijil Pengesahan Halal Malaysia produk itu sah. Tapi ramai stop kat situ, macam sijil halal tu dah cukup jawab semua tuduhan.\n\nIa tak cukup.\n\nSijil halal jawab soalan bahan dan proses: apa yang masuk, macam mana ia diproses, ada kontaminasi silang ke tak. Soalan ''air ni dari mana'' itu soalan lain, dan dijawab oleh dokumen lain: lesen punca air daripada Kementerian Kesihatan Malaysia.\n\nSemua Air Mineral Semulajadi (AMS) dan Air Minuman Berbungkus (AMB) yang dijual di Malaysia wajib patuh Peraturan 360A (AMS) atau 360B (AMB) di bawah Peraturan-Peraturan Makanan 1985. Dua peraturan berasingan ikut jenis air, dan dua-dua perlukan lesen punca air disahkan sebelum produk boleh naik rak.\n\nKalau anda usahawan air botol atau air isi semula, jangan berhenti di sijil halal je. Semak juga lesen punca air anda. Ia dokumen yang jawab tuduhan yang sijil halal langsung tak sentuh.","facebook":"Dakwaan air botol SeaMaster dari sumber kumbahan dah dijawab JAKIM, sijil halal produk itu sah Tapi sijil halal bukan dokumen yang jawab soalan sumber air.\n\nUntuk air botol (AMS atau AMB), soalan sumber air dijawab oleh lesen punca air daripada KKM, di bawah Peraturan 360A atau 360B, Peraturan-Peraturan Makanan 1985. Dua dokumen, dua soalan berbeza. Kalau anda dalam bisnes air botol, pastikan dua-dua ada, bukan satu je.","threads":"Sijil halal jawab soalan bahan. Lesen punca air (KKM, Peraturan 360A/360B) jawab soalan dari mana air tu datang. Air botol perlukan dua-dua dokumen ni, bukan satu je yang boleh jawab semua tuduhan."}}'::jsonb, 'Peraturan-Peraturan Makanan 1985, Peraturan 360A (AMS) dan 360B (AMB); pengesahan JAKIM ke atas sijil halal produk berkenaan', '[]'::jsonb, '2026-09-24'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab30147340f92dcbe1771f0","at":"2026-09-23T06:29 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab301532aa0e20bb46a3739","at":"2026-09-23T06:29 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab3015b98ae6feaa61c0706","at":"2026-09-23T06:29 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-23 06:29:00+08'::timestamptz, now(), '2026-09-20T09:32:03.131Z'::timestamptz) on conflict (id) do nothing;  -- tbr99mam5i (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('b0ae847b-605c-5b03-9067-4d7eb5a66aef'::uuid, '45cf021e-b0e1-521f-9209-7bd9ec5bdd4c'::uuid, 'linkedin', null, 'A', 'en', '"Voluntary digital labelling" is doing a lot of misleading work in group chats this week.', '{"en":{"linkedin":"\"Voluntary digital labelling\" is doing a lot of misleading work in group chats this week.\n\nPeople are reading it as Thailand replacing the printed label with a digital one. It is not. A voluntary scheme, by definition, sits on top of the mandatory physical label, it does not substitute it. Ingredient list, batch number, manufacturer details and warning statements still have to be on pack. What changes is optional: a QR code or digital layer that can carry extra information, not a shortcut for information that is already required.\n\nThis matters for anyone exporting into Thailand from Malaysia or elsewhere in ASEAN. If a label strategy assumes physical particulars can shrink because a digital option exists, that assumption fails at customs or at market surveillance, not at the comment stage.\n\nThe exact instrument, the scope of what can actually move to digital, and the comment deadline are not confirmed here.\n\n#CosmeticsRegulation #RegulatoryAffairs #ASEAN #Thailand #CosmeticLabelling"}}'::jsonb, '', '[]'::jsonb, '2026-09-15'::date, '08:30', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7506360498288967681","at":"2026-09-17 22:36 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7506360498288967681/","via":"ws.regulab Studio"}}'::jsonb, '2026-09-17 22:36:00+08'::timestamptz, now(), '2026-09-08T12:37:20.241Z'::timestamptz) on conflict (id) do nothing;  -- tz9m2jmo2d (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('afe5f985-f816-57aa-a547-6949dfda3657'::uuid, null, 'regulab', 'halal_my', null, 'bm', '"Boleh hantar dulu, SOP siapkan lepas tu?" Soalan ni saya dengar hampir setiap minggu.', '{"bm":{"instagram":"\"Boleh hantar dulu, SOP siapkan lepas tu?\" Soalan ni saya dengar hampir setiap minggu.\n\nJawapan pendek: tak boleh. JAKIM audit apa yang sedang berjalan di premis anda, bukan apa yang anda janji nak perbaiki.\n\nTapi ada satu perkara yang ramai salah faham, termasuk yang bagi nasihat. Sistem Jaminan Halal (HAS) itu keperluan untuk syarikat kategori besar dan sederhana, di bawah Prosedur 20 Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020.\n\nKalau syarikat anda kategori kecil atau mikro, yang dikehendaki ialah Sistem Kawalan Halal Dalaman (IHCS) di bawah Prosedur 19: polisi halal yang difahami semua pihak, prosedur kawalan bahan mentah dan pembekal, dan prosedur kebolehkesanan. Bukan manual HAS penuh.\n\nJadi bina yang betul untuk kategori anda, dan pastikan ia benar-benar berjalan sebelum submit di MYeHALAL.\n\nDan tentang reject: manual itu tidak menetapkan apa-apa tempoh menunggu sebelum boleh mohon semula. Yang ditetapkan ialah anda kena kemukakan permohonan baharu. Kosnya fi baharu dan audit baharu, bukan tempoh larangan.","facebook":"\"Boleh hantar dulu, SOP siapkan lepas?\" Tak boleh. JAKIM audit apa yang sedang berjalan, bukan apa yang anda janji.\n\nYang ramai salah faham: Sistem Jaminan Halal (HAS) itu keperluan kategori besar dan sederhana, Prosedur 20 Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020. Kategori kecil dan mikro bina Sistem Kawalan Halal Dalaman (IHCS) di bawah Prosedur 19: polisi halal, prosedur kawalan bahan mentah dan pembekal, prosedur kebolehkesanan.\n\nBina yang betul untuk kategori anda, dan pastikan ia berjalan sebelum submit di MYeHALAL.\n\nKena reject pun tiada tempoh menunggu dalam manual itu. Yang ada, permohonan baharu: fi baharu, audit baharu.","threads":"\"Hantar dulu, SOP lepas?\" Tak boleh. JAKIM audit apa yang berjalan sekarang.\n\nRamai salah faham: HAS itu untuk kategori besar dan sederhana (Prosedur 20). Kecil dan mikro bina IHCS (Prosedur 19) — polisi halal, kawalan bahan mentah, kebolehkesanan.\n\nReject pula tiada tempoh menunggu. Cuma permohonan baharu: fi baharu, audit baharu."}}'::jsonb, 'JAKIM, Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020: Prosedur 19, 20 dan 21', '[]'::jsonb, '2026-09-18'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa94efa21047f953f8e061e","at":"2026-09-15 21:58 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa94efcf5d240e2d1391b2c","at":"2026-09-15 21:58 MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa94eff37b10925a7f858ae","at":"2026-09-15 21:58 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-15 21:58:00+08'::timestamptz, now(), '2026-09-07T13:57:59.537Z'::timestamptz) on conflict (id) do nothing;  -- vlts9k2jxt (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('70dea6a7-dd6b-59cb-8b9d-b6b81684c335'::uuid, 'c1f9312b-5d07-5022-be51-bd0e5a39effe'::uuid, 'linkedin', null, 'F', 'en', 'Most brand owners assume a clean INCI list means no PFAS in the product. That is not how PFAS actually gets in.', '{"en":{"linkedin":"Most brand owners assume a clean INCI list means no PFAS in the product. That is not how PFAS actually gets in.\n\nPFAS can enter as a processing aid, as an impurity carried over from a raw material supplier, or through cross contamination on shared manufacturing lines. None of those routes show up on a formula sheet because they were never intentionally added ingredients in the first place.\n\nAn INCI list only tells you what was formulated in. It cannot tell you what turns up when the finished product is actually tested, using targeted methods like LC-MS/MS for specific PFAS compounds or total organic fluorine screening for the ones you did not think to look for.\n\nFor formulators putting out a \"PFAS-free\" or \"clean beauty\" claim, checking the ingredient list is the easy part. The claim has to be backed by finished-product test data, not a paper review of what went into the formula.\n\nRestricted PFAS entries such as PFOA and PFOS already sit in Annex II of Regulation (EC) 1223/2009. Absence from that annex on paper does not guarantee absence in the bottle.\n\nSources: Regulation (EC) 1223/2009, Annex II. Vincent-Graindorge M, Ripoll L. “Declared versus actual presence of PFAS in cosmetic products: an INCI list analysis and critical appraisal of current regulatory frameworks.” Environ Sci Pollut Res Int, 15 Sept 2026. DOI 10.1007/s11356-026-38214-9\n\n#PFAS #CosmeticRegulatory #CleanBeauty #RegulatoryAffairs #Cosmetics"}}'::jsonb, 'Vincent-Graindorge M, Ripoll L. Environ Sci Pollut Res Int, 15 Sept 2026, DOI 10.1007/s11356-026-38214-9; Regulation (EC) 1223/2009, Annex II', '[]'::jsonb, '2026-09-25'::date, '06:00', 'posted', '[]'::jsonb, 0, '{"linkedin":{"id":"urn:li:share:7509016518131666944","at":"2026-09-25 06:30 MYT","url":"https://www.linkedin.com/feed/update/urn:li:share:7509016518131666944","via":"ws.regulab Studio"}}'::jsonb, '2026-09-25 06:30:00+08'::timestamptz, now(), '2026-09-22T00:34:52.319Z'::timestamptz) on conflict (id) do nothing;  -- vytcj4zi45 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('1c684b21-3e29-5ca1-82c1-79a0d711f5e8'::uuid, '1f249418-867a-5f46-ac5b-ed5b02345a1f'::uuid, 'regulab', 'kajian_kes', null, 'bm', 'Nama jenama ini bunyi Eropah. Pembungkusan kemas. Produk ini bernotifikasi dengan NPRA. Ia tetap kena batal.', '{"bm":{"instagram":"Nama jenama ini bunyi Eropah. Pembungkusan kemas. Produk ini bernotifikasi dengan NPRA. Ia tetap kena batal.\n\nRemy Laure Soothing Cream dibatalkan notifikasinya oleh NPRA pada 24 Ogos 2026 kerana kandungan hydroquinone, mengikut senarai Pembatalan Produk Kosmetik Bernotifikasi\n\nKes ini berbeza daripada kes krim ''herba'' biasa, di mana nama nampak tempatan, pembungkusan murah, tiada notifikasi langsung. Di sini semua tiga tanda tu wujud: nama Eropah, pembungkusan profesional, notifikasi ada. Tapi tiada satu pun daripadanya kawalan sebenar.\n\nYang menentukan cuma satu: apa yang sebenarnya ada dalam tiub. Cara pasti untuk tahu ialah ujian pengesahan bebas ke atas produk siap, bukan spesifikasi formula di atas kertas.\n\nPeruncit: jangan letak ''jenama ini nampak established'' sebagai kriteria penilaian pembekal. Ia tak bawa maklumat tentang pematuhan.","facebook":"European sounding name. Pembungkusan kemas. Notifikasi ada. Remy Laure Soothing Cream tetap dibatalkan oleh NPRA pada 24 Ogos 2026 sebab hydroquinone\n\nTiga tanda kredibiliti tu semua wujud. Tiada satu pun jadi kawalan. Yang tentukan cuma satu: apa dalam tiub, dan itu hanya boleh disahkan melalui ujian makmal ke atas produk siap.\n\nPeruncit: jangan jadikan ''nampak established'' sebahagian penilaian pembekal anda.","threads":"Nama Eropah. Pembungkusan kemas. Notifikasi ada. NPRA tetap batalkan Remy Laure Soothing Cream (24 Ogos 2026) sebab hydroquinone. Tiga tanda tu bukan kawalan. Yang tentukan: apa dalam tiub, disahkan cuma melalui ujian makmal produk siap."}}'::jsonb, 'NPRA Notified Cosmetic Products Cancellation list, 24 August 2026', '[]'::jsonb, '2026-09-23'::date, '08:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab1b0b71177eabccaf0a3a0","at":"2026-09-22 06:33 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab1b0c8826cfc54b85d8f76","at":"2026-09-22 06:33 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab1b0d7826cfc54b85d9034","at":"2026-09-22 06:33 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-22 06:33:00+08'::timestamptz, now(), '2026-09-20T09:39:09.286Z'::timestamptz) on conflict (id) do nothing;  -- w23i9gjqy1 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('b2f830a2-9d94-536a-84ba-ad99409fe688'::uuid, '26133716-4931-54da-b1eb-0b403d012b5b'::uuid, 'regulab', 'farmaseutikal', null, 'bm', 'Ramai PRH kecil masih ingat Label Keselamatan tu hologram, tampal je siap. Dah tak macam tu dah.', '{"bm":{"instagram":"Ramai PRH kecil, pengilang dan pengimport masih anggap Label Keselamatan tu cuma hologram cetak yang ditampal atas kotak. Tampal, siap, hantar pasaran.\n\nSekarang tak boleh macam tu.\n\nDi bawah Direktif Bilangan 19 Tahun 2026 (rujukan NPRA.600-1/9/13(13)Jld.2), dikeluarkan oleh Pengarah Perkhidmatan Farmasi bawah Peraturan 29, Peraturan-Peraturan Kawalan Dadah dan Kosmetik 1984, setiap Label Keselamatan pada produk berdaftar (ubat, produk tradisional, suplemen kesihatan) kena lalui Modul Label Assignment elektronik KKM dulu. Nombor siri unik pada label tu kena dihubungkan secara digital kepada produk berkenaan dalam sistem, dan proses ni WAJIB selesai sebelum produk keluar pasaran.\n\nIni tak terpakai kepada kosmetik yang dinotifikasi, hanya keluaran berdaftar dengan Pihak Berkuasa Kawalan Dadah.\n\nPRH bertanggungjawab penuh atas ketepatan pemetaan nombor siri. Ada Label Reassignment untuk pembetulan, ada Label Deactivation bila label dah tak sah. Satu benda tegas: label yang dah dipakai tak boleh diguna semula pada produk lain, tak boleh dipindah milik, tak boleh dijual.\n\nJadi walaupun kandungan produk anda takde masalah pun, kalau Label Assignment belum dibuat sebelum produk dipasarkan, itu dah jadi isu pematuhan sendiri. Bukan lagi soal produk, tapi soal proses.","facebook":"Ramai PRH ingat Label Keselamatan tu sekadar hologram yang ditampal, siap terus.\n\nDi bawah Direktif Bilangan 19 Tahun 2026 (NPRA.600-1/9/13(13)Jld.2), setiap label pada produk berdaftar (ubat, produk tradisional, suplemen kesihatan) kena lalui Modul Label Assignment digital dulu, nombor siri disahkan sistem, sebelum produk boleh dipasarkan.\n\nLabel yang dah dipakai tak boleh diguna semula, tak boleh dijual atau dipindah milik. PRH yang bertanggungjawab atas ketepatan pemetaan tu.\n\nProduk elok pun, kalau proses ni tak buat, itu dah jadi isu berasingan.","threads":"Label Keselamatan bukan hologram tampal sahaja lagi.\n\nDirektif 19/2026 (NPRA.600-1/9/13(13)Jld.2) wajibkan Label Assignment digital, nombor siri disahkan sistem, sebelum produk berdaftar dipasarkan. Label lama tak boleh diguna semula atau dijual.\n\nProduk elok pun, proses ni gagal, jadi isu sendiri."}}'::jsonb, 'NPRA Direktif Bilangan 19 Tahun 2026, rujukan NPRA.600-1/9/13(13)Jld.2, di bawah Peraturan 29 Peraturan-Peraturan Kawalan Dadah dan Kosmetik 1984', '[]'::jsonb, '2026-09-24'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6ab301a3340f92dcbe178162","at":"2026-09-23T06:31 MYT","via":"ws.regulab Studio"},"instagram":{"id":"6ab301b0b00ec2bfabd3c6fd","at":"2026-09-23T06:31 MYT","via":"ws.regulab Studio"},"threads":{"id":"6ab301ba64b56fca2b9d2261","at":"2026-09-23T06:31 MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-23 06:31:00+08'::timestamptz, now(), '2026-09-20T09:33:32.377Z'::timestamptz) on conflict (id) do nothing;  -- y9bs3cciyb (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('69726075-1c22-51f4-8a9a-84b7972aeef6'::uuid, 'dbd80c13-3940-569c-8c92-3ff0793fb03c'::uuid, 'regulab', 'makanan', null, 'bm', 'Perbezaan “Best Before” lawan “Use By” yang semua orang ulang itu datang dari undang-undang EU, bukan Malaysia.', '{"bm":{"instagram":"Ini satu daripada perkara yang paling kerap disalin bulat-bulat: perbezaan \"Best Before\" lawan \"Use By\", di mana satu kononnya soal kualiti dan satu lagi soal keselamatan.\n\nPerbezaan itu betul, tapi ia datang dari undang-undang pelabelan EU dan UK. Ia bukan skim di bawah undang-undang Malaysia.\n\nPeraturan 14, Peraturan-Peraturan Makanan 1985 (P.U.(A) 437/85) letak dua istilah, dan kedua-duanya dibina sekitar quality attributes, bukan keselamatan:\n\nExpiry date ialah tarikh selepas mana makanan itu, bila disimpan mengikut syarat penyimpanan pada labelnya, mungkin tidak lagi mengekalkan quality attributes yang lazimnya dijangka oleh pengguna.\n\nDate of minimum durability ialah tarikh sehingga mana makanan itu, bila disimpan mengikut syarat penyimpanan pada labelnya, akan mengekalkan sifat tertentu yang dituntut secara tersurat atau tersirat.\n\nKesannya untuk SME cukup praktikal. Kalau anda ambil rangka EU dan letak \"Use By\" pada produk untuk pasaran Malaysia sambil ingat itu penanda keselamatan yang sah di sisi undang-undang, anda sedang bina label atas rangka yang salah negara. Dan kalau anda pula anggap semua tarikh pada pek makanan Malaysia adalah tarikh keselamatan, anda sedang salah faham takrif dalam peraturan sendiri.\n\nYang betul: mula dari Peraturan 14, bukan dari pek import yang anda jadikan rujukan reka bentuk pembungkusan.","facebook":"Perbezaan \"Best Before\" dan \"Use By\" yang anda selalu baca itu datang dari undang-undang EU dan UK. Ia bukan skim Malaysia.\n\nPeraturan 14, Peraturan-Peraturan Makanan 1985 letak dua istilah: expiry date dan date of minimum durability. Dan kedua-duanya ditakrif sekitar quality attributes, bukan keselamatan. Expiry date ialah tarikh selepas mana makanan mungkin tidak lagi mengekalkan kualiti yang lazimnya dijangka pengguna. Date of minimum durability ialah tarikh sehingga mana makanan mengekalkan sifat tertentu yang dituntut.\n\nJadi kalau anda salin format label dari pek Eropah dan letak \"Use By\" pada produk Malaysia sambil ingat itu penanda keselamatan sah di sisi undang-undang, anda sedang guna rangka yang salah negara.\n\nSemak date marking produk anda terhadap Peraturan 14, bukan terhadap pek import yang anda jadikan rujukan reka bentuk.","threads":"Perbezaan \"Best Before\" lawan \"Use By\" yang semua orang ulang itu datang dari undang-undang EU dan UK, bukan Malaysia. Peraturan 14, Peraturan-Peraturan Makanan 1985 letak dua istilah: expiry date dan date of minimum durability, dan kedua-duanya ditakrif sekitar quality attributes, bukan keselamatan. Jangan bina label Malaysia atas rangka negara lain."}}'::jsonb, 'Peraturan-Peraturan Makanan 1985 (P.U.(A) 437/85), Peraturan 14 — penandaan tarikh: ''date marking'' bermaksud tarikh yang menandakan expiry date atau date of minimum durability; ''expiry date'' ditakrifkan sebagai tarikh selepas mana makanan itu mungkin tidak lagi mengekalkan quality attributes yang lazimnya dijangka oleh pengguna, dan ''date of minimum durability'' sebagai tarikh sehingga mana makanan itu akan mengekalkan sifat tertentu yang dituntut secara tersurat atau tersirat.', '[]'::jsonb, '2026-09-17'::date, '21:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa61729f7b1958d5cdc2fa6","at":"13 Sep 2026, 11:23 AM MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa61736eba7bc56778b05c9","at":"13 Sep 2026, 11:23 AM MYT","via":"ws.regulab Studio"},"threads":{"id":"6aa6173fbcabda92e1a38a30","at":"13 Sep 2026, 11:23 AM MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-17 21:00:00+08'::timestamptz, now(), '2026-09-08T12:34:51.279Z'::timestamptz) on conflict (id) do nothing;  -- yfiozfjh93 (posted)
insert into public.semasa_posts (id, idea_id, stream, domain, angle, lang, hook, text, citation, slides, date, slot, status, flags, hard_flags, published, posted_at, archived_at, created_at) values ('d7526ea0-093b-5eba-b8ad-dff36b3e516e'::uuid, 'c694978d-384d-593c-b0bf-eac36c8e6229'::uuid, 'regulab', 'halal_my', null, 'bm', 'Pelanggan tanya ''mana logo halal'' hari keempat anda jual. Tempoh siap yang anda cari tu memang tiada dalam manual.', '{"bm":{"instagram":"Usahawan baru, kurang dua bulan berniaga, kena tanya pelanggan kenapa produk dia takda logo halal. Soalan yang sama berulang setiap bulan.\n\nRamai founder baru anggap bahan halal semua bermakna logo keluar cepat. Tak macam tu. Dan yang menarik, tempoh yang semua orang cari tu memang tiada dalam manual.\n\nMPPHM (Domestik) 2020 tak senaraikan tempoh siap ikut kategori produk. Prosedur 21(13) sebut tempoh semakan bergantung pada jumlah produk atau menu dan premis yang dimohon. Prosedur 27(4) pula letak tempoh pengauditan kecukupan di bawah piagam pelanggan pihak berkuasa berwibawa, iaitu di luar manual. Maknanya sesiapa yang bagi anda angka bulan yang tepat sebelum tengok fail anda, dia meneka.\n\nYang manual memang kunci ialah tempoh di pihak anda. Dokumen sokongan lengkap dalam 5 hari bekerja selepas borang MYeHALAL dihantar, ikut Prosedur 21(6). Bayaran fi dalam 14 hari bekerja selepas terima surat fi, ikut Prosedur 21(14). Lewat di dua titik tu, anda sendiri yang panjangkan proses.\n\nSelebihnya lalu beberapa lapisan: daftar dan hantar permohonan di MYeHALAL, dokumen sokongan pembekal bagi setiap bahan, premise inspection, audit, baru keputusan.\n\nJangan letak apa-apa simbol atau perkataan halal pada label sebelum ada nombor sijil sah. Kos tarik balik produk lebih mahal daripada tunggu proses.","facebook":"Pelanggan tanya \"mana logo halal\" pada hari keempat anda jual. Bukan salah pelanggan. Salah jangkaan.\n\nBahan halal semua tak bermakna logo keluar laju, dan tempoh yang anda cari tu memang tiada dalam manual. MPPHM (Domestik) 2020 tak senaraikan tempoh siap ikut kategori produk. Prosedur 21(13) sebut tempoh semakan bergantung pada jumlah produk atau menu dan premis yang dimohon. Prosedur 27(4) pula letak tempoh pengauditan kecukupan di bawah piagam pelanggan pihak berkuasa berwibawa, bukan dalam manual itu sendiri.\n\nYang manual memang tetapkan ialah jam di pihak anda. Dokumen sokongan lengkap dalam 5 hari bekerja selepas borang MYeHALAL dihantar, ikut Prosedur 21(6). Bayaran fi dalam 14 hari bekerja selepas terima surat fi, ikut Prosedur 21(14).\n\nJangan letak perkataan halal pada label sebelum ada nombor sijil sah.","threads":"Pelanggan tanya \"mana logo halal\" hari keempat anda jual. Bahan halal semua tak bermakna logo keluar laju. MPPHM (Domestik) 2020 pun tak letak tempoh siap ikut kategori: Prosedur 21(13) kata tempoh semakan ikut jumlah produk dan premis yang dimohon. Yang manual kunci ialah jam anda sendiri, dokumen sokongan 5 hari bekerja dan bayaran fi 14 hari bekerja."}}'::jsonb, 'Manual Prosedur Pensijilan Halal Malaysia (Domestik) 2020, JAKIM — Prosedur 21(6), 21(13), 21(14); Prosedur 27(4).', '[]'::jsonb, '2026-09-15'::date, '13:00', 'posted', '[]'::jsonb, 0, '{"facebook":{"id":"6aa874179dd9674a3dc6880b","at":"15 Sep 2026, 6:25 AM MYT","via":"ws.regulab Studio"},"instagram":{"id":"6aa7db654fdc747eb03a4168","at":"2026-09-14T19:35:00+08:00","via":"ws.regulab Studio"},"threads":{"id":"6aa8742f9dd9674a3dc68ad3","at":"15 Sep 2026, 6:25 AM MYT","via":"ws.regulab Studio"}}'::jsonb, '2026-09-15 13:00:00+08'::timestamptz, now(), '2026-09-07T09:54:50.152Z'::timestamptz) on conflict (id) do nothing;  -- ylur8ndu9l (posted)
